  ('cpiuris2025::b04ce5274246dde66bf8a4754d4c13e4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsificação', '## Falsificação

O crime de falsificação é formal e não admite tentativa, sendo comprovado por outros meios de prova. Não há vestígios materiais, mas a função do funcionário público pode majorar a pena.

### Conceitos
- **Falsificação**: Ação ou omissão que visa alterar ou substituir um documento
- **Tentativa**: Não é admitida na forma omissiva
- **Vestígios materiais**: Não há, pois o documento é materialmente verdadeiro
- **Pena majorante**: Um sexto quando o crime é cometido por funcionário público

### Referências legais
- Art. 283 do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pegar a diferença entre tentativa e omissão
- Entender que a função do funcionário público pode majorar a pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.272 (2)", "page_number": 272, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 283 do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T10:44:23.643317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=272", "doc_key": "b04ce5274246dde66bf8a4754d4c13e4"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b3754b5ae5f9c4dfa6e0dbba957bf059ec1ae9ccd81ba8af4b63ba71139ffce9'),
  ('cpiuris2025::cb4488981f45459c052941a070a90cdc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falso Reconhecimento de Firma ou Letra', '## Falso Reconhecimento de Firma ou Letra

Crime de médio potencial ofensivo, com possibilidade de suspensão condicional do processo e acordo de não persecução penal. Implica reconhecer firma ou letra que não é verdadeira em exercício de função pública.

### Conceitos
- **Falso Reconhecimento**: Reconhecer firma ou letra que não é verdadeira em exercício de função pública
- **Crimes contra a Fé Pública**: Crime cometido contra a fé pública, como falsidade documental
- **Dolo**: Elemento subjetivo do tipo, não se admite modalidade culposa
- **Consumação Formal**: A consumação independe de dano eventualmente causado pelo falso reconhecimento
- **Ação Penal Pública Incondicionada**: A ação penal é pública incondicionada, sem necessidade de denúncia

### Referências legais
- Art. 300 do Código Penal

### Dicas de prova
- Reconhecer firma ou letra que não é verdadeira em exercício de função pública
- Diferenciar entre falso intelectual e falsificação de documento público ou particular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.273 (1)", "page_number": 273, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 300 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:45:07.244964+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=273", "doc_key": "cb4488981f45459c052941a070a90cdc"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c8c0388a760a22647a71d18858f2dda9b93cb533ec380b35567b9cd8a016eedb'),
  ('cpiuris2025::650301a1815b2dc9f34f0a6c1a2d196f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsidade Ideológica', '## Falsidade Ideológica

O funcionário que afirma a verdade de um fato ou circunstância contida em documento público sem conhecimento pessoal comete falsidade ideológica. A expressão ''ou qualquer outra vantagem'' deve ser interpretada de maneira restritiva, considerando-se a natureza pública do proveito.

### Conceitos
- **Falsidade Ideológica**: Cometimento de afirmação falsa de fato ou circunstância contida em documento público
- **Documento Público**: O que tem natureza pública e é assinado por autoridade pública

### Referências legais
- Art. 301 do Código Penal

### Dicas de prova
- Distinção entre falsidade ideológica e falsidade qualificada
- Interpretação restritiva da expressão ''ou qualquer outra vantagem''', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.273 (2)", "page_number": 273, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 301 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:45:27.998364+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=273", "doc_key": "650301a1815b2dc9f34f0a6c1a2d196f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'fcc078d69680ececaad978d25a814d7ef7fba0d68e26457d77df135743eaa716'),
  ('cpiuris2025::0e3f137197305b95231c677979c84557', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsidade Documental', '## Falsidade Documental

O crime de falsidade documental é próprio e somente pode ser praticado por quem ocupa função pública, basta que se valha das facilidades proporcionadas pelo cargo. O elemento subjetivo do tipo é o dolo, e não se admite a forma culposa.

### Conceitos
- **Falsidade Documental**: O crime de falsidade documental é próprio e somente pode ser praticado por quem ocupa função pública.
- **Dolo**: O elemento subjetivo do tipo, que não se admite a forma culposa.
- **Forma Culposa**: Não é aceita como forma de cometer o crime.

### Referências legais
- Art. 302 do Código Penal

### Dicas de prova
- Pegar a diferença entre falsidade material e formal.
- Entender que o crime de falsidade documental é próprio e somente pode ser praticado por quem ocupa função pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.274 (1)", "page_number": 274, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 302 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:45:58.646989+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=274", "doc_key": "0e3f137197305b95231c677979c84557"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b5219177cd118a4d990229d83b471a531de1950d7ba14217a3dbd9fe27633765'),
  ('cpiuris2025::d8372fe808fec1180fc8068c02318cb2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsidade Ideológica', '## Falsidade Ideológica

O crime de falsidade ideológica é cometido por profissionais que utilizam atestados falso, sendo o beneficiário do documento ciente da sua origem e comete o crime do art. 304 do CP.

### Conceitos
- **Falsidade Ideológica**: uso de documentos falsos para obter vantagem
- **Atestado Falso**: documento que não tem base na realidade
- **Coautoria e Participação**: formas em que o crime pode ser cometido
- **Consumação Antecipada**: o crime se consuma no momento da entrega do documento falso

### Referências legais
- Art. 299
- Art. 304

### Dicas de prova
- Distinção entre o beneficiário e o profissional que utiliza o atestado falso
- Formas de coautoria e participação no crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.274 (2)", "page_number": 274, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 299", "Art. 304"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:46:31.363769+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=274", "doc_key": "d8372fe808fec1180fc8068c02318cb2"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e3a5c38875acccc562835c2365266d36867444939a0b70ab499388326337b332'),
  ('cpiuris2025::75e6251c8739227e555eb620fae0e61e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Fé Pública', '## Crimes contra a Fé Pública

Os crimes contra a fé pública são formais e não requerem resultado naturalístico para a consumação. A conduta já expõe o bem jurídico a perigo, como no caso de um médico servidor público que emite um atestado falso.

### Conceitos
- **Formalidade**: A característica de ser formal, não sendo necessária a obtenção de vantagem ou proveito para a consumação do crime.
- **Consumação**: O momento em que o crime é completado, independentemente da obtenção de resultado naturalístico.
- **Falsidade documental**: A produção de um documento falso ou alterado com o objetivo de ludibriar alguém.
- **Corrupção passiva**: O crime de aceitar promessa de vantagem para emitir atestado falso, previsto no art. 317 do CP.
- **Equívoco**: Uma situação em que a conduta não é considerada crime, pois não há intenção de ludibriar alguém.
- **Ação penal pública incondicionada**: O direito do Estado de processar e punir um indivíduo sem a necessidade de uma denúncia específica.
- **Parasitário**: Um crime que depende da prática de outro crime anterior para se consumir.
- **Fusão ou acessório**: Uma situação em que a conduta do usuário do documento falso depende da prática de um crime anterior.

### Referências legais
- Art. 317 do CP
- Art. 39 da Lei n.º 6.538/1978

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte sobre a formalidade dos crimes contra a fé pública e como ela afeta a consumação do crime.
- Entenda a diferença entre corrupção passiva e equívoco.
- Conheça a tipicidade dos crimes contra a fé pública e como ela é influenciada pela falsidade documental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.275 (1)", "page_number": 275, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 317 do CP", "Art. 39 da Lei n.º 6.538/1978"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T10:47:18.694485+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=275", "doc_key": "75e6251c8739227e555eb620fae0e61e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '5e2cbc74421ae2658b22ad3d1d15e22835ce2df23a120ae652268f733c7463a9'),
  ('cpiuris2025::7056e5401bd7b5d581823feb186cf4d7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsidade Documental', '## Falsidade Documental

A falsidade documental não é crime se o documento não for utilizado para atingir efeitos jurídicos.

### Conceitos
- **Falsidade Documental**: O uso de documentos falsos com objetivo de produzir efeitos jurídicos
- **Crime Possível**: Crime que não pode ser cometido devido à ausência de potencial lesivo na conduta
- **Documento Falso**: Um documento que não é autêntico ou que contém informações falsas

### Referências legais
- Art. 17 do CP

### Dicas de prova
- Distinção entre o uso de documentos falsos e a simples posse ou porte
- Importância da intenção do agente no crime de falsidade documental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.275 (2)", "page_number": 275, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 17 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:47:38.350078+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=275", "doc_key": "7056e5401bd7b5d581823feb186cf4d7"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '256ab706b4fb8701f42506f0257a873e3033a2a56530f790ffbda18f8db892c6'),
  ('cpiuris2025::a8c1cc43958fdf5f94ca4a3f92ddd7df', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Tipicidade da conduta no crime contra a fé pública', '## Tipicidade da conduta no crime contra a fé pública

A tipicidade da conduta no crime contra a fé pública, especialmente na Carteira Nacional de Habilitação, é discutida. O STJ adotou entendimento que a configuração do delito pressupõe a efetiva utilização do documento falso e sua apresentação como autêntico.

### Conceitos
- **conduta**: ato ou omissão que caracteriza o crime
- **tipicidade**: característica da conduta que a torna criminosa
- **Carteira Nacional de Habilitação**: documento obrigatório para dirigir
- **documento falso**: documento que imita o original, mas não tem a mesma qualidade ou autenticidade

### Referências legais
- Art. 304 do CP
- Súmula 347/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: apresentação de documento falso à autoridade pública

### Dicas de prova
- Entenda a tipicidade da conduta no crime contra a fé pública
- Conheça o entendimento do STJ sobre a apresentação de documento falso à autoridade pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.276 (1)", "page_number": 276, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 304 do CP", "Súmula 347/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: apresentação de documento falso à autoridade pública"], "confidence": 0.8, "extracted_at": "2026-05-27T10:48:22.642146+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=276", "doc_key": "a8c1cc43958fdf5f94ca4a3f92ddd7df"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '037e5365bdf08a2e494326f56674df9d947eac26771b66bc23604d27cdf7bb81'),
  ('cpiuris2025::29d17ec2d58052d761d147f820becfa4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Uso de documento falso', '## Uso de documento falso

O uso de documento falso não se legitima pela autodefesa e é post factum impunível, absorvido pela falsificação. A competência para processar e julgar o crime é da Justiça Estadual.

### Conceitos
- **Autodefesa**: uso de documento falso para proteger seus interesses pessoais
- **Falsificação**: criação de um documento falso com o objetivo de enganar alguém
- **Competência da Justiça Estadual**: competência para processar e julgar o crime de uso de documento falso

### Referências legais
- Art. 147, § 2º do Código Penal
- Súmula 546 do STJ

### Jurisprudência
- CC 128.923/SE
- CC 148.592/RJ

### Dicas de prova
- Distinguir entre autodefesa e uso de documento falso
- Entender a competência da Justiça Estadual em relação ao crime de uso de documento falso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.276 (2)", "page_number": 276, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 147, § 2º do Código Penal", "Súmula 546 do STJ"], "jurisprudence": ["CC 128.923/SE", "CC 148.592/RJ"], "confidence": 0.8, "extracted_at": "2026-05-27T10:48:47.995337+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=276", "doc_key": "29d17ec2d58052d761d147f820becfa4"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8b1e1d5d9611470bcc8e622b1c93caef74c3f45c62050d71d6af1ef353a080aa'),
  ('cpiuris2025::fd49efb2be05ab644aea44b8dbde5568', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Competência para julgar crimes contra a fé pública', '## Competência para julgar crimes contra a fé pública

A competência para julgar crimes contra a fé pública é definida em razão do órgão expedidor ou do órgão a quem o documento foi apresentado. A competência para julgar o uso de documento falso é da Justiça Federal do local onde o delito se consumou.

### Conceitos
- **Competência**: A definição da competência é um critério jurídico que determina a autoridade judiciária competente para processar e julgar uma ação ou processo.
- **Falsificação**: Falsificação é o ato de criar ou alterar um documento com o objetivo de enganar alguém.
- **Órgão expedidor**: O órgão expedidor é a entidade que emite ou expede um documento.
- **Entidade a quem o documento foi apresentado**: A entidade a quem o documento foi apresentado é a pessoa jurídica ou física que recebeu o documento.

### Referências legais
- Art. 305 do Código Penal
- Súmula 200 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: competência para julgar crimes contra a fé pública

### Dicas de prova
- Pergunte sobre a definição de competência e como ela se aplica aos crimes contra a fé pública.
- Entenda a diferença entre órgão expedidor e entidade a quem o documento foi apresentado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.277 (1)", "page_number": 277, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 305 do Código Penal", "Súmula 200 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: competência para julgar crimes contra a fé pública"], "confidence": 0.8, "extracted_at": "2026-05-27T10:49:28.722929+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=277", "doc_key": "fd49efb2be05ab644aea44b8dbde5568"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a141dbcd046fe37d43305fd8f67626e8a76b9e05f82926604ce12cb41c27c912'),
  ('cpiuris2025::808a9021e071f910ff36991d9e7484d9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Destruição, Supressão e Ocultação', '## Destruição, Supressão e Ocultação

A destruição, supressão ou ocultação de documento é tipificada se o documento for verdadeiro, público ou particular.

### Conceitos
- **Destruir**: Eliminar com uso de fogo
- **Suprimir**: Fazer desaparecer sem destruir
- **Ocultar**: Esconder, equivalente a esconder

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferenciar entre destruição e supressão/ocultação
- Verificar se o documento é verdadeiro, público ou particular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.277 (2)", "page_number": 277, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:49:58.439214+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=277", "doc_key": "808a9021e071f910ff36991d9e7484d9"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '07c0447e81bd16d490ee0368fedb3b77182f2eb6e4a95bc3fab46fa977f87667'),
  ('cpiuris2025::b916b11b7b7b48736c4fa85e08626912', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Fé Pública: Falsidade Documental', '## Crimes contra a Fé Pública: Falsidade Documental

O crime de falsidade documental é comum, geral e formal, podendo ser praticado por qualquer pessoa. O elemento subjetivo é o dolo, com benefício próprio ou de outrem e prejuízo alheio. A pena é pública incondicionada.

### Conceitos
- **Falsidade Documental**: O crime de falsificação de documento
- **Princípio da Alteridade**: O princípio que afirma que o crime não prejudica terceiros, exceto aqueles a quem ele diz respeito
- **Dolo**: O elemento subjetivo do tipo penal, consistente em benefício próprio ou de outrem e prejuízo alheio
- **Benefício Próprio**: A vantagem que o agente busca obter com a prática do crime
- **Prejuízo Alheio**: O dano causado a outrem pela prática do crime

### Referências legais
- Art. 298 do CP
- Art. 356 do CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunta sobre o crime de falsidade documental e a aplicação do princípio da alteridade
- Entenda a diferença entre benefício próprio e prejuízo alheio no contexto do dolo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.278", "page_number": 278, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 298 do CP", "Art. 356 do CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T10:50:32.664114+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=278", "doc_key": "b916b11b7b7b48736c4fa85e08626912"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '4c31fe1fb45fe360b0766cbc2f99d7580c435477430bc7fa7e27034b7887987e'),
  ('cpiuris2025::9a9bcc920d66e3025122c0d8f7746333', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsificação de marca ou sinal empregado pelo poder público', '## Falsificação de marca ou sinal empregado pelo poder público

O crime de falsificação de marca ou sinal empregado pelo poder público é comum e formal, podendo ser praticado por qualquer pessoa. A pena é de reclusão de dois a seis anos, com multa. Exige título doloso.

### Conceitos
- **Falsificação**: Ação de alterar ou fabricar uma marca ou sinal para enganar alguém
- **Marca ou sinal**: Elemento que serve de alerta para reconhecer ou conhecer algo
- **Contraste de metal precioso**: Marca feita no metal, indicadora de peso e quilate
- **Fiscalização alfandegária**: Representação gráfica utilizada para demonstrar que uma mercadoria foi liberada ou passou por um controle de entrada ou saída do país

### Referências legais
- Art. 306 do Código Penal

### Dicas de prova
- Pergunte sobre a diferença entre marca e sinal, e como eles são utilizados no crime de falsificação
- Entenda que o crime é comum e formal, e que a pena pode variar dependendo da gravidade do erro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.280", "page_number": 280, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 306 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:51:07.258705+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=280", "doc_key": "9a9bcc920d66e3025122c0d8f7746333"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '41d6d8aa9fc9acbd9348d97a7f5eaed6295fafd200fc0c59847955f5a32bc108'),
  ('cpiuris2025::82c314e31e330c32725fcd47ac87817e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsidade Pública', '## Falsidade Pública

O crime de falsidade pública inclui a atribuição de falsa identidade, o uso de documento falso e a fraude de lei sobre estrangeiro. A conduta do art. 307 se diferencia da do art. 304 pela ausência de apresentação de documento falso.

### Conceitos
- **Falsa Identidade**: Atribuição de identidade falsa a si mesmo ou a terceiro
- **Uso de Documento Falso**: Presentação de documento falso para obter vantagem ou causar dano a outrem
- **Falsidade Pública**: Conduita que vicia a fé pública, seja por meio de falsa identidade, uso de documento falso ou fraude de lei sobre estrangeiro
- **Dolo**: Elemento subjetivo do crime, consistente em intenção de obter vantagem ou causar dano a outrem
- **Consumação**: O momento em que a identidade falsa é atribuída a si ou a terceiro
- **Ação Penal**: É pública incondicionada, o que significa que não há limites de tempo para a ação penal

### Referências legais
- Art. 307 do CP
- Art. 304 do CP
- Súmula 522/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: fraude de lei sobre estrangeiro

### Dicas de prova
- Pegadinha ou distinção relevante para prova
- Entenda a diferença entre falsa identidade e uso de documento falso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.281", "page_number": 281, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 307 do CP", "Art. 304 do CP", "Súmula 522/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: fraude de lei sobre estrangeiro"], "confidence": 0.8, "extracted_at": "2026-05-27T10:52:00.850646+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=281", "doc_key": "82c314e31e330c32725fcd47ac87817e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8fa470a3934b3c5ee10b6e69f10ab09e07c3766c85c8db8978ced0161316070d'),
  ('cpiuris2025::ba4b307d01510b217ebbfbffef697ef8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsidade em prejuízo da nacionalização de sociedade', '## Falsidade em prejuízo da nacionalização de sociedade

Delitos contra a fé pública, incluindo o uso de falso nome para entrar no território nacional e a falsificação de propriedade de bens estrangeiros.

### Conceitos
- **Falsidade**: falsa representação ou declaração
- **Nacionalização de sociedade**: restringir a propriedade ou posse de empresas a brasileiros natos ou naturalizados
- **Dolo**: intenção de agir com determinado fim
- **Consumação**: efetivo uso do nome pelo estrangeiro
- **Formalidade**: característica do crime que não exige a consumação para sua tipificação

### Referências legais
- Art. 309 da CP
- Art. 304 da CP

### Dicas de prova
- Distinção entre crimes contra a fé pública e falsidade em prejuízo da nacionalização de sociedade
- Importância do dolo na tipificação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.282 (1)", "page_number": 282, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 309 da CP", "Art. 304 da CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:52:30.092136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=282", "doc_key": "ba4b307d01510b217ebbfbffef697ef8"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b95e1927855376c957f10567c82ac05a741a4de050e9cd824cb2d5013554ad25'),
  ('cpiuris2025::d4a67adb29b7ae88ae4fe8524d332393', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Concurso Necessário', '## Concurso Necessário

Crime de concurso necessário: indivíduo se passa por proprietário para encobrir o verdadeiro dono estrangeiro.

### Conceitos
- **Concurso Necessário**: Obrigação de ter um coautor ou cúmplice para que o crime possa ser cometido.
- **Proprietário Falso**: Indivíduo que se passa por proprietário para encobrir o verdadeiro dono do bem.
- **Estrangeiro**: Pessoa não nascida no Brasil, cujo bem é encoberto pelo indivíduo falso proprietário.
- **Consumação Antecipada**: O crime é formal e pode ser consumado antes de sua configuração.
- **Intuito de Lucro**: Valor que pode ser atribuído à dosimetria da pena em caso de concurso necessário.

### Referências legais
- Art. 109, IV, CF/88; Art. 59 do CP

### Dicas de prova
- Distinção entre concurso necessário e concurso eventual.
- Importância da prova da identidade do verdadeiro dono do bem.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.282 (2)", "page_number": 282, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 109, IV, CF/88; Art. 59 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:52:56.556895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=282", "doc_key": "d4a67adb29b7ae88ae4fe8524d332393"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e5e873247827c5f58b14e31d37233c41d7df509b8bb4be27d776500c0b686159'),
  ('cpiuris2025::c6bc8f1fe73a39fb346110fdf44f1cb7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Adulteração de Sinal Identificador de Veículo Automotor', '## Adulteração de Sinal Identificador de Veículo Automotor

A adulteração de sinal identificador de veículo automotor é crime previsto no art. 311 do CP, que consiste em alterar ou suprimir números de chassi, placa de identificação ou outros sinais identificadores sem autorização. A pena é de reclusão de 3 a 6 anos e multa.

### Conceitos
- **Adulteração**: alterar ou suprimir sinal identificador de veículo automotor
- **Sinal Identificador**: número de chassi, placa de identificação ou outros sinais que caracterizam o veículo
- **Veículo Automotor**: veículo a motor de propulsão que circula por seus próprios meios
- **Fé Pública**: bem jurídico tutelado na proteção da propriedade e da segurança no registro e identificação do automóvel

### Referências legais
- Art. 311 do Código Penal
- Lei nº 9.503/97

### Jurisprudência
- Súmula 62 do STF

### Dicas de prova
- Distinção entre crime e infração administrativa
- Importância da autenticidade dos sinais identificadores de veículo automotor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.283 (1)", "page_number": 283, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 311 do Código Penal", "Lei nº 9.503/97"], "jurisprudence": ["Súmula 62 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T10:53:42.370136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=283", "doc_key": "c6bc8f1fe73a39fb346110fdf44f1cb7"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '5fbff2c523c1ae0e112eb3d16dcef213d67ac68f9cb20e2e2d708b19b66b0dbc'),
  ('cpiuris2025::018f8f6a87f19f81933d8325488b0002', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Adulteração de placa de veículo', '## Adulteração de placa de veículo

A Corte não aceitou a interpretação de que a adulteração de placa de veículo é mera irregularidade administrativa, mas sim um crime, pois o objetivo do agente era frustrar a fiscalização e atingir o bem jurídico protegido pela norma penal.

### Conceitos
- **Adulteração**: alteração ilegal de placa de veículo
- **Falsidade**: falsa representação ou declaração
- **Dolo**: intenção de cometer um ato ilícito
- **Irregularidade administrativa**: conduta que não configura crime, mas pode ser punida por meio de medidas disciplinares

### Referências legais
- Art. 147 do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Destacar a existência de divergência na doutrina
- Entender que a adulteração não é mera irregularidade administrativa, mas sim um crime
- Reconhecer que o objetivo do agente era frustrar a fiscalização e atingir o bem jurídico protegido pela norma penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.283 (2)", "page_number": 283, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 147 do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T10:54:11.514005+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=283", "doc_key": "018f8f6a87f19f81933d8325488b0002"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8ab54b9e0fc853ee5b63908b3c0b93b01e0c6f308f96271910cfaa55c677be21'),
  ('cpiuris2025::37139e57ed20c355423e09c05df51bc9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsificação de veículos', '## Falsificação de veículos

O crime previsto no artigo é a falsificação ou adulteração de veículos, com o objetivo de evitar multas, pedágio, radares e restrição de circulação. O crime é formal e não depende de resultado naturalístico para sua consumação.

### Conceitos
- **Falsificação**: Ação de alterar ou modificar a identidade de um objeto, nesse caso, um veículo
- **Adulteração**: Ação de alterar ou modificar as características de um objeto, nesse caso, um veículo
- **Dolo**: O elemento subjetivo do crime, que é a intenção de cometer o crime

### Referências legais
- Art. 158 do CPP
- Art. 327 do CP
- Lei nº 14.562/2023

### Jurisprudência
- RE 123456

### Dicas de prova
- Pegar a diferença entre falsificação e adulteração
- Entender o conceito de dolo no contexto do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.284 (1)", "page_number": 284, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 158 do CPP", "Art. 327 do CP", "Lei nº 14.562/2023"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T10:54:41.975461+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=284", "doc_key": "37139e57ed20c355423e09c05df51bc9"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '9a04b6219a179203a5d0655aab9b8d273c0b88a45701cdf61ff91dca5b3f52d4'),
  ('cpiuris2025::24020a431a2400e931f9f62729c120c0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Utilização indevida de conteúdo sigiloso', '## Utilização indevida de conteúdo sigiloso

A figura típica prevista no art. 311-A envolve o uso indevido de informações sigilosas para beneficiar a si ou a outrem, comprometendo a credibilidade do certame, com pena de reclusão e multa.

### Conceitos
- **Utilização indevida**: Uso não autorizado de conteúdo sigiloso
- **Conteúdo sigiloso**: Informações protegidas por sigilo
- **Certame**: Competição ou processo em que participam pessoas qualificadas
- **Pena de reclusão**: Prisão por mais de 1 ano

### Referências legais
- Art. 311-A do Código Penal

### Dicas de prova
- Distinção entre uso indevido e acesso não autorizado
- Importância da proteção de conteúdo sigiloso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.284 (2)", "page_number": 284, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 311-A do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T10:55:15.380478+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=284", "doc_key": "24020a431a2400e931f9f62729c120c0"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '597c260f26aa92af3046d55eef3fc8dca2d06b575887cb058c7fe84d6b9bf9b8'),
  ('cpiuris2025::b512ee0ca47e34d0cb476b99f9aafca1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime contra a Fé Pública: FalSIDADES', '## Crime contra a Fé Pública: FalSIDADES

O crime de falsidade contra a fé pública é tipificado pela Lei n.º 12.550/2011, abrangendo condutas que não encontravam perfeita adequação em outros artigos do Código Penal. O crime se caracteriza por práticas de fraude em certames ou concurso de interesse público, com o objetivo de comprometer a credibilidade desses processos.

### Conceitos
- **Falsidade**: Ação que visa enganar ou prejudicar alguém
- **Crimes contra a Fé Pública**: Atos que visam comprometer a credibilidade de certames ou concurso de interesse público
- **Lei n.º 12.550/2011**: Lei que tipificou o crime de falsidade contra a fé pública
- **Tentativa**: Ação parcialmente realizada, sem a consumação do crime
- **Competência**: A competência da Justiça Estadual ou Federal para julgar o crime

### Referências legais
- Art. 311-A do Código Penal

### Jurisprudência
- RE 123456
- Súmula 345/STF

### Dicas de prova
- Distinguir entre a falsidade e os crimes contra a fé pública
- Entender o conceito de ''conteúdo sigiloso'' como elemento normativo do tipo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.285", "page_number": 285, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 311-A do Código Penal"], "jurisprudence": ["RE 123456", "Súmula 345/STF"], "confidence": 0.8, "extracted_at": "2026-05-27T10:55:51.615626+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=285", "doc_key": "b512ee0ca47e34d0cb476b99f9aafca1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd6966e9079f5e435c7176fcac31830cb38ba6c9b076e2dbbb0063faa335cd758'),
  ('cpiuris2025::e75635662e587420b19bb43aaff7ac46', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes Funcionais Próprios e Imprópios', '## Crimes Funcionais Próprios e Imprópios

O texto discute a distinção entre crimes funcionais próprios e imprópios, bem como a condição de funcionário público para fins penais.

### Conceitos
- **Crimes Funcionais Próprios**: São aqueles em que, se não houver a qualidade de funcionário público, a conduta se torna um indiferente penal.
- **Crimes Funcionais Imprópios**: Quando há o desaparecimento da qualidade especial de servidor público, o delito é desclassificado para outro tipo penal.
- **Condição de Funcionário Público**: É a qualidade que se comunica aos particulares que tiverem concorrido para o fato, sendo elementar dos crimes funcionais.

### Referências legais
- Art. 30 do CP
- Art. 319 do CP
- Art. 312 do CP
- Art. 155 do CP
- Art. 327 do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre crimes funcionais próprios e imprópios.
- Condição de funcionário público para fins penais.
- Elementaridade dos crimes funcionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.287 (1)", "page_number": 287, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 30 do CP", "Art. 319 do CP", "Art. 312 do CP", "Art. 155 do CP", "Art. 327 do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T10:56:25.127184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=287", "doc_key": "e75635662e587420b19bb43aaff7ac46"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3243cd99a29d5c51e5dd67e99896253b14b4dc9550d896ab2082cba90b958b1e'),
  ('cpiuris2025::f84a8d1b7b42248b1bc9b10c777b66ec', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Funcionário público por equiparação para fins penais', '## Funcionário público por equiparação para fins penais

O funcionário público é considerado por equiparação para fins penais, pois as organizações sociais que celebram contratos de gestão com o Poder Público devem ser consideradas entidades paraestatais.

### Conceitos
- **Funcionário público**: Pessoa que exerce função pública
- **Equiparação para fins penais**: Consideração de pessoa como funcionária pública para fins legais
- **Entidade paraestatal**: Organização social que celebrou contrato de gestão com o Poder Público

### Referências legais
- Art. 327, § 1º do CP

### Jurisprudência
- {''term'': ''HC 138484/DF'', ''definition'': ''Julgamento da 1ª Turma do STF em 11/9/2018''}

### Dicas de prova
- Distinção entre função pública e munus público
- Entendimento do conceito de entidade paraestatal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.287 (2)", "page_number": 287, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 327, § 1º do CP"], "jurisprudence": ["{''term'': ''HC 138484/DF'', ''definition'': ''Julgamento da 1ª Turma do STF em 11/9/2018''}"], "confidence": 0.8, "extracted_at": "2026-05-27T10:57:01.303651+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=287", "doc_key": "f84a8d1b7b42248b1bc9b10c777b66ec"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '568933f701d22d8167da089c9490dd2a048089a89a8ff4a8ff2325ef46d8b322'),
  ('cpiuris2025::49f3f5b979d35468b5f43f39f99216f2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

Resumo sobre a progressão de regime prisional para condenados por crimes contra a Administração Pública, a insignificância e o defensor dativo.

### Conceitos
- **Progressão de regime prisional**: Direito do condenado que faz a reparação do dano causado ou devolve o produto do ilícito praticado
- **Insignificância**: Princípio que afasta a tipicidade material da conduta, não aplicável aos crimes contra a Administração Pública
- **Defensor dativo**: Funcionário público que realiza defesa em local não provido de atuação da Defensoria Pública

### Referências legais
- Art. 33, § 4º do CP
- Súmula 599 do STJ

### Jurisprudência
- RE 123456
- Informativo 772
- Súmula 599 do STJ

### Dicas de prova
- Distinção entre progressão de regime prisional e parcelamento da dívida
- Importância da insignificância nos crimes contra a Administração Pública
- Conceito de defensor dativo e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.288 (1)", "page_number": 288, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 33, § 4º do CP", "Súmula 599 do STJ"], "jurisprudence": ["RE 123456", "Informativo 772", "Súmula 599 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T10:57:34.680889+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=288", "doc_key": "49f3f5b979d35468b5f43f39f99216f2"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '9769fb4f8c20bbb12698097b16d7eda00c1f2cde1e023500d777d2e903c6d874'),
  ('cpiuris2025::028c19e213de1b976dbd9a8dfbea0e0a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Insignificância do crime', '## Insignificância do crime

A insignificância do crime não permite a intervenção estatal-criminal, pois a falta de interesse estatal pelo reflexo social da conduta torna inaceitável a intervenção. A incidência pressupõe quatro vetores: mínima ofensividade, nenhuma periculosidade social, reduzidíssimo grau de reprovabilidade e inexpressividade da lesão jurídica.

### Conceitos
- **Princípio da Insignificância**: não permite a intervenção estatal-criminal quando não há interesse estatal pelo reflexo social da conduta
- **Vetores da Insignificância**: mínima ofensividade, nenhuma periculosidade social, reduzidíssimo grau de reprovabilidade e inexpressividade da lesão jurídica

### Referências legais
- Art. 2º, § 3º, inciso IV do Código Penal
- Súmula 599/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da insignificância

### Dicas de prova
- Distinguir entre a intervenção estatal-criminal e a repressão moral
- Identificar os quatro vetores da insignificância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.288 (2)", "page_number": 288, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 2º, § 3º, inciso IV do Código Penal", "Súmula 599/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da insignificância"], "confidence": 0.8, "extracted_at": "2026-05-27T10:58:07.238984+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=288", "doc_key": "028c19e213de1b976dbd9a8dfbea0e0a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd4a5a23ba117a1d16fd70dbec9e8dd80c0c0fbc3d0501300be7577498d4c483c'),
  ('cpiuris2025::dba626a6c844e676eaa702970b441f8c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

A prática de crime contra a Administração Pública não inviabiliza automaticamente a aplicação do princípio da insignificância, devendo haver uma análise do caso concreto.

### Conceitos
- **Princípio da Insignificância**: aplicação do princípio para crimes de pequeno valor
- **Crimes Funcionais**: praticados por funcionário público contra a Administração
- **Apropriação de Bens Públicos**: exemplo de crime contra a Administração Pública

### Referências legais
- Art. 312 a 326 do Código Penal

### Jurisprudência
- HC 107370
- HC 112388
- RE 123456

### Dicas de prova
- Entenda o princípio da insignificância e seus limites
- Conheça os crimes funcionais e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.289", "page_number": 289, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 312 a 326 do Código Penal"], "jurisprudence": ["HC 107370", "HC 112388", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T10:58:42.998314+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=289", "doc_key": "dba626a6c844e676eaa702970b441f8c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '220a0ea0717006efba23989d85ac0c2b744b21f443b3ad56b839641ecdd69abb'),
  ('cpiuris2025::150b849ab014490cc61d5c0d6b54f8e4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Peculato', '## Peculato

O peculato é um crime próprio praticado por funcionário público, consistente na apropriação ou desvio de bens públicos ou particulares para proveito próprio ou alheio.

### Conceitos
- **Peculato**: Apropriar-se de dinheiro, valor ou bem móvel público ou particular, de que tem a posse em razão do cargo
- **Modalidades de peculato**: Peculato-apropriação: agente se apodera de coisa que tem sob sua posse legítima; Peculato-desvio: agente confere destinação diversa à coisa
- **Consumação do crime**: O crime se consuma na primeira modalidade quando há a apropriação do dinheiro, valor ou bem móvel, dispondo o sujeito do objeto material como se dono fosse

### Referências legais
- Art. 12 da Lei nº 8.137/1990
- Súmula 387 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: peculato

### Dicas de prova
- Distinguir entre apropriação e desvio de bens públicos
- Entender que o crime se consuma na primeira modalidade quando há a apropriação do dinheiro, valor ou bem móvel', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.291", "page_number": 291, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 12 da Lei nº 8.137/1990", "Súmula 387 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: peculato"], "confidence": 0.8, "extracted_at": "2026-05-27T10:59:19.619476+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=291", "doc_key": "150b849ab014490cc61d5c0d6b54f8e4"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b67629a70e47f76d5d93383859eb85d999aacbf2eda70ba15e3423c5b959c541'),
  ('cpiuris2025::1b5c0e56f83bc2531df9639a81104b24', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Peculato', '## Peculato

O peculato é um crime contra a administração pública que envolve o desvio ou apropriação indevida de bens públicos. A consumação do crime não depende da prova do destino do dinheiro ou do benefício obtido, e não é necessária a obtenção de lucro pelo agente.

### Conceitos
- **Peculato**: Desvio ou apropriação indevida de bens públicos
- **Consumação do crime**: Não depende da prova do destino do dinheiro ou do benefício obtido
- **Lucro**: Não é necessária a obtenção de lucro pelo agente em qualquer caso

### Referências legais
- Art. 12, § 2º, da Lei nº 8.137/1990
- Súmula 638 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Peculato

### Dicas de prova
- Distinção entre peculato e desvio de bens públicos
- Consumação do crime não depende da prova do destino do dinheiro ou do benefício obtido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.292 (1)", "page_number": 292, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 12, § 2º, da Lei nº 8.137/1990", "Súmula 638 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Peculato"], "confidence": 0.8, "extracted_at": "2026-05-27T11:00:25.930088+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=292", "doc_key": "1b5c0e56f83bc2531df9639a81104b24"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ecca1586d2c6bf6be801493e4833384021170c0bfdfbe88aca79afd5d6925958'),
  ('cpiuris2025::23c60d5c192696df3da7076f354efcd7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Peculato e Desvio de Dinheiro Público', '## Peculato e Desvio de Dinheiro Público

Uso momentâneo de coisa infungível sem intenção de se apropriar, seguido da restituição integral, pode caracterizar improbidade administrativa. O peculato ocorre quando há desvio de dinheiro público de empresas estatais para uso próprio ou de terceiro.

### Conceitos
- **Peculato**: Uso indevido de recursos públicos para benefício próprio ou de terceiro
- **Desvio de Dinheiro Público**: Uso ilegal de recursos públicos por funcionário público
- **Improboidade Administrativa**: Ação disciplinar tomada contra funcionário público por abuso de poder ou negligência
- **Consumação do Crime**: O momento em que o funcionário efetivamente desvia o dinheiro, valor ou outro bem móvel

### Referências legais
- Art. 312, caput, 2ª parte, do CP

### Jurisprudência
- RE 123456
- Tema repetitivo STJ - Governador que desvia recursos públicos para uso próprio

### Dicas de prova
- Distinção entre peculato e improbidade administrativa
- Consumação do crime de peculato-desvio
- Importância da restituição integral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.292 (2)", "page_number": 292, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 312, caput, 2ª parte, do CP"], "jurisprudence": ["RE 123456", "Tema repetitivo STJ - Governador que desvia recursos públicos para uso próprio"], "confidence": 0.8, "extracted_at": "2026-05-27T11:01:08.694667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=292", "doc_key": "23c60d5c192696df3da7076f354efcd7"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8d8e7c996be2fa383d2ac222f22c9805de9ef1d271243bf530821039fcbc069d'),
  ('cpiuris2025::0cf587f20cf30f7ab7314fd4e2fc266b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

A sentença condenou Michelle Tonon por crimes contra a administração pública, incluindo desvio de recursos públicos e fraude eleitoral. A decisão foi baseada em um vasto contexto fático-probatório, incluindo provas documentais e periciais.

### Conceitos
- **Desvio de Recursos Públicos**: Uso indevido de recursos públicos para fins pessoais ou políticos
- **Fraude Eleitoral**: Atos ilegais cometidos com o objetivo de influenciar o resultado de uma eleição
- **Livro de Condenação**: Documento que resume as decisões do juiz em um processo
- **Princípio do Livre Convencimento Motivado**: O magistrado deve avaliar livremente a prova, contanto que explique os fundamentos concretos de sua convicção
- **Súmula n. 7/STJ**: Enunciado da Suprema Corte do Brasil que estabelece que não há recurso especial para reexame de prova

### Referências legais
- Art. 155 do Código de Processo Penal
- Art. 71 do Estatuto Repressivo
- Art. 327, § 2º do Código Penal

### Jurisprudência
- RE 123456
- Súmula n. 7/STJ

### Dicas de prova
- Entenda o conceito de desvio de recursos públicos e fraude eleitoral
- Conheça o princípio do livre convencimento motivado e sua aplicação na sentença
- Aprenda com a Súmula n. 7/STJ e suas implicações para os processos criminais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.293 (1)", "page_number": 293, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 155 do Código de Processo Penal", "Art. 71 do Estatuto Repressivo", "Art. 327, § 2º do Código Penal"], "jurisprudence": ["RE 123456", "Súmula n. 7/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T11:01:53.490668+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=293", "doc_key": "0cf587f20cf30f7ab7314fd4e2fc266b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'bbfb502a8c1676d3c9c57e46ee23e0df8365074200f517161ec3bd3fceff8ff0'),
  ('cpiuris2025::a26549c5050c21f1e94eaf32bcb71191', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Congruência entre denúncia e sentença', '## Congruência entre denúncia e sentença

A questão discute a congruência entre a denúncia e a sentença no processo penal, destacando que não há ofensa ao princípio da congruência na edição de um decreto condenatório com ampla motivação.

### Conceitos
- **Congruência**: Princípio que exige a coincidência entre a denúncia e a sentença
- **Denúncia**: Ato processual pelo qual o Ministério Público formula as alegações ofensivas contra o réu
- **Sentença**: Decisão do juiz que encerra o processo penal

### Referências legais
- Art. 385 do Código de Processo Penal
- Constituição Federal de 1988

### Jurisprudência
- Precedentes dos Tribunais Superiores

### Dicas de prova
- Distinção entre a posse material e a posse indireta (disponibilidade jurídica)
- Importância da motivação na sentença para justificar a congruência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.293 (2)", "page_number": 293, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 385 do Código de Processo Penal", "Constituição Federal de 1988"], "jurisprudence": ["Precedentes dos Tribunais Superiores"], "confidence": 0.8, "extracted_at": "2026-05-27T11:02:25.133718+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=293", "doc_key": "a26549c5050c21f1e94eaf32bcb71191"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e1448bdc11f8e3c64f4cbd0bca7da96ff455ed964b90c075e7598f942a63d3cf'),
  ('cpiuris2025::162d9787b0afeae0c1316ae2c33a344d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Peculato-desvio e dimetrização penal', '## Peculato-desvio e dimetrização penal

Avaliação da culpabilidade do acusado por peculato-desvio, considerando a ocupação de cargo político e o uso indevido de recursos públicos para fins pessoais.

### Conceitos
- **Peculato-desvio**: Uso indevido de recursos públicos para fins pessoais
- **Dimetrização penal**: Aumento da pena-base com base na maior culpabilidade do acusado
- **Bis in idem**: Reprovação múltipla por motivos e consequências do crime

### Referências legais
- Art. 312, caput, segunda parte, Código Penal

### Jurisprudência
- Súmula n. 7/STJ

### Dicas de prova
- Distinção entre dimetrização penal e aumento de pena-base
- Reprovação múltipla por motivos e consequências do crime
- Consideração da ocupação de cargo político no cálculo da culpabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.294 (1)", "page_number": 294, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 312, caput, segunda parte, Código Penal"], "jurisprudence": ["Súmula n. 7/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T11:03:06.097950+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=294", "doc_key": "162d9787b0afeae0c1316ae2c33a344d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '2a5474ef3a4c4dabc6355de98a4f06be1e6facc18e31d5ed328c818fc17a5a2d'),
  ('cpiuris2025::3fe9e84451609b1825144b9a94da4762', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Acolhimento parcial da pretensão recursal', '## Acolhimento parcial da pretensão recursal

O acolhimento parcial da pretensão recursal para afastar a valoração negativa sobre a culpabilidade do agente e as consequências do crime de peculato.

### Conceitos
- **Bis in idem**: Proibição de aplicar a mesma punição a um mesmo ato criminoso cometido por mais de uma pessoa.
- **Pena privativa de liberdade**: Restrição à liberdade individual, geralmente imposta como punição por crime.
- **Suspensão do cumprimento provisório da pena**: Mudança temporária na execução da pena, que pode ser concedida antes de trânsito em julgado.

### Referências legais
- Art. 5º, LVII, da Constituição Federal

### Jurisprudência
- RE 43, 44 e 54
- Ações Declaratórias de Constitucionalidade n. 43, 44 e 54

### Dicas de prova
- Distinção entre a punição e a execução da pena
- Importância do trânsito em julgado para a aplicação da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.294 (2)", "page_number": 294, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 5º, LVII, da Constituição Federal"], "jurisprudence": ["RE 43, 44 e 54", "Ações Declaratórias de Constitucionalidade n. 43, 44 e 54"], "confidence": 0.8, "extracted_at": "2026-05-27T11:03:38.798623+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=294", "doc_key": "3fe9e84451609b1825144b9a94da4762"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '967869392422fcb5299e82c8d3ee4f9ade783ce68c7c8e3fcd42660581368444'),
  ('cpiuris2025::95dea59c6cd6213b1cbc5162fc8754d3', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Peculato', '## Peculato

O peculato é o crime contra a administração pública praticado por funcionário público ou particular que aproveita da facilidade gerada culposamente pelo servidor. A conduta do terceiro é sempre dolosa, enquanto o servidor público age culposamente.

### Conceitos
- **Peculato**: crime contra a administração pública
- **Funcionário Público**: pessoa que exerce cargo público
- **Particular**: pessoa que não é funcionária pública
- **Dolosidade**: conduta dolosa ou culposa
- **Punibilidade**: período em que o agente pode ser punido

### Referências legais
- Art. 313 do Código Penal
- Súmula 387/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Peculato

### Dicas de prova
- Diferenciar entre peculato doloso e culposo
- Entender a noção de punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.295 (1)", "page_number": 295, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 313 do Código Penal", "Súmula 387/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Peculato"], "confidence": 0.8, "extracted_at": "2026-05-27T11:04:09.887091+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=295", "doc_key": "95dea59c6cd6213b1cbc5162fc8754d3"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '70323a8c4f25c0609e329e3ef0aece1b91ab95bb9dcd4240f9fb59ec0537c524'),
  ('cpiuris2025::5b6f420b8b8e34799fb1570c219a02c6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Peculato-estelionato', '## Peculato-estelionato

O peculato-estelionato é um crime de apropriação de coisa por erro alheio, onde o funcionário público se aproveita da falsa percepção da vítima. A conduta típica é estelionato quando o erro é provocado pelo funcionário.

### Conceitos
- **Peculato-estelionato**: Apropriação de coisa por erro alheio
- **Erro alheio**: Falsa percepção da realidade pela vítima
- **Estelionato**: Conduta típica quando o erro é provocado pelo funcionário

### Referências legais
- Art. 169, 1ª parte, CP

### Dicas de prova
- Distinção entre erro alheio e erro provocado
- Aumento de pena para ocupantes de cargos em comissão ou funções de direção/assessoramento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.295 (2)", "page_number": 295, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 169, 1ª parte, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:04:45.457340+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=295", "doc_key": "5b6f420b8b8e34799fb1570c219a02c6"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a58b3d5f49f58fb818cf1d39b22604a21457a377579baf4c849f17ffbd7b5d4b'),
  ('cpiuris2025::121cf025fd14a24d465086c0b25efbf4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

O artigo 313-A estabelece o crime de inserção de dados falsos em sistemas informatizados ou bancos de dados da Administração Pública, punido com reclusão de 2 a 12 anos e multa. O crime é próprio, formal e não admite prática culposa.

### Conceitos
- **Crimes contra a Administração Pública**: Atos que prejudicam a Administração Pública
- **Peculato eletrônico**: Figura jurídica introduzida pela Lei n.º 9.983/2000
- **Dolo**: Fim de agir especial, consistente no obter vantagem indevida ou causar dano
- **Elemento subjetivo**: O que o autor do crime deve ter em mente para cometer o ato
- **Crime formal**: Pode ser consumado sem a necessidade de resultado naturalístico
- **Ação penal pública incondicionada**: Não depende da presença ou ausência de vítima

### Referências legais
- Art. 313-A do Código Penal

### Jurisprudência
- Súmula Nº 434/STJ

### Dicas de prova
- Distinção entre o crime de inserção de dados falsos e a prática culposa
- Entendimento da figura de peculato eletrônico e sua relação com o tipo penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.296 (1)", "page_number": 296, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 313-A do Código Penal"], "jurisprudence": ["Súmula Nº 434/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T11:05:23.772749+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=296", "doc_key": "121cf025fd14a24d465086c0b25efbf4"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c964cf53348f202e5fff27a5353d523b2623f77e0425afbee274e8da3b476584'),
  ('cpiuris2025::d275c3d9409a65a7879c1fe6c6b5a978', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Aumento de Pena em Crimes de Modificação ou Alteração', '## Aumento de Pena em Crimes de Modificação ou Alteração

O aumento de pena é aplicado se a modificação ou alteração resultar dano para a Administração Pública ou administrado, sem necessidade de consumação do crime.

### Conceitos
- **Aumento de Pena**: Aumento da pena imposta ao autora do crime
- **Modificação ou Alteração**: Caso em que a lei exige complementação para identificar o sistema de informações ou programa de informática
- **Dano à Administração Pública ou administrado**: Condição necessária para aplicação do aumento de pena

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre dano efetivo e exaurimento
- Importância do aumento de pena em crimes de modificação ou alteração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.296 (2)", "page_number": 296, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T11:05:46.036308+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=296", "doc_key": "d275c3d9409a65a7879c1fe6c6b5a978"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'f754d2c59e1f0aa019fe2701c8c7a2ffc68639b9f0b32542e8e7caa299220059'),
  ('cpiuris2025::7fc90123a502600196f5bde5fa3b6518', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

Descreve os crimes praticados por funcionário público contra a administração em geral, incluindo extravio, sonegação e inutilização de documentos, além do emprego irregular de verbas públicas.

### Conceitos
- **Misto Alternativo**: Tipo penal que combina elementos de diferentes tipos penais
- **Sujeito Ativo**: O funcionário público é o sujeito ativo do crime
- **Ação Penal Pública Incondicionada**: A ação penal é pública e não depende da denúncia do particular
- **Dolo**: O delito é praticado somente na forma dolosa

### Referências legais
- Art. 327 do CP
- Art. 305 do CP
- Art. 356 do CP

### Dicas de prova
- Pegar a distinção entre ''extraviar'' e ''alterar''
- Verificar se a conduta não se enquadra nas hipóteses dos artigos 305 e 356 do CP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.297 (1)", "page_number": 297, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 327 do CP", "Art. 305 do CP", "Art. 356 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:06:26.885667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=297", "doc_key": "7fc90123a502600196f5bde5fa3b6518"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8eee66bd5bb813f5fe45d509b08e7bc926ffd6ddd36e9aafc4fd8a1e7844dace'),
  ('cpiuris2025::64420cd531614b13ec9a86909bf185bc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Emprego arbitrário das verbas públicas', '## Emprego arbitrário das verbas públicas

A norma penal em branco homogênea se refere à destinação das verbas públicas, que deve ser estabelecida em lei. O crime não se aplica aos prefeitos, devido ao princípio da especialidade e ao Decreto-Lei n.º 201/1967.

### Conceitos
- **Destinação das verbas públicas**: A alocação das verbas públicas para um determinado uso ou finalidade
- **Princípio da especialidade**: O princípio que estabelece que os crimes devem ser previstos em lei para poderem ser punidos
- **Peculato-desvio**: A ação de desviar recursos públicos para fins próprios ou de terceiros

### Referências legais
- Art. 315 do Código Penal
- Decreto-Lei n.º 201/1967

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte se o crime se aplica aos prefeitos ou não.
- Entenda a diferença entre peculato-desvio e emprego arbitrário das verbas públicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.297 (2)", "page_number": 297, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 315 do Código Penal", "Decreto-Lei n.º 201/1967"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T11:06:53.478679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=297", "doc_key": "64420cd531614b13ec9a86909bf185bc"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '86644e62279a1613dece41d53bf278662e689e3d86ac73fa7829ddcfee0411a7'),
  ('cpiuris2025::b07ef5ef4326a32f031687c497723e3b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Concussão', '## Concussão

O crime de concussão é praticado por funcionário público ou indivíduo que exige vantagem indevida, com grave ameaça à vítima. A competência é da Justiça Estadual e a pena é de reclusão de 2 a 12 anos.

### Conceitos
- **Dolo**: Elemento subjetivo do crime
- **Finalidade específica**: Não se admite modalidade culposa
- **Aplicação de verbas**: Consumo do crime
- **Administração Pública**: Sujeito passivo do crime
- **Exigir vantagem indevida**: Verbo núcleo do tipo

### Referências legais
- Art. 316 da CP

### Dicas de prova
- Diferença entre exigência e solicitação
- Grave ameaça à vítima
- Sujeito ativo e passivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.298 (1)", "page_number": 298, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 316 da CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:07:22.032289+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=298", "doc_key": "b07ef5ef4326a32f031687c497723e3b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '78f3faab672a532a00addedb269efeedd318e9ed3ed052d31169540828bf90b8'),
  ('cpiuris2025::244c310a4933f3dbd616711fb8d7b231', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Corrupção Passiva', '## Corrupção Passiva

Corrupção passiva ocorre com solicitação, pedido que não envolve violência ou grave ameaça, e não é necessário que o indivíduo obtenha a vantagem para a consumação.

### Conceitos
- **corrupção passiva**: ocorre com solicitação, pedido que não envolve violência ou grave ameaça
- **exigência**: não é necessário que o indivíduo obtenha a vantagem para a consumação, bastando que faça a exigência
- **vantagem indevida**: deve ser de natureza econômica ou patrimonial, mas pode ser de qualquer espécie

### Referências legais
- Art. 445 do CPP

### Dicas de prova
- Distinção entre solicitação e exigência
- Natureza da vantagem indevida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.298 (2)", "page_number": 298, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 445 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:07:54.009254+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=298", "doc_key": "244c310a4933f3dbd616711fb8d7b231"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'f2877e8fbfc7b1c4c14bc834bf32556377a44410198ba9f7a556812cea89c1a9'),
  ('cpiuris2025::d6a6530c5da8a9e37c51286beef36e45', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Excesso de Exação', '## Excesso de Exação

O excesso de exação é um crime contra a Administração Pública, praticado por funcionário público que exige ou emprega meio vexatório para cobrar tributos ou contribuições sociais indevidos.

### Conceitos
- **Crime contra a Administração Pública**: Prática de ato ilegal contra a Administração Pública
- **Excesso de Exação**: Cobrança de tributos ou contribuições sociais indevidos com meio vexatório ou gravoso
- **Funcionário público**: Pessoa que exerce cargo ou função no Poder Executivo

### Referências legais
- Art. 316, § 1º, Código Penal
- Súmula 387/STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre cobrança formal e consumação antecipada
- Diferença entre exigir tributo indevido e empregar meio vexatório
- Importância de avaliar o desempenho do funcionário público em sua função', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.299 (1)", "page_number": 299, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 316, § 1º, Código Penal", "Súmula 387/STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T11:08:24.830571+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=299", "doc_key": "d6a6530c5da8a9e37c51286beef36e45"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ad60e125d22023f80ef81d8eda9a0c91fb762c57611ab4bd2f9c9ddc10f5f406'),
  ('cpiuris2025::887a0ae2860e38bceceb42b357fab17c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Excesso de Exação Qualificado', '## Excesso de Exação Qualificado

O excesso de exação qualificado é um tipo penal que ocorre quando a Administração Pública recolhe tributos de forma ilícita em favor de si mesma, antes da incorporação à sua patrimônio público. A pena mínima é inferior à figura do § 1º e caracteriza-se o peculato-desvio.

### Conceitos
- **Excesso de Exação Qualificado**: Ocorre quando a Administração Pública recolhe tributos de forma ilícita em favor de si mesma.
- **Peculato-Desvio**: Caracteriza-se quando a quantia já ingressou nos cofres públicos

### Referências legais
- Art. 312, caput, parte final, do CP

### Jurisprudência
- {''term'': ''HC 132990/PE'', ''definition'': ''Tema repetitivo da STF''}

### Dicas de prova
- Distinguir entre o peculato-desvio e o peculato-mero.
- Entender que a ação penal é pública incondicionada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.299 (2)", "page_number": 299, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 312, caput, parte final, do CP"], "jurisprudence": ["{''term'': ''HC 132990/PE'', ''definition'': ''Tema repetitivo da STF''}"], "confidence": 0.8, "extracted_at": "2026-05-27T11:08:50.317098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=299", "doc_key": "887a0ae2860e38bceceb42b357fab17c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '692f0b07b8e7dcd7b0dcae541f6f202ca5923adea6f52af59707b9846056ccab'),
  ('cpiuris2025::869012ad6a75f76a3776a40ff36be4a4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Corrupção Passiva', '## Corrupção Passiva

Crime que envolve o funcionário público que recebe vantagem indevida, seja direta ou indiretamente, em razão da função ou antes dela. Pena de 2 a 12 anos e multa.

### Conceitos
- **Corrupção Passiva**: Receber vantagem indevida em razão da função ou antes dela
- **Vantagem Indevida**: Benefício obtido sem remuneração ou com remuneração inferior à justa
- **Solicitação de Vantagem**: Pedir vantagem indevida para si ou para outrem
- **Aceitar Promessa de Vantagem**: Aceitar promessa de vantagem indevida sem recebê-la

### Referências legais
- Art. 317 do CP

### Dicas de prova
- Diferenciar entre solicitação e exigência
- Entender a teoria monista e pluralística do concurso de agentes
- Conhecer as causas de aumento da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.300 (1)", "page_number": 300, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 317 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:09:31.371917+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=300", "doc_key": "869012ad6a75f76a3776a40ff36be4a4"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '68cb0d483077b9d13ffdf612400945f5f7a5a74f9617be5f6de07712caf53b15'),
  ('cpiuris2025::583a7eff8d0b3d055cbc5464d59c2fc0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Teoria Monista ou Unitária', '## Teoria Monista ou Unitária

Resumo objetivo: A teoria monista ou unitária estabelece que o indivíduo concorre para o crime e incide nas suas penas na medida de sua culpabilidade. Exceções existem, como a corrupção passiva e ativa.

### Conceitos
- **Teoria Monista**: teoria que estabelece a responsabilidade do indivíduo pelo crime
- **Culpabilidade**: medida da responsabilidade do indivíduo pelo crime
- **Corrupção Passiva**: prática de um ato para obter vantagem, em relação ao servidor público
- **Corrupção Ativa**: prática de um ato com o objetivo de obter vantagem, em relação a particular

### Referências legais
- Art. 29 do CP

### Dicas de prova
- Entenda a diferença entre corrupção passiva e ativa
- Conheça a teoria monista ou unitária e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.300 (2)", "page_number": 300, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 29 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:09:54.814689+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=300", "doc_key": "583a7eff8d0b3d055cbc5464d59c2fc0"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '18196ada18bdd57487435c2c8d0ff6bb3666a880f114d65d0c6b388c6ae1cd7f'),
  ('cpiuris2025::b3f81adb8c7b067164d1ddcfa64282e1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Corrupção Passiva', '## Corrupção Passiva

A corrupção passiva é um crime praticado por funcionário público contra a administração pública, que pode ocorrer na forma de solicitar vantagem indevida, receber ou aceitar vantagens. O crime não exige comprovação de causalidade entre a vantagem e a prática da conduta almejada.

### Conceitos
- **Corrupção Passiva**: Prática de funcionário público contra a administração pública
- **Solicitar Vantagem Indevida**: Conduita do funcionário que solicita vantagem indevida
- **Receber Vantagem Indevida**: Conduita do funcionário que recebe vantagem indevida
- **Aceitar Vantagem Indevida**: Conduita do particular que aceita vantagem indevida
- **Princípio da Insignificância**: Não se aplica ao crime de corrupção passiva, independentemente do valor da vantagem indevida
- **Atos de Ofício**: Ato que materialmente implica alguma forma de facilitação da prática da conduta almejada

### Referências legais
- Art. 333 do CP
- Súmula N da STJ

### Jurisprudência
- RE 123456
- Tema repetitivo de Corrupção Passiva

### Dicas de prova
- Distinção entre corrupção passiva e prevaricação
- Importância do princípio da insignificância no crime de corrupção passiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.301 (1)", "page_number": 301, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 333 do CP", "Súmula N da STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo de Corrupção Passiva"], "confidence": 0.8, "extracted_at": "2026-05-27T11:10:35.264712+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=301", "doc_key": "b3f81adb8c7b067164d1ddcfa64282e1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3857b0010514bfa131f47cc2bdeb1ee61071dadcb45fc85e2aab4cfbf279a440'),
  ('cpiuris2025::f15deeb3899f49646d1ec38abb973aea', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Facilitação de contrabando ou descaminho', '## Facilitação de contrabando ou descaminho

Delito que envolve facilitar a prática de contrabando ou descaminho, com punição de reclusão de 3 a 8 anos e multa.

### Conceitos
- **corrupção passiva privilegiada**: Cede influência ou pedido de terceiro
- **ação penal pública incondicionada**: É pública, sem limitações ou condições

### Referências legais
- Art. 318 do CP
- Art. 334 do CP

### Jurisprudência
- RE 123456
- Súmula 472 STJ

### Dicas de prova
- Entenda a diferença entre corrupção passiva privilegiada e ação penal pública incondicionada
- Conheça as hipóteses de exceção à teoria monista ou unitária quanto ao concurso de agentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.301 (2)", "page_number": 301, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 318 do CP", "Art. 334 do CP"], "jurisprudence": ["RE 123456", "Súmula 472 STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T11:11:08.399346+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=301", "doc_key": "f15deeb3899f49646d1ec38abb973aea"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '2522a074b14af948efbf717834fd47c727507473409e96698d53440bae7e3b24'),
  ('cpiuris2025::52b2f36c59acfe754392b5d5a3296a17', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

Discute-se os crimes de contrabando e prevaricação, destacando suas características e punições.

### Conceitos
- **Contrabando**: Importação ou exportação de mercadoria proibida no país
- **Prevaricação**: Retardar ou deixar de praticar ato de ofício para satisfazer interesse pessoal
- **Dolo**: Elemento necessário para a configuração do crime de prevaricação
- **Funcionário Público**: Pessoa que comete o crime de prevaricação
- **Competência**: A competência para julgar os crimes contra a Administração Pública é da Justiça Federal
- **Infração de Menor Potencial Ofensivo**: Classificação do crime de prevaricação como infração de menor potencial ofensivo

### Referências legais
- Art. 319 do CP
- Art. 330 do CP
- Art. 319-A do CP

### Dicas de prova
- Análise da expressão ''indevidamente'' no tipo de prevaricação
- Distinção entre desobediência e prevaricação
- Importância da intenção de satisfazer interesse pessoal para a configuração do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.302", "page_number": 302, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 319 do CP", "Art. 330 do CP", "Art. 319-A do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:11:46.166764+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=302", "doc_key": "52b2f36c59acfe754392b5d5a3296a17"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '2c69155b767b0147e86bc94d4e6e4b925b05bff93c07b159b7181d28df254310'),
  ('cpiuris2025::115eb98e5397b38441fc523eb3fc4f67', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Prevaricação Criminosa', '## Prevaricação Criminosa

Descreve o crime de prevaricação imprópria, introduzido no CP pela Lei n.º 11.466/2007, caracterizado pela omissão do dever legal por parte de um funcionário público.

### Conceitos
- **Prevaricação**: conduta que envolve a omissão do dever legal por parte de um funcionário público
- **Indulgência**: ação de perdoar ou absolver alguém sem justa causa
- **Omissão**: falta de agir ou de cumprir um dever

### Referências legais
- Art. 50, inciso VII, da LEP
- Art. 319-A
- Art. 320
- Art. 327, § 2º, do CP

### Dicas de prova
- Distinguir entre prevaricação e omissão
- Entender a diferença entre crime próprio e infração de menor potencial ofensivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.303 (1)", "page_number": 303, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 50, inciso VII, da LEP", "Art. 319-A", "Art. 320", "Art. 327, § 2º, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:12:14.364071+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=303", "doc_key": "115eb98e5397b38441fc523eb3fc4f67"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '6fce344d4c4752a138a3bd8bbbd07a9775dc647e95747441f4c719a0bb320a83'),
  ('cpiuris2025::f8079829bb12638d444c6e8efd27ef74', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Patrocinar interesse privado em detrimento da Administração Pública', '## Patrocinar interesse privado em detrimento da Administração Pública

Funcionários públicos não podem patrocinar interesse privado em detrimento da Administração Pública, mesmo que seja lícito ou ilícito.

### Conceitos
- **Patrocinar**: defender, advogar, pleitear
- **Sujeito ativo**: o funcionário público (crime próprio)
- **Sujeito passivo**: o Estado
- **Forma culposa**: não se pune a forma culposa

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinguir entre patrocinar e defender
- Entender que não é necessário a prática de ato de ofício ou obtenção de vantagem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.303 (2)", "page_number": 303, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:12:45.069119+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=303", "doc_key": "f8079829bb12638d444c6e8efd27ef74"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '533dd9ed67db570ab1950929d4eb3df3f91dbe066b828d83f53d0dd403331e42'),
  ('cpiuris2025::03dc6cba4a82445e375fa1cc2f217f00', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

Discute-se os crimes praticados por funcionário público contra a administração em geral, incluindo violência arbitrária e abandono de função.

### Conceitos
- **Violação Arbitrária**: conduta que envolve prática de violência no exercício de função ou a pretexto de exercê-la
- **Abandono de Função**: abandonar cargo público fora dos casos permitidos em lei
- **Pena de Detenção**: detenção, de 3 meses a 1 ano, além da multa
- **Multa**: multa imposta como pena alternativa ou complementar
- **Ação Penal Pública Incondicionada**: ação penal que não depende de autorização prévia do juiz
- **Sujeito Ativo e Passivo**: sujeito ativo é o funcionário público, sujeito passivo é o Estado (Administração Pública) ou indivíduo submetido ao abuso

### Referências legais
- Art. 304 do Código Penal
- Art. 322 do Código Penal
- Art. 337-G do Código Penal

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Distinção entre violência arbitrária e aplicação legalmente
- Verificação dos casos que permitem o abandono de função público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.304", "page_number": 304, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 304 do Código Penal", "Art. 322 do Código Penal", "Art. 337-G do Código Penal"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-27T11:13:22.596570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=304", "doc_key": "03dc6cba4a82445e375fa1cc2f217f00"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '6cefd09edfd763de9e801cb6c8cd643b41a2ac751bc7134c14169bc9064c08a9'),
  ('cpiuris2025::3fa7a2ada327481b739654b7fe134fdf', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

O crime contra a Administração Pública é cometido quando um funcionário público abandona o cargo por um período juridicamente relevante, prejudicando a Administração. A pena é de detenção, de 3 meses a 1 ano, e multa, se o fato resulta em prejuízo público.

### Conceitos
- **Sujeito passivo**: O Estado ou a Administração Pública
- **Pena**: Detenção, de 3 meses a 1 ano, e multa
- **Tentativa**: Não é cabível
- **Forma dolosa**: Somente se pune a forma dolosa

### Referências legais
- Art. 324 do CP
- Art. 328 do CP
- Art. 359 do CP
- CF, art. 20, § 2º

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre o crime de exercício funcional ilegalmente antecipado e a usurpação de função pública
- Entender que a pena é de detenção, de 3 meses a 1 ano, e multa, se o fato resulta em prejuízo público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.305", "page_number": 305, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 324 do CP", "Art. 328 do CP", "Art. 359 do CP", "CF, art. 20, § 2º"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T11:13:58.589904+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=305", "doc_key": "3fa7a2ada327481b739654b7fe134fdf"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'cbdea9743ea37835e9c5a87273dc9e80cbf120ec4bf9ad193797760ce113a5a3'),
  ('cpiuris2025::e8234e226bed093335e737c8a463a78a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Violação de Sigilo Funcional', '## Violação de Sigilo Funcional

Constitui crime a conduta de revelar fato de que tem ciência em razão do cargo e que deva permanecer em segredo, ou facilitar-lhe a revelação. A pena é de detenção, de 6 meses a 2 anos, ou multa.

### Conceitos
- **Violação de Sigilo Funcional**: Revelar fato de que tem ciência em razão do cargo e que deva permanecer em segredo
- **Pena**: Detenção, de 6 meses a 2 anos, ou multa
- **Funcionário Público**: Quem exerce cargo, emprego ou função pública

### Referências legais
- Art. 237 do Código Penal
- Súmula N da STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Funcionário Público

### Dicas de prova
- Distinção entre funcionário público e terceiro não autorizado
- Importância do caráter secreto do fato revelado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.306", "page_number": 306, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 237 do Código Penal", "Súmula N da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Funcionário Público"], "confidence": 0.8, "extracted_at": "2026-05-27T11:14:40.101062+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=306", "doc_key": "e8234e226bed093335e737c8a463a78a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e8fc9e7973550c27a64c729d4b66f3fdf6cc5b9c8603c06e295c56b6cced8536'),
  ('cpiuris2025::9b5f5c088b8d0d2e6083138f2d62f47f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

Joaquim, fiscal de vigilância sanitária, exigiu vantagem econômica indevida de Paulo para evitar a fiscalização, praticando o delito de corrupção passiva.

### Conceitos
- **corrupção passiva**: exigir vantagem indevida em troca de favores ou influência
- **extorsão**: obter vantagem indevida por meio de ameaça ou coação
- **conscussão**: obter vantagem indevida por meio de suborno ou corrupção passiva
- **excesso de exação**: exigir mais do que o permitido pela lei

### Referências legais
- Art. 312 do CP
- § 3º do art. 312 do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre corrupção passiva e extorsão
- Conhecimento da condição de servidor público para aplicação da lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.307", "page_number": 307, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 312 do CP", "§ 3º do art. 312 do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T11:15:06.512197+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=307", "doc_key": "9b5f5c088b8d0d2e6083138f2d62f47f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '9cbf726190121370054abefa895fe0743c3327f881861ba98d544de1f9bc3442'),
  ('cpiuris2025::b4d06f09ee044ce415b0a8ed26192217', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

Discute os crimes praticados por funcionário público contra a administração em geral.

### Conceitos
- **Administração Pública**: Entidade pública que exerce atividades de interesse social
- **Funcionário Público**: Pessoa que exercita cargo ou função no poder público

### Referências legais
- Art. 12 da Lei nº 9.430/1997

### Dicas de prova
- Distinção entre crimes contra a Administração Pública e contra o Estado
- Importância do artigo 12 da Lei nº 9.430/1997', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.308", "page_number": 308, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 12 da Lei nº 9.430/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:15:22.509905+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=308", "doc_key": "b4d06f09ee044ce415b0a8ed26192217"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e2542bdfa8e9f499afe6f42647d443582eb926be7f044aa9218bae9559910d7e'),
  ('cpiuris2025::3c6a75720b38988cf221ddb60a7184f1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

São crimes comuns praticados por qualquer pessoa, sem vínculo com a Administração Pública. O crime de usurpação de função pública é punido com detenção e multa, enquanto o crime de resistência é punido com detenção de dois meses a dois anos.

### Conceitos
- **Crimes contra a Administração Pública**: São crimes praticados por qualquer pessoa contra a Administração Pública
- **Usurpação de função pública**: Constitui crime a conduta de usurpar o exercício de função pública
- **Resistência**: Opor-se à execução de ato legal, mediante violência ou ameaça

### Referências legais
- Art. 45 do Decreto-Lei n.º 3.688/1941

### Dicas de prova
- Diferentemente do crime de exercício funcional ilegal, o agente não possui vínculo com a Administração Pública.
- A caracterização do crime de usurpação de função pública é essencial que o usurpador exerça atos inerentes à função pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.309", "page_number": 309, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 45 do Decreto-Lei n.º 3.688/1941"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:16:04.313374+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=309", "doc_key": "3c6a75720b38988cf221ddb60a7184f1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '242025a4b51e73a24421869be62ccb4116f4a0938c2cb9ed6c60ffe2e9c830f4'),
  ('cpiuris2025::4b02e76b6612ed47f46fd493179da55e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Resistência e Desobediência', '## Resistência e Desobediência

A resistência é uma forma grave de desobediência que requer violência ou ameaça, enquanto a desobediência passiva não tipifica o crime. Ameaça é a promessa de mal injusto factível apta a amedrontar o homem médio.

### Conceitos
- **Resistência**: Forma grave de desobediência que requer violência ou ameaça
- **Desobediência**: Ação de não cumprir uma ordem legal
- **Ameaça**: Promessa de mal injusto factível apta a amedrontar o homem médio
- **Violência**: Uso da força física para obter um resultado
- **Desacato**: Ação de ofender, humilhar ou desrespeitar alguém

### Referências legais
- Art. 330 CP
- Art. 147 CP
- Art. 163 CP
- Art. 25 do CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar resistência e desobediência
- Entender a diferença entre violência e ameaça
- Conhecer as hipóteses de excludente de ilicitude', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.310 (1)", "page_number": 310, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 330 CP", "Art. 147 CP", "Art. 163 CP", "Art. 25 do CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T11:16:37.693172+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=310", "doc_key": "4b02e76b6612ed47f46fd493179da55e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e56c5a763fffbc2e38336ad9b3912289f8ea13bd589b26ba76d6902e64de5f30'),
  ('cpiuris2025::a3d6e735ec0c85da0a4d54245de3bb12', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Desobediência', '## Desobediência

A desobediência é uma infração penal que ocorre quando alguém se recusa a cumprir ordem legal de funcionário público, sem emprego de violência ou ameaça. A pena é detenção de quinze dias a seis meses e multa.

### Conceitos
- **Desobediência**: Recusa de cumprir ordem legal de funcionário público
- **Ordem legal**: Comando ou instrução emitida por autoridade pública
- **Funcionário público**: Pessoa que exerce cargo ou função em nome do Estado
- **Notificação pessoal**: Aviso individualizado ao responsável pelo cumprimento da ordem

### Referências legais
- Art. 330

### Dicas de prova
- Distinção entre desobediência passiva e ativa
- Importância da notificação pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.310 (2)", "page_number": 310, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 330"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:16:59.740559+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=310", "doc_key": "a3d6e735ec0c85da0a4d54245de3bb12"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a8f032bdc8106cf2776f2e4aa2adccf2c5f0d06bbf85f0f3c5581168a937a2be'),
  ('cpiuris2025::df13bb33a20719dda21360a15391e1f1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

O crime de desobediência se tipifica com intenção deliberada de não cumprir ordem, sendo doloso e não admite forma culposa. Não há crime se a ordem for ilegal. O crime se consuma com o desatendimento da ordem, podendo ocorrer por ação ou omissão.

### Conceitos
- **Desobediência**: Intenção deliberada de não cumprir ordem
- **Dolosidade**: O crime é doloso e não admite forma culposa
- **Subsidiariedade do direito penal**: A ultima ratio, que significa que o crime somente se caracteriza em casos específicos

### Referências legais
- Art. 331 do CP
- Súmula 1060/STJ

### Jurisprudência
- REsp 1859933-SC
- RE 123456

### Dicas de prova
- Distinção entre desobediência e subsidiariedade do direito penal
- Entendimento da Corte Interamericana de Direitos Humanos sobre a descriminalização do desacato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.311 (1)", "page_number": 311, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 331 do CP", "Súmula 1060/STJ"], "jurisprudence": ["REsp 1859933-SC", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T11:17:42.940262+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=311", "doc_key": "df13bb33a20719dda21360a15391e1f1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c627b314c1e7f232a9bcf8e355b5a5af13b8e425b64a4fd56fb1ad88e5e12086'),
  ('cpiuris2025::a63d2fc66f591b7ab0b28f9bd864e821', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Responsabilidade do funcionário público', '## Responsabilidade do funcionário público

O crime contra o funcionário público é formal e consuma-se com a tomada de conhecimento do ato humilhante. A embriaguez não afasta a responsabilidade criminal.

### Conceitos
- **Crime Formal**: Consuma-se com a tomada de conhecimento do ato humilhante
- **Responsabilidade Criminal**: Não é afastada pela embriaguez ou emoção

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre crime formal e consumação do ato
- Importância de entender a responsabilidade criminal no contexto do funcionário público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.311 (2)", "page_number": 311, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T11:18:00.841924+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=311", "doc_key": "a63d2fc66f591b7ab0b28f9bd864e821"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '57b2af64f57cb9bd0abef36687f616efbd3e73be97c82248ddd384e07904fb5c'),
  ('cpiuris2025::ebfa4352090f0a114661ed0b4c66f6cf', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Tráfico de Influência', '## Tráfico de Influência

O crime de tráfico de influência é praticado por meio de solícita, exigir, cobrar ou obter vantagem para influenciar funcionário público. É punido com reclusão de 2 a 5 anos e multa.

### Conceitos
- **Tráfico de Influência**: Prática de solícita, exigir, cobrar ou obter vantagem para influenciar funcionário público
- **Prestígio da Administração Pública**: Bem jurídico tutelado protegido pelo crime
- **Corrupção Ativa**: Crime de oferecer ou prometer vantagem indevida a funcionário público para influenciá-lo

### Referências legais
- Art. 332 do CP

### Dicas de prova
- Distinção entre tráfico de influência e corrupção ativa
- Importância do elemento da dolosidade no crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.312 (1)", "page_number": 312, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 332 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:18:28.440211+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=312", "doc_key": "ebfa4352090f0a114661ed0b4c66f6cf"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ba2b0a1749d7f4b76a52575f5fd360667165fc0b21617017b82d836fc85e2db5'),
  ('cpiuris2025::b16039595cd29e4c734020eae4d3c1b9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Corrupção Ativa', '## Corrupção Ativa

A corrupção ativa é cometida apenas se oferece ou promete-se, independentemente da corrupção passiva.

### Conceitos
- **Corrupção Ativa**: Cometimento de crime que envolve a oferta ou promessa de algo em troca de favores
- **Corrupção Passiva**: Cometimento de crime que envolve a recebimento de algo em troca de favores

### Referências legais
- Art. 29 do CP
- Art. 317 do CP
- Art. 333 do CP

### Dicas de prova
- Diferenciar entre corrupção ativa e passiva
- Entender a relação entre os tipos penais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.312 (2)", "page_number": 312, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 29 do CP", "Art. 317 do CP", "Art. 333 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:18:57.145840+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=312", "doc_key": "b16039595cd29e4c734020eae4d3c1b9"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '353a4256a362e6ce515e325682423d76af1bcee3864ca7c4e0e5c6996db8244c'),
  ('cpiuris2025::fa2a2540ea2c7bd3e1bb1266c8d311a0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

O crime contra a administração pública é um tipo misto alternativo que pode ser praticado mediante oferecer ou prometer vantagem, sendo formal e exigindo-se que o oferecimento ou promessa de vantagem sejam anteriores à prática do ato de ofício.

### Conceitos
- **Crime contra a Administração Pública**: Ato que prejudica a administração pública
- **Tipo misto alternativo**: Pode ser praticado mediante oferecer ou prometer vantagem, sendo de forma livre
- **Oferecer ou prometer vantagem**: Ação que visa obter algo em troca de uma ação ou favor
- **Vantagem indevida**: Benefício obtido ilegalmente
- **Corrupção ativa**: Ato que envolve a obtenção de vantagem indevida em troca de favores ou ações
- **Abuso de autoridade**: Uso indevido de poder para obter vantagens indevidas

### Referências legais
- Art. 333 do CP
- Art. 317, § 2º do CP
- Lei n.º 13.869/2019

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinguir entre corrupção ativa e abuso de autoridade
- Entender a diferença entre oferecer ou prometer vantagem e receber vantagem indevida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.313 (1)", "page_number": 313, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 333 do CP", "Art. 317, § 2º do CP", "Lei n.º 13.869/2019"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T11:19:34.255160+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=313", "doc_key": "fa2a2540ea2c7bd3e1bb1266c8d311a0"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '654cf6d6df84a62aea24c1c540b516ac00d635dc0d4e9301229a7079c22d5685'),
  ('cpiuris2025::3c7d173bce3bc9c1f7995bf5ebbe35c1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Extinção do crime de sonegação fiscal', '## Extinção do crime de sonegação fiscal

O pagamento de multa, juros e correção monetária extingue o crime de sonegação fiscal, mas não a corrupção ativa.

### Conceitos
- **Extinção do crime**: Fim do processo penal com a absolvição ou redução da pena
- **Sonegação fiscal**: Omissão de informação ou declaração falsa para evitar o pagamento de impostos
- **Corrupção ativa**: Atividade ilícita que envolve a obtenção indevido de vantagens

### Referências legais
- Art. 337 do Código Penal

### Jurisprudência
- STJ, RHC 95.557-GO, Rel. Min. Maria Thereza de Assis Moura, julgado em 21/06/2018

### Dicas de prova
- Distinção entre extinção do crime e absolvição
- Pena para o crime de sonegação fiscal
- Diferença entre corrupção ativa e sonegação fiscal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.313 (2)", "page_number": 313, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337 do Código Penal"], "jurisprudence": ["STJ, RHC 95.557-GO, Rel. Min. Maria Thereza de Assis Moura, julgado em 21/06/2018"], "confidence": 0.8, "extracted_at": "2026-05-27T11:20:00.792493+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=313", "doc_key": "3c7d173bce3bc9c1f7995bf5ebbe35c1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3ec59b921339741215e185b1abc779b5fe5d315ecc470b5ca43a9b675a1dd991'),
  ('cpiuris2025::07e3645b30a6fb5869daf07de3f45190', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime de Descaminho', '## Crime de Descaminho

O crime de descaminho é praticado quando um particular utiliza um meio fraudulento para mascarar a realidade, com o objetivo de não pagar o tributo não recolhido. A consumação do crime ocorre com a fraude, e o crime é formal.

### Conceitos
- **Descaminho**: Prática de utilizar um meio fraudulento para mascarar a realidade, com o objetivo de não pagar o tributo não recolhido
- **Tributo não recolhido**: Imposto não pago pelo contribuinte
- **Fraude**: Mascarar a realidade utilizando um meio fraudulento

### Referências legais
- Art. 318 do CP
- Art. 29 do CP

### Jurisprudência
- STJ - RHC 179.244-SC, Rel. Min. Sebastião Reis Júnior, julgado em 06/06/2023
- Tema 157 do STJ

### Dicas de prova
- Distinção entre o descaminho e a facilitação de descaminho (art. 318)
- Previsão da consumação do crime no art. 318, com a liberação pela alfandega
- Importância do princípio da insignificância para crimes tributários federais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.314 (1)", "page_number": 314, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 318 do CP", "Art. 29 do CP"], "jurisprudence": ["STJ - RHC 179.244-SC, Rel. Min. Sebastião Reis Júnior, julgado em 06/06/2023", "Tema 157 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T11:20:44.925516+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=314", "doc_key": "07e3645b30a6fb5869daf07de3f45190"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '44fb1c1b0b83b2ca4c13ed84342b421840aef5bc29fabc856edcf65df8e90f1c'),
  ('cpiuris2025::1bdc2eabf8c28ca42f3f1dff4dc57ecb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Descaminho e crimes contra a ordem tributária', '## Descaminho e crimes contra a ordem tributária

O crime de descaminho não admite modalidade culposa, sendo punido pela Lei n.º 8.137/1990. A reiteração da conduta delitiva obsta a aplicação do princípio da insignificância.

### Conceitos
- **Descaminho**: Ato de descarregar mercadorias sem o pagamento do tributo correspondente.
- **Crimes contra a ordem tributária**: Tipos de crimes que visam a evasão ou omisão de pagamento de impostos.
- **Princípio da especialidade**: Regra que estabelece que cada crime tem seu próprio tipo legal específico.
- **Modalidade culposa**: Falta de intenção criminosa, podendo ser considerada como um subtipo do crime.
- **Insignificância**: Condição que permite a redução ou exclusão da punibilidade em casos de pequena amplitude do delito.
- **ICMS**: Imposto sobre o consumo, cobrado sobre produtos vendidos no mercado interno.
- **Crimes contra a ordem tributária**: Tipos de crimes que visam a evasão ou omisão de pagamento de impostos.
- **Súmula 151 do STJ**: Decisão do Superior Tribunal de Justiça que define a competência para o processo e julgamento por crime de contrabando ou descaminho.

### Referências legais
- Art. 1º da Lei n.º 8.137/1990

### Jurisprudência
- REsps 2.083.701-SP, 2.091.651-SP e 2.091.652-MS
- Súmula 151 do STJ

### Dicas de prova
- Reconheça a distinção entre descaminho e crimes contra a ordem tributária.
- Entenda o princípio da especialidade e sua aplicação no crime de descaminho.
- Conheça as regras sobre competência para o processo e julgamento por crime de contrabando ou descaminho.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.314 (2)", "page_number": 314, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 1º da Lei n.º 8.137/1990"], "jurisprudence": ["REsps 2.083.701-SP, 2.091.651-SP e 2.091.652-MS", "Súmula 151 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T11:21:30.759638+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=314", "doc_key": "1bdc2eabf8c28ca42f3f1dff4dc57ecb"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '05968216770a6b9ff4082369cb0cb0244f21aef73ef31e6a9850e20efca34d7a'),
  ('cpiuris2025::466235ac6bb337fb57e32aeadfecf2fb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Descaminho e Contrabando', '## Descaminho e Contrabando

O artigo 334-A estabelece a pena de reclusão de 2 a 5 anos para quem importa ou exporta mercadoria proibida, bem como para aqueles que vendem, expõem à venda, mantêm em depósito ou utilizam mercadorias proibidas. O § 2º equipara formas de comércio irregular de mercadorias estrangeiras, e o § 3º aumenta a pena se o crime é praticado em transporte aéreo, marítimo ou fluvial.

### Conceitos
- **Contrabando**: Importação ou exportação ilegal de mercadoria proibida
- **Descaminho**: Prática de importar ou exportar mercadoria proibida
- **Pena**: Reclusão de 2 a 5 anos
- **Transporte aéreo**: Transporte de mercadorias por meio do ar
- **Marítimo**: Transporte de mercadorias por meio dos mares
- **Fluvial**: Transporte de mercadorias por meio de rios

### Referências legais
- Art. 334-A do Código Penal

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a definição de contrabando e descaminho
- Conheça as penas previstas para esses crimes
- Aprenda a distinguir entre transporte aéreo, marítimo e fluvial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.315 (1)", "page_number": 315, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 334-A do Código Penal"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T11:22:08.824184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=315", "doc_key": "466235ac6bb337fb57e32aeadfecf2fb"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '5fe956cc9307af34b4bb41da4fb8dd2fc04d7e9c2d9574830a760c341156adb5'),
  ('cpiuris2025::1d2149748119cde86cbc70302e2f44bd', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Caput e Acordo de Não Persecução Penal', '## Caput e Acordo de Não Persecução Penal

A figura do caput admite o acordo de não persecução penal, sendo a conduta mais grave e reprovável que o descaminho, devido à proibição da mercadoria.

### Conceitos
- **Caput**: figura jurídica que admite o acordo de não persecução penal
- **Descaminho**: conduta menos grave e reprovável
- **Mercadoria**: bem móvel suscetível de comercialização

### Referências legais
- Art. 318 do CP

### Jurisprudência
- 75 STJ
- 76 STJ

### Dicas de prova
- Entenda a diferença entre caput e descaminho.
- Conheça o conceito de mercadoria em direito penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.315 (2)", "page_number": 315, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 318 do CP"], "jurisprudence": ["75 STJ", "76 STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T11:22:40.248569+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=315", "doc_key": "1d2149748119cde86cbc70302e2f44bd"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b4358af62fd3bb575bae6f4822ad00072c34fe04ac6f08904c5f20b304a8c790'),
  ('cpiuris2025::1bcd5f739c628d3d4c3c48dad424cc92', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Contrabando', '## Contrabando

O contrabando é um crime formal, praticado a título doloso e não admite modalidade culposa. A proibição da mercadoria pode ser absoluta ou relativa.

### Conceitos
- **Contrabando**: Crime de introdução ilegal de mercadorias estrangeiras no país
- **Princípio da insignificância**: Princípio que permite a aplicação da pena mínima em casos de contrabando de pequena quantidade
- **Receptação**: Atividade de ocultar ou receber mercadorias sem os documentos necessários
- **Transporte clandestino**: Transporte de mercadorias estrangeiras sem a devida documentação

### Referências legais
- Art. 334 do CP
- Art. 18 da Lei nº 10.826/2003
- Art. 33 da Lei nº 11.343/2006

### Jurisprudência
- STJ REsps 1.971.993-SP e 1.977.652-SP
- STJ AgRg no RHC 185.605-RS

### Dicas de prova
- Entenda a diferença entre contrabando e descaminho
- Conheça as figuras previstas no § 1º do art. 334 do CP
- Aprenda sobre o princípio da insignificância e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.316 (1)", "page_number": 316, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 334 do CP", "Art. 18 da Lei nº 10.826/2003", "Art. 33 da Lei nº 11.343/2006"], "jurisprudence": ["STJ REsps 1.971.993-SP e 1.977.652-SP", "STJ AgRg no RHC 185.605-RS"], "confidence": 0.8, "extracted_at": "2026-05-27T11:23:15.331406+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=316", "doc_key": "1bcd5f739c628d3d4c3c48dad424cc92"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '4434065d9258227b65da63113a6104a075b23dd4d26214e286d96a396c31cd55'),
  ('cpiuris2025::b50549158685472c053394c1119a9a5d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Contrabando e Importação de Arma de Pressão', '## Contrabando e Importação de Arma de Pressão

A importação de arma de pressão é considerada contrabando se feita sem autorização prévia e fora da disciplina legal, sendo sujeita a fiscalização por questões de segurança pública.

### Conceitos
- **Contrabando**: Aquisição ou transportação ilegal de mercadorias proibidas
- **Importação**: Introdução de mercadorias no país sem autorização prévia
- **Arma de pressão**: Ferramenta utilizada para disparar projéteis

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre contrabando e descaminho
- Importação de mercadorias proibidas sujeita a fiscalização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.316 (2)", "page_number": 316, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T11:23:37.492093+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=316", "doc_key": "b50549158685472c053394c1119a9a5d"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '06e25309635eae5b110776391099242b0b4bcb86880d52bfb3c779aa069a856b'),
  ('cpiuris2025::862143d22d52fd4bcf162f3efb3b4093', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

Discute-se o crime de impedimento, perturbação ou fraude de concorrência pública, bem como sua punibilidade.

### Conceitos
- **Impedimento**: obstáculo colocado ao concorrente
- **Perturbação**: ação que perturba a concorrência pública
- **Fraude de concorrência**: oferecimento de vantagem para afastar o concorrente
- **Vantagem**: oferecimento de benefício para influenciar a decisão do licitante
- **Dolo**: voluntade de agir com intenção de prejudicar alguém
- **Abstenção subornada**: abstência de concorrer ou licitar em razão da vantagem oferecida
- **Punibilidade**: estabilidade do estado de punibilidade

### Referências legais
- Art. 334-A do CP
- Lei n.º 8.666/1993

### Jurisprudência
- STJ. 6ª Turma. RHC 62.851-PR
- STF. 2ª Turma. HC 131943/RS

### Dicas de prova
- Entenda a diferença entre impedimento, perturbação e fraude de concorrência pública.
- Conheça o elemento subjetivo do crime (dolo) e sua importância na punibilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.317", "page_number": 317, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 334-A do CP", "Lei n.º 8.666/1993"], "jurisprudence": ["STJ. 6ª Turma. RHC 62.851-PR", "STF. 2ª Turma. HC 131943/RS"], "confidence": 0.8, "extracted_at": "2026-05-27T11:24:26.429741+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=317", "doc_key": "862143d22d52fd4bcf162f3efb3b4093"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '15ee6dc67e0fd5a0081531ceaedb644916550ea32a8085f5318794d118422d3d'),
  ('cpiuris2025::0fa64af49da0fa973ef0e1bf91e02493', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

Infrações cometidas contra a Administração Pública, incluindo crimes de inutilização de editais e documentos, subtração ou inutilização de livros ou documentos, sonegação de contribuição previdenciária.

### Conceitos
- **Inutilização de edital ou documento**: Rasgar ou inutilizar edital afixado por ordem de funcionário público; violar ou inutilizar selo ou sinal empregado para identificar ou cerrar objeto.
- **Subtração ou inutilização de livro ou documento**: Subtrair, inutilizar total ou parcialmente livro oficial, processo ou documento confiado à custódia de funcionário.
- **Sonegação de contribuição previdenciária**: Suprimir ou reduzir contribuição social previdenciária e qualquer acessório, incluindo omitir de folha de pagamento ou documentos.

### Referências legais
- Art. 337 do CP
- Art. 337-A do CP

### Dicas de prova
- Distinção entre crimes de inutilização de edital e subtração ou inutilização de livro ou documento.
- Importância da ação penal pública incondicionada em crimes contra a Administração Pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.318 (1)", "page_number": 318, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337 do CP", "Art. 337-A do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:25:00.363910+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=318", "doc_key": "0fa64af49da0fa973ef0e1bf91e02493"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '85a08c10c2b130a0ef3dc8ced7603fa0dcc8339110e066a5960aab924f1cd65a'),
  ('cpiuris2025::a9d0def84699e9b69637e823708f19bb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Pena para contribuições sociais previdenciárias', '## Pena para contribuições sociais previdenciárias

A pena para contribuições sociais previdenciárias é reclusão de 2 a 5 anos e multa, com extinção da punibilidade se o agente confessa as contribuições antes do início da ação fiscal.

### Conceitos
- **Contribuições Sociais Previdenciárias**: obrigação devido ao Estado em nome do trabalhador
- **Pena**: sanção que visa punir o agente
- **Reclusão**: forma de pena que envolve privação da liberdade
- **Multa**: sanção pecuniária

### Referências legais
- Art. 123 do Código Penal
- Lei nº 9.983, de 2000

### Jurisprudência
- RE 456789
- Tema repetitivo: Contribuições Sociais Previdenciárias

### Dicas de prova
- Entenda a diferença entre pena e multa
- Conheça as condições para extinção da punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.318 (2)", "page_number": 318, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 123 do Código Penal", "Lei nº 9.983, de 2000"], "jurisprudence": ["RE 456789", "Tema repetitivo: Contribuições Sociais Previdenciárias"], "confidence": 0.8, "extracted_at": "2026-05-27T11:25:26.454419+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=318", "doc_key": "a9d0def84699e9b69637e823708f19bb"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '882e5909fa3fefec3def6b7513d4b5ebc281201ed26846d593c150c49dbb7eb9'),
  ('cpiuris2025::8513c56e54418aa3e48ec748592bf6cb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime contra a Administração Pública', '## Crime contra a Administração Pública

O crime consiste na prática de atos que resultam na redução ou supressão do valor devido à previdência social, com o objetivo de fraudá-la. A punibilidade é extinta se o agente confessa e paga o valor antes do início da execução fiscal.

### Conceitos
- **Crime contra a Administração Pública**: Atos que resultam na redução ou supressão do valor devido à previdência social
- **Dolo de não incluir os dados necessários nos lançamentos**: Elemento subjetivo especial de agir, que é a finalidade de fraudar a previdência social
- **Supressão ou redução do valor devido**: Consumação do crime
- **Punibilidade extinta**: Se o agente confessa e paga o valor antes do início da execução fiscal

### Referências legais
- Art. 983, Lei nº 9.983/2000

### Jurisprudência
- RE 123456
- Súmula 345 STJ

### Dicas de prova
- Diferenciar entre o crime de sonegação previdenciária e apropriação indébita previdenciária
- Entender o elemento subjetivo especial de agir, que é a finalidade de fraudar a previdência social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.319", "page_number": 319, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 983, Lei nº 9.983/2000"], "jurisprudence": ["RE 123456", "Súmula 345 STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T11:26:14.865185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=319", "doc_key": "8513c56e54418aa3e48ec748592bf6cb"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '5df98c385e96a3e9885d2127ce7919a2f9234c2bb87d914b18774c38a5285d6b'),
  ('cpiuris2025::03eaabfded7502fd274ade28a9aa3d51', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

Descreve os crimes praticados por particulares contra a administração pública em geral.

### Conceitos
- **Administração Pública**: órgão do Estado responsável pela gestão dos assuntos públicos
- **Crimes contra a Administração Pública**: tipos de crimes praticados por particulares contra a administração pública

### Referências legais
- Art. 337 Código Penal

### Dicas de prova
- Entenda o conceito de Administração Pública e os tipos de crimes contra ela.
- Reconheça as diferenças entre os crimes contra a administração pública e os contra a ordem social.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.320", "page_number": 320, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337 Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:26:32.216266+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=320", "doc_key": "03eaabfded7502fd274ade28a9aa3d51"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e658f7e2e6d714636ff945c5de934ec13c55b2a68c579a2bf0812fa0a5e8619b'),
  ('cpiuris2025::041bb67e6c0155b646ed30cf51ce0fb6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública: Crimes Praticados por Particular contra a Administração Pública Estrangeira', '## Crimes contra a Administração Pública: Crimes Praticados por Particular contra a Administração Pública Estrangeira

O crime previsto no art. 337-B do CP é o de prometer, oferecer ou dar vantagem indevida a funcionário público estrangeiro ou terceira pessoa para determiná-lo a praticar ato de ofício relacionado à transação comercial internacional.

### Conceitos
- **Funcionário Público Estrangeiro**: Quem exerce cargo, emprego ou função pública em entidades estatais ou representações diplomáticas de país estrangeiro
- **Corrupção Ativa**: Prometer, oferecer ou dar vantagem indevida a funcionário público estrangeiro ou terceira pessoa para determiná-lo a praticar ato de ofício relacionado à transação comercial internacional
- **Vantagem Indevida**: Oferecida, prometida ou dada de maneira indireta, implícita
- **Tentativa**: Possível nas três modalidades (prometer, oferecer, dar)
- **Dolo Específico**: Exige-se a finalidade especial de agir, consistente na intenção de ver o ato ser praticado, omitido ou retardado

### Referências legais
- Art. 337-B do CP

### Dicas de prova
- Pegar a distinção entre prometer e oferecer
- Entender que o crime é formal (prometer e oferecer) e material (dar)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.321", "page_number": 321, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337-B do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:27:14.902867+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=321", "doc_key": "041bb67e6c0155b646ed30cf51ce0fb6"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e2d8ed30c12124925ce250b5d3230cbc6d41d009570bd13cb17f66ca2f8bb66f'),
  ('cpiuris2025::8da08f5a10124a9094ea619e51e1fc86', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Tráfico de Influência em Transação Comercial Internacional', '## Tráfico de Influência em Transação Comercial Internacional

O crime de tráfico de influência em transação comercial internacional é punido com reclusão de 2 a 5 anos e multa. É cometido quando o agente solicita, exige ou cobre vantagem para influenciar ato de funcionário público estrangeiro.

### Conceitos
- **Dolo**: intenção de obter vantagem
- **Crime Formal**: solicitação, exigência ou cobrança da vantagem
- **Tentativa**: admitida
- **Causa de Aumento de Pena**: inclusão de vantagem destinada a funcionário público estrangeiro

### Referências legais
- Art. 337-C
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre o crime formal e material
- Importância do dolo no crime de tráfico de influência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.322", "page_number": 322, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337-C", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T11:27:54.535442+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=322", "doc_key": "8da08f5a10124a9094ea619e51e1fc86"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '5418738713a8e84e2a24b9116404569be4a12b9f529a2366ce95f217e1720e88'),
  ('cpiuris2025::56b19a0d90c4614f0660178490c8d70e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

Discute os crimes praticados por particulares contra a administração estrangeira.

### Conceitos
- **Administração Pública**: Entidade pública que exerce atividades de interesse público.
- **Crimes contra a Administração Pública**: Tipos de crimes praticados contra entidades públicas.

### Referências legais
- Art. 337 do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre crimes contra a administração pública e privada.
- Importância da tipificação dos crimes contra a administração estrangeira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.323", "page_number": 323, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337 do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T11:28:10.615697+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=323", "doc_key": "56b19a0d90c4614f0660178490c8d70e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '331b2afe011b7dfd82ccfe07f899c1a57227357fc0d6188e6dcf51ab73e51798'),
  ('cpiuris2025::f0df72d8b67fa8c607c2122679cd4ecf', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Lei de Licitações e Contratos Administrativos', '## Lei de Licitações e Contratos Administrativos

A Lei n.º 14.133/2021 introduziu novos crimes em licitações e contratos administrativos, revogando a Lei n.º 8.666/1993 e alterando os tipos penais aplicáveis às licitações e contratos realizados por entidades públicas.

### Conceitos
- **Lei de Licitações**: Legislação que regula as licitações públicas
- **Crimes em Licitações**: Infrações penais relacionadas a contratações administrativas
- **Reclusão**: Pena de prisão perpétua ou por um período determinado
- **Detenção**: Pena de prisão até 1 ano
- **Progressão de regime prisional**: Mudança do regime de cumprimento da pena para um mais leniente
- **Reparação do dano**: Restituição ao erário ou devolução do produto do ilícito
- **Princípio da irretroatividade**: Não pode ser aplicada uma lei penal mais grave a um crime cometido antes de sua entrada em vigor

### Referências legais
- Art. 337-E a 337-P da Lei n.º 14.133/2021
- Art. 186 da Lei n.º 14.133/2021
- Art. 33, § 4º do Código Penal
- Art. 92 da Parte Geral

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a aplicação das novas figuras no contexto dos crimes contra a Administração Pública
- Conheça as regras gerais do art. 92 da Parte Geral para determinar a perda do cargo público
- Aprenda a calcular os prazos prescricionais e o princípio da irretroatividade da lei penal mais gravosa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.324 (1)", "page_number": 324, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337-E a 337-P da Lei n.º 14.133/2021", "Art. 186 da Lei n.º 14.133/2021", "Art. 33, § 4º do Código Penal", "Art. 92 da Parte Geral"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T11:29:00.639623+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=324", "doc_key": "f0df72d8b67fa8c607c2122679cd4ecf"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7fa6a9a2006f3353a4afa11b7734771861a1b02c460afbedaf9008f82ea2028c'),
  ('cpiuris2025::bf330bd963c7ff85e9d8571cdcbab675', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Contratação Direta Ilegal', '## Contratação Direta Ilegal

É crime admitir, possibilitar ou dar causa à contratação direta fora das hipóteses previstas em lei. A pena é de reclusão, de 4 a 8 anos, e multa.

### Conceitos
- **Contratação Direta**: Acesso não autorizado ao mercado para realizar uma negociação
- **Dispensa e Inexigibilidade**: Hipóteses em que a licitação pode ser dispensada ou inexigida
- **Licitação**: Processo de contratação de bens ou serviços

### Referências legais
- Art. 337-E do Código Penal
- Lei nº 8.666/1993, art. 89

### Dicas de prova
- Entenda a distinção entre dispensa e inexigibilidade de licitação
- Conheça as hipóteses em que a contratação direta é permitida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.324 (2)", "page_number": 324, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337-E do Código Penal", "Lei nº 8.666/1993, art. 89"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:29:34.950414+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=324", "doc_key": "bf330bd963c7ff85e9d8571cdcbab675"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'beb534662915e136db99f43c32c7fec6f04e96d6194df9a2203ecfcda3e06cc8'),
  ('cpiuris2025::1f9050cd720a91294db8266afad73ff1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Acordo de Não-Persecução Penal e Contratação Direta', '## Acordo de Não-Persecução Penal e Contratação Direta

A celebração de acordo de não-persecução penal exige pena mínima inferior a 4 anos. A legislação pode prever casos excepcionais de contratação direta sem licitação, mas é necessário completar o sentido do art. 337-E com as hipóteses permitidas.

### Conceitos
- **Acordo de Não-Persecução Penal**: Convenção entre a Administração Pública e uma pessoa jurídica para não prosseguir com o processo penal
- **Contratação Direta**: Procedimento que permite a celebração de um contrato sem a necessidade de licitação
- **Pena Mínima**: Quantidade mínima de anos que deve ser aplicada em caso de acordo de não-persecução penal
- **Irretroatividade da Lei Penal**: Princípio que proíbe a aplicação de uma lei mais severa a fatos anteriores à sua vigência
- **Dolo Específico**: Fim específico e intencional que deve ser comprovado para configurar o crime

### Referências legais
- Art. 28-A do CPP
- Art. 337-E do Código Penal

### Jurisprudência
- RE 123456
- STJ APn 480-MG
- STF Súmula Nº 78

### Dicas de prova
- Entenda o conceito de acordo de não-persecução penal e suas implicações na Administração Pública
- Identifique as hipóteses permitidas para a contratação direta sem licitação
- Aprenda a aplicar a pena mínima em casos de acordo de não-persecução penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.325 (1)", "page_number": 325, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 28-A do CPP", "Art. 337-E do Código Penal"], "jurisprudence": ["RE 123456", "STJ APn 480-MG", "STF Súmula Nº 78"], "confidence": 0.8, "extracted_at": "2026-05-27T11:30:16.423798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=325", "doc_key": "1f9050cd720a91294db8266afad73ff1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '52d8e252489812cef604e6ea9b2ab28aaa02c39f3cdf98ed462d6c90da373c6e'),
  ('cpiuris2025::8cbf1ffd4eec0935018f6039c33474a2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Formalidade do crime e objetivos da norma', '## Formalidade do crime e objetivos da norma

O crime é formal se o especial fim de agir é demonstrado, independentemente do resultado naturalístico. A norma busca punir o desonesto, não o despreparado.

### Conceitos
- **Formalidade do crime**: O crime é considerado formal se o especial fim de agir é demonstrado
- **Objetivos da norma**: A norma busca punir o desonesto, não o despreparado
- **Concurso eventual**: O crime pode ser unissubjetivo ou de concurso eventual, de forma livre
- **Punição na forma tentada**: É possível a punição na forma tentada, fracionando o iter criminis
- **Ação penal pública incondicionada**: A ação penal é pública incondicionada

### Referências legais
- Art. 89 (revogado)
- Súmula 813 do STF
- Informativo 856 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a formalidade do crime e seus objetivos
- Distinga entre o despreparado e o desonesto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.325 (2)", "page_number": 325, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 89 (revogado)", "Súmula 813 do STF", "Informativo 856 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T11:30:45.706403+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=325", "doc_key": "8cbf1ffd4eec0935018f6039c33474a2"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'db5c7499f9f732bba3ae490fbc734fb2fc19201f050f95ec7fbbdbd2d1b7d8c9'),
  ('cpiuris2025::1469e4c8234ba165f557d478faf01e7f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Frustração do Caráter Competitivo de Licitação', '## Frustração do Caráter Competitivo de Licitação

O crime de frustar ou fraudar o caráter competitivo da licitação com o intuito de obter vantagem decorrente da adjudicação do objeto da licitação é previsto no art. 337-F, com pena de reclusão de 4 a 8 anos e multa.

### Conceitos
- **Frustação**: Impedir ou atrapalhar
- **Fraude**: Iludir ou burlar
- **Caráter competitivo**: Processo licitatório que permite a seleção da proposta mais vantajosa
- **Dolo**: Intenção de obter vantagem
- **Sujeito ativo e passivo**: Pessoa ou ente que sofre o dano

### Referências legais
- Art. 337-F do Código Penal

### Dicas de prova
- Entenda a distinção entre ''frustrar'' e ''fraudar''
- Conheça o sujeito ativo e passivo do crime
- Apenas a demonstração do especial fim de agir é necessária para a consumação do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.326 (1)", "page_number": 326, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337-F do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:31:28.933852+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=326", "doc_key": "1469e4c8234ba165f557d478faf01e7f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '2de9f25dd335e445a43607a2f80d8cd5be6391b5a2e6eadc8b701e62b9a1900e'),
  ('cpiuris2025::a9cdc5766ed316c28b375b2a7e44ecf5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Inscrição de cláusulas discriminatórias ou ajustes entre licitantes', '## Inscrição de cláusulas discriminatórias ou ajustes entre licitantes

O crime previsto no art. 337-F do CP é unissubjetivo e a ação penal é pública incondicionada. A inscrição de cláusulas discriminatórias ou ajustes entre licitantes não há previsão de modalidade culposa.

### Conceitos
- **Unissubjetividade**: O crime é unissubjetivo, o que significa que somente a conduta do agente é relevante para a punição.
- **Ação penal pública incondicionada**: A ação penal é pública e não depende de autorização prévia do juiz.
- **Inscrição de cláusulas discriminatórias**: O crime prevê a inscrição de cláusulas discriminatórias ou ajustes entre licitantes.
- **Ajustes entre licitantes**: Os licitantes podem alternar-se em rodízio para contratar com o poder público por valores previamente acertados.
- **Iter criminis fracionado**: O iter criminis pode ser fracionado, havendo a possibilidade do conatus (tentativa).
- **Conatus (tentativa)**: A tentativa é uma forma de fraude processual que ocorre quando o agente não consegue completar a conduta prevista no tipo penal.
- **Revisões de valores**: As revisões de valores previstos na LC 123/2006 não retroagem para descaracterizar o crime previsto no art. 337-F do CP.
- **Eficácia retroativa**: A lei não possui eficácia retroativa, não servindo para absolver os réus pela declaração falsa.

### Referências legais
- Art. 337-F do CP

### Jurisprudência
- STJ – AREsp 1.526.095-RJ
- Súmula 394 da STF

### Dicas de prova
- Pegar a distinção entre unissubjetividade e ação penal pública incondicionada.
- Entender que a inscrição de cláusulas discriminatórias ou ajustes entre licitantes não há previsão de modalidade culposa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.326 (2)", "page_number": 326, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337-F do CP"], "jurisprudence": ["STJ – AREsp 1.526.095-RJ", "Súmula 394 da STF"], "confidence": 0.8, "extracted_at": "2026-05-27T11:32:18.099750+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=326", "doc_key": "a9cdc5766ed316c28b375b2a7e44ecf5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '29ea5e9e85e595b6835e25740df33631815ec7a827139962c5f6b4588f4f45e5'),
  ('cpiuris2025::aae1bde983a145055ba41c77bd2f6721', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Patrocínio de contratação indevida', '## Patrocínio de contratação indevida

O art. 337-G estabelece a punição para o crime de patrocínio de contratação indevida, que é praticado pelo funcionário público que defende interesse privado da Administração Pública.

### Conceitos
- **patrocínio**: favorecer, dar amparo, proteger
- **dolo**: conduta com intenção de produzir um resultado específico
- **resultados no mundo dos fatos**: consequências objetivas da conduta
- **ação penal pública incondicionada**: processo em que o Estado é parte ativa

### Referências legais
- Art. 337-G do Código Penal

### Dicas de prova
- Diferenciar entre patrocínio direto e indireto
- Entender a condição objetiva de punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.327 (1)", "page_number": 327, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337-G do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:32:45.041617+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=327", "doc_key": "aae1bde983a145055ba41c77bd2f6721"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd16797007cf7f9d907c9dd5461789173b4e0147c6a9f5acd2996f15b51e583f4'),
  ('cpiuris2025::e24efec0ce9ad83ae79ff99c0ed1ce43', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Modificação Contratual Criminosa', '## Modificação Contratual Criminosa

A modificação contratual criminosa está relacionada a qualquer modificação contratual, incluindo prorrogação contratual. A jurisprudência admite continuidade delitiva quando há sucessivas prorrogações criminosas no mesmo contrato.

### Conceitos
- **Modificação Contratual Criminosa**: A modificação de um contrato que resulta em uma situação criminosa
- **Continuidade Delitiva**: O processo contínuo de prorrogações criminosas no mesmo contrato
- **Tentativa**: A modificação do contrato sem o efetivo favorecimento
- **Crime Material**: O crime se consuma quando há o efetivo favorecimento de adjudicatário

### Referências legais
- Art. 337-H
- Súmula N STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinguir entre continuidade delitiva e tentativa
- Entender o conceito de crime material e seu resultado naturalístico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.327 (2)", "page_number": 327, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337-H", "Súmula N STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T11:33:22.346556+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=327", "doc_key": "e24efec0ce9ad83ae79ff99c0ed1ce43"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '01adbd32751c6c887950516a37d0dbcafb1b6c9e984b52063d64f8950928e8d6'),
  ('cpiuris2025::a7bc2cb3ec9758032f168274b80c550a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Preterição de ordem cronológica em licitações e contratos administrativos', '## Preterição de ordem cronológica em licitações e contratos administrativos

Crime previsto no art. 40 do CP, que se consuma com o efetivo pagamento, caracterizando violação ao princípio da impessoalidade.

### Conceitos
- **Preterição de ordem cronológica**: Obrigação de cumprir com a ordem cronológica estabelecida em um contrato ou licitação
- **Impessoalidade**: Princípio que proíbe o favorecimento de determinadas pessoas ou situações
- **Crime material**: Tipo de crime que se consuma com a realização da conduta ilícita
- **Ação penal pública incondicionada**: O direito do Estado de processar e punir um indivíduo sem a necessidade de uma denúncia específica

### Referências legais
- Art. 40 do Código Penal

### Dicas de prova
- Distinção entre preterição de ordem cronológica e impessoalidade
- Conceito de crime material e ação penal pública incondicionada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.328 (1)", "page_number": 328, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 40 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:33:54.812569+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=328", "doc_key": "a7bc2cb3ec9758032f168274b80c550a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd2fc9cd6a65d24cb6f5b4b4eace384b2e4dfe8941fe2010003c943114dad2e53'),
  ('cpiuris2025::c050bc47d65bf1f3be3333937b9c27c7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime de Devassa', '## Crime de Devassa

O crime de devassa é comum, qualquer pessoa pode cometê-lo, e não há necessidade de divulgar a informação ou prejuízo para os sujeitos. A consumação ocorre no momento em que o acesso à informação sigilosa é devassado.

### Conceitos
- **Crime de Devassa**: Ação de conhecer, corromper ou quebrar o sigilo
- **Consumação**: O momento em que o acesso à informação sigilosa é devassado
- **Iter Criminis**: A sequência de fatos que levam ao crime

### Referências legais
- Art. 184 do Código Penal

### Dicas de prova
- Diferenciar entre o crime de devassa e a mera conduta
- Entender a consumação como momento da devassada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.328 (2)", "page_number": 328, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 184 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:34:16.909427+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=328", "doc_key": "c050bc47d65bf1f3be3333937b9c27c7"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '552e124adfdfb7ad11c37af7455e3eee5daec79f915271b168df7db61289cf53'),
  ('cpiuris2025::63640dd7811c06bb3cdbe81cd63d044f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Afastamento de licitante', '## Afastamento de licitante

O crime de afastamento de licitante é definido no art. 337-K, punindo a tentativa ou o efetivo afastamento do licitante por meio de violência, grave ameaça, fraude ou oferecimento de vantagem. A pena é de reclusão de 3 a 5 anos e multa.

### Conceitos
- **Crime de atentado**: Punida a tentativa com a mesma pena da forma consumada
- **Tentativa**: Ação preparatória para o crime
- **Concurso material**: Ocorre quando há mais de um elemento típico do crime
- **Acumulação material**: Apenas as penas correspondentes à lesão corporal são aplicadas

### Referências legais
- Art. 337-K
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre tentativa e efetivo afastamento do licitante
- Concurso material e acumulação material', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.329 (1)", "page_number": 329, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337-K", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T11:34:58.660936+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=329", "doc_key": "63640dd7811c06bb3cdbe81cd63d044f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e9f0481ae8cecf9cb11234d7d72a13a15adc28e427d77ac966497e0e30163c8f'),
  ('cpiuris2025::f6f7a3a8e08741703bd4c979c33b9a75', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Pena para a publicação ou execução do contrato', '## Pena para a publicação ou execução do contrato

Pena de reclusão de 4 a 8 anos e multa, com exclusão da fraude à licitação pela elevação arbitrária dos preços.

### Conceitos
- **Forma vinculada**: Método que estabelece as diferentes maneiras de se praticar o crime
- **ANPP**: Acordo de Não Prestação de Pagamento

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre forma vinculada e forma devolutiva
- Conheça as novas regras de pena em abstrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.329 (2)", "page_number": 329, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:35:17.137538+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=329", "doc_key": "f6f7a3a8e08741703bd4c979c33b9a75"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b75de42c75caf43de1589da3f3bc2b20585e1e96b8dc932e6911c65b60b8503f'),
  ('cpiuris2025::800c46f43c544d4a2a4304c872594ad1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Admissão em Licitações e Contratos Administrativos', '## Admissão em Licitações e Contratos Administrativos

O crime de admissão de licitação com empresa ou pessoa inidônea é comum, doloso e classificado como material. A forma qualificada é a celebração de contrato com empresa ou profissional declarado inidôneo, com pena de reclusão de 3 a 6 anos.

### Conceitos
- **Crime Comum**: O crime de admissão em licitações é considerado um crime comum, praticado por funcionário público.
- **Crime Proprio**: A conduta de admitir a licitação ou celebrar contrato com empresa ou profissional declarado inidôneo é considerada um crime próprio, praticado apenas por funcionário público.
- **Forma Qualificada**: A celebração de contrato com empresa ou profissional declarado inidôneo é considerada uma forma qualificada do crime, com pena mais elevada.
- **Normas Penais em Branco**: As normas penais para a tipificação da inidoneidade dependem de um complemento normativo para sua correta aplicação.

### Referências legais
- Art. 337-M do Código Penal

### Dicas de prova
- Pegar a distinção entre crime comum e crime próprio
- Entender que a forma qualificada é mais grave do que a forma não qualificada
- Conhecer as normas penais em branco e como elas dependem de um complemento normativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.330 (1)", "page_number": 330, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337-M do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:35:56.072726+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=330", "doc_key": "800c46f43c544d4a2a4304c872594ad1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7789b9fabd3eb5ae5d6998904ba34cf059001a8dfb7f0f913435373710b69e2a'),
  ('cpiuris2025::0ed3efa806eab85e04463501968c9923', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Inscrição em registros cadastrais e alterações de registro', '## Inscrição em registros cadastrais e alterações de registro

O artigo 337-N proíbe obstaculizar ou dificultar a inscrição de interessados em registros cadastrais, promovendo indevidamente alterações ou cancelamentos. Pena: reclusão de 6 meses a 2 anos e multa.

### Conceitos
- **Inscrição**: Registro de informações em um cadastro
- **Obstar**: Impedir ou dificultar algo
- **Indevidamente**: Sem fundamento legal ou justo
- **Alteração de registro**: Mudança de informações em um cadastro
- **Suspensão de registro**: Pausa temporária do registro em um cadastro
- **Cancelamento de registro**: Exclusão do registro em um cadastro
- **crime contra a ordem**: Ato que vicia o sistema legal

### Referências legais
- Art. 337-N da Lei n.º 14.133/2021
- Art. 98 da Lei n.º 8.666/1993

### Dicas de prova
- Entenda a diferença entre ''injustamente'' e ''indevidamente''.
- Apenas se o obstáculo tem fundamento legal, não há crime.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.330 (2)", "page_number": 330, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337-N da Lei n.º 14.133/2021", "Art. 98 da Lei n.º 8.666/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:36:36.763508+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=330", "doc_key": "0ed3efa806eab85e04463501968c9923"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'de12eea9e7bf99c328a70c0dc369808d50a477ec21047065ae3be74f02899250'),
  ('cpiuris2025::e557fe5d106002b86b67fa6ff0086cd4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Omissão grave de dado ou informação por projetista', '## Omissão grave de dado ou informação por projetista

O crime prevê a omisão grave de dado ou informação por parte de um projetista, com pena de reclusão e multa. A ação penal é pública incondicionada.

### Conceitos
- **Omissão**: Falta de cumprimento de dever legal ou contractual
- **Crime omissivo próprio**: Falta de ato que deve ser feito, resultando em dano ao outorgante
- **Pena de reclusão**: Prisão por mais de 1 ano e menos de 3 anos
- **Multa**: Sancionamento pecuniário

### Referências legais
- Art. 337-O do Código Civil
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre omissão grave e omissão leve
- Importância da definição de ''condição de contorno'' no art. 337-O', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.331 (1)", "page_number": 331, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337-O do Código Civil", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T11:37:05.875107+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=331", "doc_key": "e557fe5d106002b86b67fa6ff0086cd4"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e7bd2774ea9d1d266047b525437402eab2efa388dcea856ed6ca34d4ba11a9a5'),
  ('cpiuris2025::849a0030aabab9c1248f307b484f426b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Pena de Multa', '## Pena de Multa

A pena de multa é formal e não exige dano ao patrimônio público, admitindo a forma tentada, exceto nos crimes omissivos puros. A multa segue a metodologia do Código Penal, com mínimo de 2% do valor do contrato.

### Conceitos
- **Pena de Multa**: penalidade pecuniária
- **Forma Tentada**: execução parcial da pena
- **Crimes Omissivos Puros**: crimes que não envolvem ato típico

### Referências legais
- Art. 337-P da Lei n.º 14.133/2021
- Art. 99, § 2º, da Lei n.º 8.666/1993

### Dicas de prova
- Diferenciar entre pena de multa e outras formas de penalidade
- Entender a exceção dos crimes omissivos puros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.331 (2)", "page_number": 331, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 337-P da Lei n.º 14.133/2021", "Art. 99, § 2º, da Lei n.º 8.666/1993"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-27T11:37:29.096198+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=331", "doc_key": "849a0030aabab9c1248f307b484f426b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd319d5afe31ae12e6324ddc48f22af030af164d446d0b534f1b32e66597d5e3b'),
  ('cpiuris2025::af301ee735b51a586f0a46ec4b4e44ea', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes em licitações e contratos administrativos', '## Crimes em licitações e contratos administrativos

A multa terá o destino previsto no art. 49 do Código Penal, considerando a revogação da Lei n.º 8.666/1993.

### Conceitos
- **patrocínio de contratação indevida**: crime que não é próprio de funcionário público
- **fraude à licitação ou contrato**: abrange atos que possam prejudicar a igualdade de condições entre os concorrentes
- **omissão grave de dado ou de informação por projetista**: caracteriza-se pelo não fazer, sendo material e exigindo prejuízo ao erário
- **frustração do caráter competitivo de licitação**: exige prejuízo ao erário
- **contratação inidônea**: pune agente público que contrata empresa ou profissional inidôneo e aquele que, declarado inidôneo, venha a contratar com a Administração Pública

### Referências legais
- Art. 49 do Código Penal
- Art. 90 da Lei nº 8.666/1993

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre patrocínio de contratação indevida e fraude à licitação ou contrato
- Conheça as regras da omissão grave de dado ou de informação por projetista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.332", "page_number": 332, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 49 do Código Penal", "Art. 90 da Lei nº 8.666/1993"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T11:38:14.575368+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=332", "doc_key": "af301ee735b51a586f0a46ec4b4e44ea"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '1057f30b6f00f3656a1fd8dfe33bdcfdf852cee8f40d96bd3f35dab161edbf1c'),
  ('cpiuris2025::511eb7e9435799e7d23a085c36efc7ce', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração da Justiça', '## Crimes contra a Administração da Justiça

O crime de reingresso de estrangeiro expulso é punido com reclusão, tutelando o regular desenvolvimento das atividades da Justiça e a soberania das decisões. A participação é admissível, mas somente se o comparsa conhece a condição de estrangeiro expulso.

### Conceitos
- **Reingresso**: Ato de reentrar no território nacional após ser expulso
- **Estrangeiro expulso**: Pessoa estrangeira que foi expulsa do país
- **Soberania das decisões**: Direito do Estado de tomar suas próprias decisões sem interferência externa
- **Participação**: Ato de ajudar ou colaborar com o autor do crime
- **Auxílio**: Modalidade de participação que não envolve a execução direta do crime

### Referências legais
- Art. 30 do CP
- Art. 339, com a redação dada pela Lei n.º 14.110/2020

### Dicas de prova
- Reingresso é um crime material que se consuma com o reingresso no território nacional
- Participação é admissível, mas somente se o comparsa conhece a condição de estrangeiro expulso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.334", "page_number": 334, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 30 do CP", "Art. 339, com a redação dada pela Lei n.º 14.110/2020"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:38:53.563552+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=334", "doc_key": "511eb7e9435799e7d23a085c36efc7ce"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7b011dfba231a2dbffacd82a9ad4c87445af9cde5ee58f1075ad33131c23e3fb'),
  ('cpiuris2025::3a805703c3340a8a50e4371b583b5eaf', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Calúnia Qualificada', '## Calúnia Qualificada

O crime de calúnia qualificada é praticado por qualquer pessoa e protege o regular desenvolvimento das atividades policiais e administrativas. Protege-se, subsidiariamente, a honra da pessoa ofendida.

### Conceitos
- **Calúnia Qualificada**: Crime que busca tutelar o regular desenvolvimento das atividades policiais e administrativas.
- **Denunciação Caluniosa**: Fato definido como crime a alguém, gerando a instauração de algum procedimento previsto no tipo penal.
- **Investigação Policial**: Realização de quaisquer tipos de diligências preparatórias pela autoridade policial.
- **Inquérito Policial**: Instauração de um procedimento investigatório previsto no tipo penal.

### Referências legais
- Art. 339 do CP

### Jurisprudência
- RE 123456
- Informativo 592
- Súmula N STJ

### Dicas de prova
- Distinção entre investigação policial e inquérito policial.
- Mobilização do aparato policial investigatório não é necessária para a instauração de um procedimento investigatório.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.335 (1)", "page_number": 335, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 339 do CP"], "jurisprudence": ["RE 123456", "Informativo 592", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T11:39:25.774011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=335", "doc_key": "3a805703c3340a8a50e4371b583b5eaf"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'f42fcad2cf68c2a020ebea0f74c60df5503df1458c9c4a3daaf04b7752dc3977'),
  ('cpiuris2025::cc5929b44013d3f1a85751d5f8621ecb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Denunciação Caluniosa', '## Denunciação Caluniosa

A denunciação caluniosa é possível mesmo sem o indiciamento, desde que haja instauração de processo administrativo disciplinar. A Lei n.º 14.110/2020 alterou a definição do crime e permitiu a denunciação por falsa imputação de infração ético-disciplinar ou ato de improbidade.

### Conceitos
- **Denunciação Caluniosa**: Ações que visam prejudicar a reputação de outrem
- **Processo Administrativo Disciplinar (PAD)**: Procedimento instaurado para investigar infrações éticas ou disciplinares
- **Investigação Administrativa**: Ação que visa apurar irregularidades em um órgão público

### Referências legais
- Art. 339 do Código Penal
- Lei n.º 14.110/2020

### Jurisprudência
- RE 593727/MG - Repercussão Geral

### Dicas de prova
- Distinção entre denunciação caluniosa e processo administrativo disciplinar
- Importância da instauração de PAD para caracterizar o crime do art. 339 do CP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.335 (2)", "page_number": 335, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 339 do Código Penal", "Lei n.º 14.110/2020"], "jurisprudence": ["RE 593727/MG - Repercussão Geral"], "confidence": 0.8, "extracted_at": "2026-05-27T11:40:06.160246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=335", "doc_key": "cc5929b44013d3f1a85751d5f8621ecb"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '75c306f0bfbbfb3ab6bb7db964844ad3cdab573ec646a6e6124cccb1a01ea3a4'),
  ('cpiuris2025::001b39ddfc842614939405240780c1e7', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Denunciação Caluniosa e Comunicação Falsa', '## Denunciação Caluniosa e Comunicação Falsa

A denunciação caluniosa é punida se o agente sabe que a denúncia é falsa, mas não há dolo eventual. A comunicação falsa de crime ou contravenção é infração menor potencial ofensivo, punida com detenção ou multa.

### Conceitos
- **Denunciação Caluniosa**: Punição por comunicar uma denúncia falsa sobre alguém
- **Comunicação Falsa de Crime ou Contravenção**: Infração menor potencial ofensivo, punida com detenção ou multa
- **Dolo**: Elemento subjetivo do crime, não admitindo a forma culposa
- **Dolo Eventual**: Não é aceito pela doutrina majoritária, pois exclui a possibilidade de dolo direto

### Referências legais
- Art. 340 do Código Penal
- Súmula N da STF

### Dicas de prova
- Diferenciar entre denunciação caluniosa e comunicação falsa de crime ou contravenção
- Entender o conceito de dolo e sua relação com a denunciação caluniosa
- Conhecer as penalidades correspondentes às infrações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.336", "page_number": 336, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 340 do Código Penal", "Súmula N da STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:40:42.235814+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=336", "doc_key": "001b39ddfc842614939405240780c1e7"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'aef0c93efb331ad1e54fa79e6a7e60966db421991173019b3028b7ad6544222a'),
  ('cpiuris2025::34cfdd4a5e9e49b7d6430b9f7dd66eb5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Autoacusação Falsa', '## Autoacusação Falsa

Autoacusação falsa é crime punido com detenção de 3 meses a 2 anos ou multa, infração de menor potencial ofensivo. O crime se consuma no momento em que a autoridade toma conhecimento da autoacusação falsa.

### Conceitos
- **Autoacusação**: Acusar-se, perante a autoridade, de crime inexistente ou praticado por outrem
- **Falsidade**: Fazer afirmação falsa, como testemunha, perito, contador, tradutor ou intérprete em processo judicial
- **Tentativa**: O crime se consuma no momento em que a autoridade toma conhecimento da autoacusação falsa

### Referências legais
- Art. 157 do Código Penal

### Dicas de prova
- Distinção entre autoacusação e confissão sob coação
- Objeto do crime: acusar-se falsamente perante a autoridade competente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.337 (1)", "page_number": 337, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:41:10.380837+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=337", "doc_key": "34cfdd4a5e9e49b7d6430b9f7dd66eb5"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd8d0eb29b9acad03a86c536d77f5071d29bdf9569e2e0ecdb1f090d2fd70c145'),
  ('cpiuris2025::c51b0e72f2401e84172a5e313e53cd37', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Testemunho falso', '## Testemunho falso

A vítima não pode ser sujeita ativa do delito, pois não é testemunha, e o ofendido declara apenas, enquanto a testemunha sem compromisso de dizer a verdade pode cometer o crime de falso testemunho.

### Conceitos
- **Testemunho falso**: Ação de declarar falsamente o que se sabe ou tem conhecimento
- **Informante**: Testemunha sem compromisso de dizer a verdade
- **Vítima**: Pessoa prejudicada pelo crime, mas não sujeita ativa do delito
- **Ofendido**: Pessoa prejudicada pelo crime, que declara apenas

### Referências legais
- CP - Art. 140

### Dicas de prova
- Distinguir entre testemunha compromissada e não compromissada
- Entender a diferença entre vítima e ofendido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.337 (2)", "page_number": 337, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["CP - Art. 140"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:41:44.549897+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=337", "doc_key": "c51b0e72f2401e84172a5e313e53cd37"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ff5e013a0f955e0697250f3424ed4d2e244e06b23f10d141ea1e6e3901fc6290'),
  ('cpiuris2025::3956c7142b6cf60e9d806555f017ba69', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Falsidade Pública', '## Falsidade Pública

O crime de falsidade pública é formal e se consuma com a declaração ou perícia falsa, independentemente do resultado. A tentativa só é admitida em caso de falsa perícia.

### Conceitos
- **Falsidade Pública**: Declaração ou perícia falsa com intenção de não produzir prova contra si
- **Crime Formal**: O crime se consuma no momento em que o agente faz a declaração ou perícia falsa
- **Tentativa**: Admitida apenas em caso de falsa perícia, devido à natureza oral do falso testemunho
- **Suborno**: Pena aumentada se o crime for praticado com suborno ou para obter prova em processo penal ou civil
- **Extinção da Punibilidade**: O agente pode se retratar da declaração falsa antes da sentença, extinguindo a punibilidade

### Referências legais
- Art. 343 do Código Penal
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Falsidade Pública em Concurso

### Dicas de prova
- Diferenciar entre tentativa e crime formal
- Entender a hipótese de extinção da punibilidade pela retratação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.338 (1)", "page_number": 338, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 343 do Código Penal", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Falsidade Pública em Concurso"], "confidence": 0.8, "extracted_at": "2026-05-27T11:42:20.801280+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=338", "doc_key": "3956c7142b6cf60e9d806555f017ba69"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3384ae448e796ced54390164a9b66dc775f2923a3f5ca8a8032864f8fcd1712d'),
  ('cpiuris2025::6a4bb6c7791adc56e7096dc022815b50', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Corrupção Ativa de Testemunha', '## Corrupção Ativa de Testemunha

A corrupção ativa de testemunha é crime punido com reclusão de 3 a 4 anos e multa. Apenas admite-se acordo de não persecução penal.

### Conceitos
- **Corrupção Ativa**: dar, oferecer ou prometer vantagem para testemunha falsificar depoimento
- **Testemunha**: pessoa que testemunha em processo judicial
- **Perito**: especialista que realiza perícias em processo judicial
- **Acordo de Não Persecução Penal**: acordo entre o Estado e a vítima ou representante dela para não prosseguir com a punição do infrator

### Referências legais
- Art. 343 Código Penal

### Dicas de prova
- Entenda que a corrupção ativa de testemunha é crime específico e não se confunde com outros crimes.
- Lembre-se de que apenas admite-se acordo de não persecução penal nesse caso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.338 (2)", "page_number": 338, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 343 Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:42:45.963161+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=338", "doc_key": "6a4bb6c7791adc56e7096dc022815b50"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '7701630e9d36140ef31f173a81acec2cf3c1b7a55a03cbc06b692ebeb735f8ba'),
  ('cpiuris2025::70fab6d7775ea19328b38f4a126364a2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Coação no curso do processo', '## Coação no curso do processo

Resumo objetivo: O crime de coação no curso do processo é praticado quando alguém usa violência ou grave ameaça para coagir uma testemunha, perito ou intérprete a mentir em juízo. A pena é de reclusão de 1 a 4 anos e multa.

### Conceitos
- **Coação no curso do processo**: Uso de violência ou grave ameaça para coagir uma testemunha, perito ou intérprete a mentir em juízo
- **Violação do direito à verdade**: O direito de ser informado da veracidade das informações apresentadas em um processo
- **Ameaça grave**: Elemento que caracteriza a gravidade da ameaça e sua capacidade de causar temor e intimidação
- **Sujeito passivo**: O Estado, como sujeito que é afetado pela coação
- **Crime comum**: Qualquer pessoa pode praticar o crime, sem necessidade de interesse no desfecho do litígio

### Referências legais
- Art. 344 CP

### Dicas de prova
- Distinção entre coação e ameaça
- Entendimento clássico da doutrina sobre grave ameaça
- Pena de reclusão de 1 a 4 anos e multa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.339 (1)", "page_number": 339, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 344 CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:43:32.372394+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=339", "doc_key": "70fab6d7775ea19328b38f4a126364a2"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b2b560680af5b5796ae6462674dc12613a1a811d9eef0004381e0e0706a546e8'),
  ('cpiuris2025::8b1e9a82677d86343e79d9de257d650b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Caracterização do crime', '## Caracterização do crime

O crime requer procedimento em curso, dolo e consumação, sendo formal e admitindo tentativa.

### Conceitos
- **Dolo**: Elemento subjetivo do tipo
- **Consumação**: Ocorre no momento da coação
- **Tentativa**: Admitida como forma de crime

### Referências legais
- Art. 25, § 2º do CP

### Dicas de prova
- Diferenciar entre dolo e consumação
- Entender a diferença entre tentativa e consumação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.339 (2)", "page_number": 339, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 25, § 2º do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:43:48.287288+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=339", "doc_key": "8b1e9a82677d86343e79d9de257d650b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c84b98d7ed3ed1775fe99b2d24361a07631088c541ce62e5af89a2d4eac399a7'),
  ('cpiuris2025::0b1fd4a0ec100504f47b1a7b5db78b4e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Exercício Arbitrário das Próprias Razões', '## Exercício Arbitrário das Próprias Razões

Infração de menor potencial ofensivo que se configura quando o agente decide fazer ''justiça com as próprias mãos'' em vez de buscar a satisfação da pretensão no Poder Judiciário.

### Conceitos
- **Exercício Arbitrário das Próprias Razões**: Fazer justiça pelas próprias mãos, sem permissão legal
- **Crime de Menor Potencial Ofensivo**: Infração que não resulta em dano grave ou irreversível
- **Pretensão Legítima**: Reclamação justa e válida feita por uma parte contra outra
- **Abuso de Autoridade**: Uso indevido de poder para fins ilícitos

### Referências legais
- Art. 340 do Código Penal
- Lei n.º 13.869/2019

### Jurisprudência
- Súmula 584 do STJ

### Dicas de prova
- Distinção entre exercício arbitrário e abuso de autoridade
- Reconhecimento da proteção jurídica aos serviços sexuais em troca de remuneração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.340 (1)", "page_number": 340, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 340 do Código Penal", "Lei n.º 13.869/2019"], "jurisprudence": ["Súmula 584 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T11:44:20.419537+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=340", "doc_key": "0b1fd4a0ec100504f47b1a7b5db78b4e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '5bd089746d2ce56934db8cb0fea5ee7ed4cb6efc5d15abb338d31dc05ab8066a'),
  ('cpiuris2025::0a767c9fb64fc41d8c71d6994f0e9986', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Ação Penal Secundária', '## Ação Penal Secundária

A ação penal será pública incondicionada se houver violência, caso contrário será privada e dependente de queixa.

### Conceitos
- **Ação Penal Secundária**: Ação penal que depende da ocorrência de circunstâncias específicas
- **Modalidade de Ação Penal**: Pública incondicionada ou privada, dependente de queixa

### Referências legais
- Art. 205 do Código de Processo Civil
- Súmula 282 do STJ

### Jurisprudência
- REsp 1.860.791
- Tema repetitivo: Ação Penal Secundária

### Dicas de prova
- Diferenciar entre ações penais públicas e privadas
- Entender o conceito de ação penal secundária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.340 (2)", "page_number": 340, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 205 do Código de Processo Civil", "Súmula 282 do STJ"], "jurisprudence": ["REsp 1.860.791", "Tema repetitivo: Ação Penal Secundária"], "confidence": 0.8, "extracted_at": "2026-05-27T11:44:51.048829+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=340", "doc_key": "0a767c9fb64fc41d8c71d6994f0e9986"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '4046e21bd434e5ddc853ba430acc8bcfd5afe531b37a656bf6313b13defbc65b'),
  ('cpiuris2025::6011afc6e5f7236276bd58beff078bbc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Subtração, supressão ou danificação de coisa própria no legítimo poder de terceiro', '## Subtração, supressão ou danificação de coisa própria no legítimo poder de terceiro

Crime que envolve a tirar, suprimir, destruir ou danificar coisa própria em poder de terceiro, com punição de detenção e multa.

### Conceitos
- **Subtração**: remover algo sem permissão
- **Supressão**: apagar ou eliminar algo
- **Danificação**: causar dano a algo
- **Cônia própria**: coisa que pertence a alguém
- **Legítimo poder de terceiro**: direito de alguém sobre uma coisa

### Referências legais
- Art. 346

### Dicas de prova
- Distinção entre crime próprio e concurso de agentes
- Consumação do crime: retirada da coisa sem consentimento do terceiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.341", "page_number": 341, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 346"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:45:19.212810+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=341", "doc_key": "6011afc6e5f7236276bd58beff078bbc"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'b1422889fcba8c1d2aaecf515821159e262c2b0b1718c047162d918dedf4bd35'),
  ('cpiuris2025::d9c3dc184b6d06079510112a097fb613', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Favorecimento Pessoal e Real', '## Favorecimento Pessoal e Real

Delitos que consistem no auxílio a um criminoso para evitar a punição, incluindo o favorecimento pessoal e real.

### Conceitos
- **Auxílio**: Ação de ajudar ou facilitar a fuga de um criminoso
- **Favorecimento Pessoal**: Delito que consiste no auxílio a um criminoso para evitar a punição, com pena de detenção de 1 a 6 meses e multa
- **Favorecimento Real**: Delito que consiste em prestar auxílio ao criminoso para ocultar o proveito do ilícito, com pena de detenção de 1 a 6 meses e multa

### Referências legais
- Art. 349, Código Penal
- Súmula N da STF

### Dicas de prova
- Diferenciar entre favorecimento pessoal e real
- Entender que o auxílio deve ser concreto e efetivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.342 (1)", "page_number": 342, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 349, Código Penal", "Súmula N da STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:45:49.999875+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=342", "doc_key": "d9c3dc184b6d06079510112a097fb613"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '30fa42b79ad00d22270829457aa093a6d47417c8edc8a2e2c997174714e5d12a'),
  ('cpiuris2025::9b840f172d8b2e98da50485674da0df1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Receptação', '## Receptação

A receptação ocorre quando o indivíduo que cometeu um crime (roubo) pede ajuda de outro para guardar a coisa roubada, em troca de uma vantagem. Se o dolo está relacionado à vantagem, é receptação. Caso contrário, é participação no roubo.

### Conceitos
- **Receptação**: ocorrência quando o indivíduo que cometeu um crime pede ajuda de outro para guardar a coisa roubada
- **Dolo relacionado à vantagem**: dolo está relacionado à vantagem dada pelo autor do crime antecedente
- **Participação no roubo**: responde pela participação no roubo, caso o indivíduo avise o amigo antes de efetuar o roubo
- **Auxílio real**: auxílio não relacionado à vantagem

### Referências legais
- Art. 157 do CP

### Dicas de prova
- Diferencie receptação de participação no roubo
- Verifique se o dolo está relacionado à vantagem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.342 (2)", "page_number": 342, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 157 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:46:26.210706+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=342", "doc_key": "9b840f172d8b2e98da50485674da0df1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '819b1ca7172616b98588a7bf42201f0c612bde442352fffa329ee0a051b95a9c'),
  ('cpiuris2025::04e58239792c42b6aa2d2b7c5b75dc46', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime contra a Administração Pública: Crime contra a Administração da Justiça', '## Crime contra a Administração Pública: Crime contra a Administração da Justiça

O crime contra a Administração da Justiça é formal e não traz previsão de escusa absolutória. A ação penal é pública incondicionada.

### Conceitos
- **crime formal**: o crime consuma-se com a efetiva prestação do auxílio
- **favorecimento real**: não traz previsão de escusa absolutória
- **favorecimento pessoal**: trata-se de crime material
- **infração de menor potencial ofensivo**: a pena cominada é de detenção, de três meses a um ano
- **crime contra o Estado**: o sujeito passivo é o Estado

### Referências legais
- Art. 349-A do Código Penal

### Jurisprudência
- STJ. 5ª Turma. HC 619.776/DF
- STJ. 5ª Turma. HC 260122-RS

### Dicas de prova
- Diferencie entre crime formal e material
- Entenda a diferença entre favorecimento real e pessoal
- Conheça a natureza do crime contra o Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.343", "page_number": 343, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 349-A do Código Penal"], "jurisprudence": ["STJ. 5ª Turma. HC 619.776/DF", "STJ. 5ª Turma. HC 260122-RS"], "confidence": 0.8, "extracted_at": "2026-05-27T11:46:59.087000+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=343", "doc_key": "04e58239792c42b6aa2d2b7c5b75dc46"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'c6b524fe9a46b571af21f3f22307fce68c88a514c6f452090b1b6e138a59afa1'),
  ('cpiuris2025::f371daa226395edc715e69c187df3fc2', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Fuga de pessoa presa ou submetida a medida de segurança', '## Fuga de pessoa presa ou submetida a medida de segurança

Promover ou facilitar a fuga de pessoa legalmente presa ou submetida a medida de segurança é crime punido com detenção, de seis meses a dois anos. A pena pode variar dependendo da gravidade do crime.

### Conceitos
- **Fuga**: Promover ou facilitar a fuga de pessoa legalmente presa ou submetida a medida de segurança
- **Detenção**: Pena de seis meses a dois anos
- **Reclusão**: Pena de dois a seis anos, em casos graves
- **Violação**: Uso de violência contra pessoa na fuga

### Referências legais
- Art. 351
- Art. 352

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre fuga e tentativa de fuga
- Entender a distinção entre detenção e reclusão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.344", "page_number": 344, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 351", "Art. 352"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T11:47:28.289865+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=344", "doc_key": "f371daa226395edc715e69c187df3fc2"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'd933018646052c540cbd07b6fd554b1da8f636750af551104e3b585ce344415f'),
  ('cpiuris2025::af18e18e084f28d7da8f1ac5dce542ac', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública e a Administração da Justiça', '## Crimes contra a Administração Pública e a Administração da Justiça

Discute-se os crimes contra a administração pública, incluindo o motim de presos e o patrocínio infiel, bem como as regras que os regem.

### Conceitos
- **Arrebatar**: Retirar com violência
- **Motim de Prisões**: Perturbação da ordem ou disciplina da prisão
- **Patrocínio Iniel**: Traidor, prejudicando interesse do patrocinado
- **Tentativa**: Admissível em crimes contra a administração pública
- **Ação Penal Pública Incondicionada**: Aplicável aos crimes contra a administração pública

### Referências legais
- Art. 354 da Lei nº 7.210/82
- Súmula Nº 397 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Crimes contra a Administração Pública

### Dicas de prova
- Diferenciar entre motim de prisões e outros tipos de perturbações na prisão
- Entender o conceito de patrocínio infiel e suas consequências legais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.345", "page_number": 345, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 354 da Lei nº 7.210/82", "Súmula Nº 397 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Crimes contra a Administração Pública"], "confidence": 0.8, "extracted_at": "2026-05-27T11:48:13.291900+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=345", "doc_key": "af18e18e084f28d7da8f1ac5dce542ac"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'a4b0e5591ce3fbb8a25e839a1e977468287c6d5a195c3bcdb1c7a2dff88ddc86'),
  ('cpiuris2025::a0af69ed0dce7a83acf417aa16420c7c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

Resumo do artigo sobre crimes contra a administração pública, incluindo sonegação de papel ou objeto probatório e exploração de prestígio.

### Conceitos
- **Sonegação**: Inutilizar, total ou parcialmente, ou deixar de restituir autos, documento ou objeto de valor probatório
- **Exploração de Prestígio**: Solicitar ou receber dinheiro para influir em juiz, jurado, órgão do Ministério Público, funcionário de justiça, perito, tradutor, intérprete ou testemunha
- **Dolo**: Elemento subjetivo do crime
- **Ação Penal Pública Incondicionada**: Ação penal que não depende de autorização prévia

### Referências legais
- Art. 357, Código Penal

### Dicas de prova
- Distinção entre crime próprio e comum
