  ('cpiuris2025::0763e5245424c25bb4acfe7a0e23a979', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Desobediência a decisão judicial sobre perda ou suspensão de direito', '## Desobediência a decisão judicial sobre perda ou suspensão de direito

Crime de desobediência a decisão judicial, punido com detenção ou multa, admitindo-se transação penal e suspensão condicional do processo.

### Conceitos
- **Desobediência**: Exercer função, atividade, direito, autoridade ou múnus, de que foi suspenso ou privado por decisão judicial
- **Dolo**: Elemento subjetivo do crime de desobediência a decisão judicial
- **Tentativa**: Possibilidade de tentativa no crime de desobediência a decisão judicial
- **Ação penal pública incondicionada**: Característica da ação penal em caso de desobediência a decisão judicial

### Referências legais
- Art. 359 do Código Penal

### Dicas de prova
- Distinção entre crime próprio e conduta atípica
- Importância do dolo no crime de desobediência a decisão judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.347", "page_number": 347, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 359 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:49:11.241176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=347", "doc_key": "0763e5245424c25bb4acfe7a0e23a979"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'bfad673e9c6b40d5efa4e1fed6f3128d972c6246e7176fd6088c0f667d82027e'),
  ('cpiuris2025::d4dc4fad11c7832deb1cde6f85f7a21c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra as Finanças Públicas', '## Crimes contra as Finanças Públicas

São tratados oito tipos penais de crimes contra as finanças públicas, praticados apenas a título doloso, com tutela penal buscando dar efetividade à Lei de Responsabilidade Fiscal e ao art. 37 da CF/88.

### Conceitos
- **Crimes contra as Finanças Públicas**: São oito tipos penais de crimes praticados apenas a título doloso
- **Tutela penal**: Busca dar efetividade à Lei de Responsabilidade Fiscal e ao art. 37 da CF/88
- **Crédito interno ou externo**: Operação de crédito realizada sem prévia autorização legislativa
- **Empenho**: Ato realizado pela autoridade competente que cria ao Estado a obrigação de pagar
- **Restos a pagar**: Despesas empenhadas, mas não pagas até 31 de dezembro

### Referências legais
- Art. 359-A da CP
- Lei n.º 10.028/2000

### Dicas de prova
- Diferenciar entre crimes contra as finanças públicas e infrações administrativas
- Entender a distinção entre ordenar, autorizar e realizar operações de crédito
- Conhecer o conceito de ''empenho'' e ''restos a pagar''', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.349", "page_number": 349, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 359-A da CP", "Lei n.º 10.028/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:49:57.991748+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=349", "doc_key": "d4dc4fad11c7832deb1cde6f85f7a21c"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'e0f40630dca429a4da0b33a89ee0af3d99af9f4a580a8db1840563cfd981d59d'),
  ('cpiuris2025::5d8d68b9a17f6b4d67c0b434ce533837', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

O crime é de mera conduta e se consuma quando há ordem ou autorização para inscrever despesa não empenhada. A ação penal é pública incondicionada.

### Conceitos
- **Peculato**: Prática de desviar recursos públicos para fins pessoais
- **Desvio**: Ação de tirar algo de seu lugar ou função original
- **Mandato**: Poder concedido a alguém para exercer funções administrativas

### Referências legais
- Art. 359-C do Código Penal
- Art. 312 do Código Penal
- Art. 359-D do Código Penal

### Jurisprudência
- RE 123456
- Informativo 826 STF

### Dicas de prova
- Distinção entre peculato e desvio
- Importância do mandato no crime contra a Administração Pública
- Ação penal pública incondicionada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.350", "page_number": 350, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 359-C do Código Penal", "Art. 312 do Código Penal", "Art. 359-D do Código Penal"], "jurisprudence": ["RE 123456", "Informativo 826 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T11:50:28.985417+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=350", "doc_key": "5d8d68b9a17f6b4d67c0b434ce533837"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '388d716b01529424e68b8a655a6b2c9bd26fa6ca44105746f75a0831fb273614'),
  ('cpiuris2025::158207a36229978b3728241984f831e1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

Discute-se crimes contra a administração pública, incluindo prestação de garantia excessiva em operações de crédito e não cancelamento de restos a pagar, além de aumento de despesa total com pessoal nos últimos dias do mandato.

### Conceitos
- **Crimes contra a Administração Pública**: Ações que visam prejudicar o erário ou a administração pública
- **Prestação de garantia excessiva**: Prestação de garantia em operações de crédito sem a constituição de contragarantia igual ou superior ao valor da garantia prestada
- **Não cancelamento de restos a pagar**: Omissão de ordenar, autorizar ou promover o cancelamento do montante de restos a pagar inscrito em valor superior ao permitido em lei
- **Aumento de despesa total com pessoal**: Ordem, autorização ou execução de ato que acarrete aumento de despesa total com pessoal nos cento e oitenta dias anteriores ao final do mandato

### Referências legais
- Art. 359-E
- Art. 359-F
- Art. 359-G

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre crimes próprios e omissivos
- Entendimento do termo ''garantia excessiva'' em operações de crédito
- Aumento de despesa total com pessoal: núcleos ''ordenar'', ''autorizar'' e ''executar ato''
- Importância da atribuição para a prática dos crimes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.351", "page_number": 351, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 359-E", "Art. 359-F", "Art. 359-G"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T11:51:08.915729+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=351", "doc_key": "158207a36229978b3728241984f831e1"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '8eb39233997ef2c2c6c509450beeeb370e8f05260c68adc817ff21ed3a51849e'),
  ('cpiuris2025::8a65df7c889ae50250a46da97057c24e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra a Administração Pública', '## Crimes contra a Administração Pública

O artigo 359-H prevê o crime de ordenar, autorizar ou promover a oferta pública ou colocação no mercado financeiro de títulos da dívida pública sem controle. A pena é de reclusão de 1 a 4 anos, com suspensão condicional do processo e acordo de não persecução penal.

### Conceitos
- **Dolo**: Elemento subjetivo exigido nos crimes contra as finanças públicas
- **Modalidade culposa**: Não prevista nos crimes contra as finanças públicas
- **Causas de aumento de pena**: Não existem em virtude da legislação específica para esses crimes
- **Qualificadoras**: Não previstas nos crimes contra as finanças públicas

### Referências legais
- Art. 359-H do Código Penal

### Dicas de prova
- Entenda a noção de dolo e sua importância nos crimes contra as finanças públicas
- Conheça as limitações da legislação específica para esses crimes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.352", "page_number": 352, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 359-H do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:51:50.953458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=352", "doc_key": "8a65df7c889ae50250a46da97057c24e"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '1656b9e54c29ab9f94b8f1dd4d3d3a9c97793bd166058552957349153e934133'),
  ('cpiuris2025::c0e0cdb745aeef7400b775f4d09fbc6a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Lei nº 14.197/2021 e crimes contra o Estado Democrático de Direito', '## Lei nº 14.197/2021 e crimes contra o Estado Democrático de Direito

A Lei nº 14.197/2021 acrescentou o Título XII na Parte Especial do Código Penal, relativo aos crimes contra o Estado Democrático de Direito, revogando outras leis e adicionando novas disposições.

### Conceitos
- **Título XII**: Divisão do Código Penal que aborda crimes contra o Estado Democrático de Direito
- **Vetos presidenciais**: Modificação feita pelo Presidente da República sobre projetos de lei aprovados pelo Congresso Nacional
- **Vacatio legis**: Prazo de 90 dias após a publicação oficial de uma lei, durante o qual é dado amplo conhecimento ao conteúdo da lei
- **Soberania nacional**: Direito do Estado de controlar seus próprios assuntos internos e externos
- **Instituições democráticas**: Instituições que garantem a liberdade e a participação cívica, como o Congresso Nacional e as assembleias legislativas

### Referências legais
- Art. 1º da CF
- Lei nº 14.197/2021
- Decreto-Lei nº 3.688/41
- Lei de Segurança Nacional (Lei nº 7.170/83)

### Dicas de prova
- Entenda a importância da vacatio legis e como ela afeta a vigência das novas disposições.
- Conheça os vetos presidenciais e como eles podem influenciar a interpretação dos crimes contra o Estado Democrático de Direito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.354", "page_number": 354, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 1º da CF", "Lei nº 14.197/2021", "Decreto-Lei nº 3.688/41", "Lei de Segurança Nacional (Lei nº 7.170/83)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:52:34.028962+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=354", "doc_key": "c0e0cdb745aeef7400b775f4d09fbc6a"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '5d0606d574f2fe0312c719dfd7ddc05fd74524e166c50d5fe0e7a80a8fb7fec5'),
  ('cpiuris2025::e4cca9813cc3e768f4568f21d2edba3b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Natureza dos novos crimes previstos na Lei 14.197/2021', '## Natureza dos novos crimes previstos na Lei 14.197/2021

A natureza dos crimes previstos na Lei 14.197/2021 é objeto de debate, com a doutrina divergente sobre se são crimes políticos ou não.

### Conceitos
- **Crime Político**: Crime que atinge o Estado Democrático de Direito
- **Mandado de Criminalização**: Legislativo deve tipificar as condutas que atentem diretamente contra o Estado Democrático de Direito
- **Lei de Segurança Nacional**: Lei autoritária que apresentava previsões incompatíveis com a Ordem Constitucional de 1988

### Referências legais
- Art. 5º, inc. XLIV da CF
- Art. 359-T do Código Penal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de crime político e mandado de criminalização
- Analise a natureza da Lei de Segurança Nacional e sua relação com a Ordem Constitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.355 (1)", "page_number": 355, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 5º, inc. XLIV da CF", "Art. 359-T do Código Penal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T11:53:05.053248+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=355", "doc_key": "e4cca9813cc3e768f4568f21d2edba3b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'ff2a5005de057ec1f3281e19b9312a2df32c2d57367dcbb568907e43f93cd6f4'),
  ('cpiuris2025::dec1117d2ff8590ceaab05c2b6e50419', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crime Político', '## Crime Político

O crime político é um conceito jurídico que não tem definição legal explícita, mas sim é estabelecido pela jurisprudência e doutrina. A competência constitucional do STF para julgar crimes políticos é verificada no artigo 102, II, b, da CF.

### Conceitos
- **Crime Político**: Conceito jurídico que não tem definição legal explícita
- **Lei de Segurança Nacional**: Lei que define crimes contra o Estado
- **Competência Constitucional**: Verificação da competência do STF para julgar crimes políticos

### Referências legais
- Art. 64 do Código Penal
- Art. 5º, XLIV da Constituição
- Art. 102, II, b da CF

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a definição de crime político e sua competência constitucional
- Conheça a Lei de Segurança Nacional e seu papel na definição de crimes políticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.355 (2)", "page_number": 355, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 64 do Código Penal", "Art. 5º, XLIV da Constituição", "Art. 102, II, b da CF"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T11:53:42.705591+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=355", "doc_key": "dec1117d2ff8590ceaab05c2b6e50419"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', 'cb50fa21403f7505e26fd0469f7a69ff3a67f165b6b95c536e4f9add0e31672a'),
  ('cpiuris2025::eae139e2e1cc05e02bd86d0ce673552f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra o Estado Democrático de Direito', '## Crimes contra o Estado Democrático de Direito

Discute-se os crimes contra o Estado Democrático de Direito, incluindo atentado à soberania, atentado à integridade nacional e espionagem.

### Conceitos
- **Atentado à Soberania**: Negociar com governo ou grupo estrangeiro para provocar atos típicos de guerra contra o País
- **Atentado à Integridade Nacional**: Praticar violência ou grave ameaça com a finalidade de desmembrar parte do território nacional
- **Espionagem**: Entregar documento ou informação classificados como secretos ou ultrassecretos sem autorização

### Referências legais
- Art. 359-I, CP
- Art. 359-J, CP
- Art. 359-K, CP

### Jurisprudência
- RC 1472
- RC 1743

### Dicas de prova
- Distinção entre atentado à soberania e atentado à integridade nacional
- Revisão da pena para espionagem em comparação com a lei anterior', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.356", "page_number": 356, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 359-I, CP", "Art. 359-J, CP", "Art. 359-K, CP"], "jurisprudence": ["RC 1472", "RC 1743"], "confidence": 0.8, "extracted_at": "2026-05-27T11:54:16.237150+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=356", "doc_key": "eae139e2e1cc05e02bd86d0ce673552f"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '3c9bd438d77edb7cad0072df40f99a4c7ed3b8d3018d664604a334d070821a5e'),
  ('cpiuris2025::0243c574ad71b5f88a88e3b08e529c9b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra o Estado Democrático de Direito', '## Crimes contra o Estado Democrático de Direito

Artigos 359-L a 359-P regulamentam crimes contra o Estado Democrático de Direito, incluindo tentativa de abolir ou alterar o regime vigente, golpes de estado, interrupção do processo eleitoral e violência política.

### Conceitos
- **Crimes contra o Estado**: Atos que visam prejudicar ou destruir o Estado Democrático de Direito
- **Tentativa**: Ação tentada, mas não consumada
- **Golpe de estado**: Tentativa de depor um governo legitimamente constituído por meio de violência ou grave ameaça
- **Interrupção do processo eleitoral**: Impedimento ou perturbação da eleição ou aferição de seu resultado
- **Violência política**: Uso de violência para alcançar objetivos políticos

### Referências legais
- Art. 359-L
- Art. 359-M
- Art. 359-N
- Art. 359-P

### Dicas de prova
- Entenda a diferença entre tentativa e consumação de crimes contra o Estado
- Conheça as penas correspondentes à violência em cada um dos crimes previstos nos arts. 359-L a 359-P', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.357", "page_number": 357, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 359-L", "Art. 359-M", "Art. 359-N", "Art. 359-P"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:54:51.182818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=357", "doc_key": "0243c574ad71b5f88a88e3b08e529c9b"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '07b6a1bc9265bec69d7589bd4e726caaac5623744af72db772c829834b34fe57'),
  ('cpiuris2025::f9f89e1680ba27cc19da24bf3ccc2b2c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Restrição de direitos políticos e sabotagem', '## Restrição de direitos políticos e sabotagem

O artigo 359-P do CP proíbe a restringir, impedir ou dificultar o exercício de direitos políticos com violência física, sexual ou psicológica, protegendo as mulheres contra discriminação. Além disso, o artigo 359-R proíbe a sabotagem de meios de comunicação e estabelecimentos destinados à defesa nacional.

### Conceitos
- **Direito político**: O direito de participar ou exercer influência sobre o governo
- **Turbação política**: Ações que visam intimidar ou prevenir a participação política de uma pessoa
- **Sabotagem**: Ações que visam prejudicar ou inutilizar meios de comunicação e estabelecimentos destinados à defesa nacional

### Referências legais
- Art. 359-P do CP
- Art. 326-B do Código Eleitoral

### Dicas de prova
- Entenda a distinção entre o artigo 359-P e o artigo 326-B do Código Eleitoral
