  ('cpiuris2025::3c924de9b7228dd50f7fda754ad2d0d0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Delitos contra a Defesa Nacional', '## Delitos contra a Defesa Nacional

O texto define como crime a inutilização de meio de comunicação ou estabelecimento utilizado para defesa nacional, com o objetivo de abolir o Estado Democrático de Direito.

### Conceitos
- **Delito contra a Defesa Nacional**: Crime que visa abolir o Estado Democrático de Direito
- **Tendência Interna Transcendente**: Fim do crime que não precisa ser alcançado para consumação
- **Fim Especial**: Objetivo específico do crime, que não é necessariamente alcançado

### Referências legais
- Art. 23 da Lei nº 7.170/72

### Dicas de prova
- Distinção entre delitos contra a defesa nacional e outros tipos de crimes
- Entendimento do termo ''fim especial'' no contexto do crime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf · p.358 (2)", "page_number": 358, "discipline": "Direito Penal (Parte Especial)", "legal_refs": ["Art. 23 da Lei nº 7.170/72"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:55:58.220267+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Especial) - Vol. 06 - 2025.pdf#page=358", "doc_key": "3c924de9b7228dd50f7fda754ad2d0d0"}'::jsonb, '{"materia": "Direito Penal (Parte Especial)"}'::jsonb, 'cp_iuris_2025', '9046903355e96ee3f800376943ba99fb06655393f12fe0cb4c35a38cc7aa2477'),
  ('cpiuris2025::e0a35269cddefa043babd9d9af02134b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Crimes contra o Estado Democrático de Direito', '## Crimes contra o Estado Democrático de Direito

