### Conceitos
- **Liberdade de Expressão**: Direito fundamental previsto na Constituição Federal que permite a manifestação do pensamento, criação, expressão e informação
- **Manifestação Política**: Atividade que visa promover mudanças sociais ou políticas, incluindo passeatas, reuniões, greves e aglomerações

