  ('cpiuris2025::56d15733458e4a4501e0f32f3c28288e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Especial) — Súmulas e Temas do STJ e STF', '## Súmulas e Temas do STJ e STF

