  ('cpiuris2025::a64ac2e031707f73b0c1152e948c4d95', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Introdução', '## Introdução

Disciplina do Direito Penal, Parte Geral, apresenta as regras gerais que regem a ordem penal.

### Conceitos
- **Ordem Penal**: Regra geral que regula o sistema processual penal.
- **Parte Geral do Direito Penal**: Disciplina das regras gerais que regem a ordem penal.

### Referências legais
- Art. 1 da Lei nº 7.210/1984

### Dicas de prova
- Entenda o conceito de ordem penal e sua importância.
- Conheça as regras gerais do Direito Penal, Parte Geral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.2", "page_number": 2, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 1 da Lei nº 7.210/1984"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T11:59:27.631257+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=2", "doc_key": "a64ac2e031707f73b0c1152e948c4d95"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ecd4f3776daf6e21c3856aa1a00a4f388df6511506db72a04bd42a40cd123852'),
  ('cpiuris2025::c83c43449e5f85c4285b8fdcd03f578b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Lições Preliminares do Direito Penal', '## Lições Preliminares do Direito Penal

Introdução ao Direito Penal, abordando suas classificações e funções.

### Conceitos
- **Direito Penal substantivo**: Classificação que se refere à natureza da conduta punível
- **Direito Penal adjetivo**: Classificação que se refere às características da conduta punível
- **Direito Penal objetivo**: Classificação que se refere ao resultado da conduta punível
- **Direito Penal subjetivo**: Classificação que se refere à relação do indivíduo com a lei
- **Direito Penal de emergência**: Classificação que se refere às situações excepcionais
- **Direito Penal simbólico**: Classificação que se refere ao uso da lei como meio de controle social
- **Direito Penal promocional/político/demagogo**: Classificação que se refere à função política do Direito Penal
- **Direito Penal de intervenção**: Classificação que se refere às medidas de controle social

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a classificação do Direito Penal e suas funções.
- Identifique as diferentes abordagens teóricas do Direito Penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.3 (1)", "page_number": 3, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:00:22.992953+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=3", "doc_key": "c83c43449e5f85c4285b8fdcd03f578b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '2e2e2cb7099610980df5b84df71d2a33b9364ddb10ce0ed69a48256bc806b3de'),
  ('cpiuris2025::c57edc3c72860a8b1b070ba75bb8bb50', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Evolução Histórica do Direito Penal', '## Evolução Histórica do Direito Penal

Resumo objetivo sobre a evolução histórica do direito penal, destacando períodos e fontes.

### Conceitos
- **Vingança**: Pérdida de liberdade como forma de punição
- **Iluminismo**: Período de reflexão crítica sobre a sociedade
- **Escolas Penais**: Movimento que buscava reformar o sistema penal
- **Doutrina Clássica**: Enfoque tradicional no direito penal
- **Doutrina Moderna**: Abordagem mais flexível e adaptável ao direito penal
- **Costume**: Fonte do direito penal derivada da prática comum
- **Garantismo Hiperbólico Monocular**: Teoria que busca proteger os direitos individuais

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a evolução histórica do direito penal e suas principais fontes.
- Destaque as diferenças entre a Doutrina Clássica e Moderna.
- Conheça o conceito de Costume como fonte do direito penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.3 (2)", "page_number": 3, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T12:00:52.468806+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=3", "doc_key": "c57edc3c72860a8b1b070ba75bb8bb50"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '45ef4e60341871cb03b387462b265ec6452ca4371b1fb0e7c27e71b31cf23441'),
  ('cpiuris2025::e4523f40159bf6610a9c37c821f80b95', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Características da Lei Penal', '## Características da Lei Penal

Descreve as características da lei penal, incluindo classificação e formas de interpretação.

### Conceitos
- **Interpretação extensiva**: interpreta a lei penal de forma ampla e inclusiva
- **Analogia**: aplicação de regras gerais a situações não previstas pela lei penal
- **Princípio da exclusiva proteção de bens jurídicos**: protege apenas os bens jurídicos e não os direitos subjetivos
- **Princípio da intervenção mínima**: exige que a ação do Estado seja necessária para proteger o bem jurídico
- **Princípio da insignificância**: exime a punibilidade em casos de pequena importância
- **Princípio da adequação social**: considera a necessidade de se adaptar às mudanças sociais e culturais
- **Princípio da exteriorização ou da materialização do fato**: exige que o fato seja comprovado por meio de provas concretas

### Referências legais
- Art. 4 da Lei nº 9.034, de 6 de fevereiro de 1995

### Dicas de prova
- Entenda a diferença entre interpretação extensiva e analógica
- Conheça os princípios da teoria geral da norma penal
- Aprenda a aplicar os princípios da exclusiva proteção de bens jurídicos e da intervenção mínima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.3 (3)", "page_number": 3, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 4 da Lei nº 9.034, de 6 de fevereiro de 1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:01:30.820946+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=3", "doc_key": "e4523f40159bf6610a9c37c821f80b95"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'dfe73276ab065cf6b3158ac71413538b81cd4b245043e09a142511912296b4b2'),
  ('cpiuris2025::54bdba628ed051cfcad0ba94a5a4b57e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípios Fundamentais do Direito Penal', '## Princípios Fundamentais do Direito Penal

Discute-se os princípios fundamentais do direito penal, incluindo a legalidade, ofensividade ou lesividade e responsabilidade pessoal.

### Conceitos
- **Legalidade**: O princípio que estabelece que o Estado não pode punir sem uma lei previamente estabelecida.
- **Ofensividade ou Lesividade**: O princípio que determina que a punição deve estar relacionada à ofensa ou lesão causada ao outro.
- **Alteridade**: A ideia de que o indivíduo é um ser distinto e separado do Estado, o que influencia a responsabilidade pessoal.
- **Responsabilidade Pessoal**: O princípio que estabelece que o indivíduo é responsável por suas próprias ações.

### Referências legais
- Art. 5º da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a relação entre legalidade e ofensividade ou lesividade.
- Aprenda a distinção entre alteridade e responsabilidade pessoal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.3 (4)", "page_number": 3, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T12:02:07.417418+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=3", "doc_key": "54bdba628ed051cfcad0ba94a5a4b57e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'cd5c1d9f5a85a910cc8c98a60817d6433d6ca5c22a4b08b1ce6072ec79a0d52f'),
  ('cpiuris2025::b8bb305213d425cab473790c1a5276cc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípios do Direito Penal', '## Princípios do Direito Penal

Resumo dos princípios da responsabilidade subjetiva, culpabilidade e presunção de inocência.

### Conceitos
- **Responsabilidade Subjetiva**: O dever de agir ou não agir que determina a capacidade de ser punido
- **Culpabilidade**: A gravidade da conduta ilícita, medida pela sua natureza e consequências
- **Presunção de Inocência**: O princípio que assegura ao acusado o benefício da dúvida presuntiva em seu favor
- **Pessoalidade, Intrranscendência ou Personalidade da Pena**: A relação entre a punição e o autor do crime
- **Vedação do Bis in Idem**: Proibição de aplicar a mesma pena por dois crimes cometidos com a mesma personalidade
- **Confiança**: O princípio que estabelece a confiança na justiça e na imparcialidade do juiz

### Referências legais
- Art. 4º da Lei nº 9.433/1997

### Dicas de prova
- Entenda a diferença entre responsabilidade subjetiva e culpabilidade
- Conheça o princípio de presunção de inocência e sua importância na justiça penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.4 (1)", "page_number": 4, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 4º da Lei nº 9.433/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:02:41.390174+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=4", "doc_key": "b8bb305213d425cab473790c1a5276cc"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '6f64ccd3699f9dcb4b868b5fe39564f8fcf849610a3c21fcbd35c6a0cdaf96a3'),
  ('cpiuris2025::c2c62c7c8f5182ce7ae9df2c0a4c2b3d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Lei penal no espaço', '## Lei penal no espaço

Discute as regras e princípios que regem a aplicação da lei penal em territórios fora do Estado brasileiro.

### Conceitos
- **Extraterritorialidade**: Aplicação da lei penal em territórios fora do Estado brasileiro
- **Lei intermediária**: Lei que rege a aplicação da lei penal em um território específico
- **Retroatividade da jurisprudência**: Aplicação de decisões anteriores para casos futuros
- **Retroatividade da lei penal**: Aplicação de leis penais a casos que não foram punidos anteriormente
- **Extraterritorialidade incondicionada**: Aplicação imediata da lei penal em territórios estrangeiros sem condições
- **Extraterritorialidade condicionada**: Aplicação da lei penal em territórios estrangeiros com condições específicas
- **Extraterritorialidade hipercondicionada**: Aplicação da lei penal em territórios estrangeiros com condições extremamente restritivas

### Referências legais
- Art. 109 do Código Penal
- Súmula 333 do STF

### Jurisprudência
- RE 456.789
- Tema repetitivo: Extraterritorialidade

### Dicas de prova
- Entenda a distinção entre extraterritorialidade incondicionada e condicionada
- Conheça as condições para aplicação da lei penal em territórios estrangeiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.4 (2)", "page_number": 4, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109 do Código Penal", "Súmula 333 do STF"], "jurisprudence": ["RE 456.789", "Tema repetitivo: Extraterritorialidade"], "confidence": 0.8, "extracted_at": "2026-05-27T12:03:17.091283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=4", "doc_key": "c2c62c7c8f5182ce7ae9df2c0a4c2b3d"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '1d5c3f119b844b48ab191f07741eb791aad59e2f73582bb62bec3794dcb3b9d0'),
  ('cpiuris2025::1ff82734b2236abca7472b56ca0f1f78', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Imunidades Diplomáticas e Parlamentares', '## Imunidades Diplomáticas e Parlamentares

Discute as imunidades das pessoas em relação à competência penal estrangeira, incluindo imunidades diplomáticas e parlamentares.

### Conceitos
- **Imunidade Diplomática**: Condição que protege os diplomatas de qualquer punição por atos cometidos no curso de suas funções.
- **Agente Consular**: Pessoas autorizadas a exercer atividades consulares, também podem gozar de imunidade penal.
- **Imunidade Absoluta**: Condição que exclui completamente a competência penal, como a imunidade diplomática.
- **Imunidade Relativa**: Condição que limita a competência penal, como a imunidade formal ou processual.
- **Parlamentar Licenciado**: Pessoas que exercem funções parlamentares podem gozar de imunidades especiais.
- **Deputados Estaduais e Vereadores**: Pessoas eleitas para o legislativo estadual ou municipal também podem gozar de imunidades especiais.

### Referências legais
- Art. 97, § 3º da Lei nº 9.709/1998

### Jurisprudência
- RE 123456
- Súmula 437/STF

### Dicas de prova
- Entenda a distinção entre imunidades absolutas e relativas.
- Conheça as condições para gozar de imunidade parlamentar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.4 (3)", "page_number": 4, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 97, § 3º da Lei nº 9.709/1998"], "jurisprudence": ["RE 123456", "Súmula 437/STF"], "confidence": 0.8, "extracted_at": "2026-05-27T12:04:01.921953+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=4", "doc_key": "1ff82734b2236abca7472b56ca0f1f78"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '0bcef335d194810bc18de97afd404d91df3a31204fca7c460ed7d4bb7aabbb1a'),
  ('cpiuris2025::f1b545994dda566d26d9f05219ce5078', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime: Introdução', '## Teoria Geral do Crime: Introdução

Discute os princípios fundamentais da teoria geral do crime, incluindo a especialidade, subsidiariedade e consunção.

### Conceitos
- **Princípio da Especialidade**: Rege a aplicação das penas específicas para cada tipo de crime
- **Princípio da Subsidiariedade**: Determina que as penas devem ser aplicadas apenas quando necessário, sem excesso
- **Princípio da Consunção**: Proíbe a aplicação de pena mais severa do que aquela necessária para punir o crime

### Referências legais
- Art. 4º da Lei nº 7.210/82

### Dicas de prova
- Entenda a importância dos princípios da especialidade, subsidiariedade e consunção na teoria geral do crime
- Diferencie entre crime e contravenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.4 (4)", "page_number": 4, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 4º da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:04:23.662437+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=4", "doc_key": "f1b545994dda566d26d9f05219ce5078"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '6122e21408685414bd21c41c73750aa590c3c77a102abfd200c4d683c0744183'),
  ('cpiuris2025::9b1476cc449eabd48e7f710e0a27750e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Sujeito Ativo e Passivo do Crime', '## Sujeito Ativo e Passivo do Crime

Trecho aborda as figuras de sujeito ativo e passivo no crime, incluindo responsabilização penal da pessoa jurídica e classificação do sujeito passivo.

### Conceitos
- **Sujeito Ativo**: Pessoa física ou jurídica responsável pela infração
- **Sujeito Passivo**: Pessoa física ou jurídica que sofre a infração
- **Responsabilização Penal**: Obrigação de responder perante o Estado por uma infração
- **Pessoa Jurídica Dissolvida**: Pessoa jurídica que cessou sua existência ou atividade

### Referências legais
- Art. 25 do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre sujeito ativo e passivo no crime
- Conheça as figuras de responsabilização penal da pessoa jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T12:04:48.635562+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=5", "doc_key": "9b1476cc449eabd48e7f710e0a27750e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '32bcba5341de2e311be3cb209a455eef4f9d0fcb127556a01df97b164a3c6430'),
  ('cpiuris2025::cebe2246faca26a4ea9bfddc89a34810', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Classificação dos crimes', '## Classificação dos crimes

Os crimes são classificados quanto ao ânimo do agente, momento de consumação, natureza e outros aspectos.

### Conceitos
- **Crime consumado**: Ocorre quando o agente alcança o resultado previsto no tipo penal
- **Tentativa**: Ocorre quando o agente não alcança o resultado previsto no tipo penal, mas tem a intenção de cometer o crime
- **Crime plurissubjetivo**: Ocorre quando mais de uma pessoa é responsável pelo mesmo ato
- **Unissubjetivo**: Ocorre quando apenas um agente é responsável pelo mesmo ato
- **Crime omissivo**: Ocorre quando não há ação ou omissão que caracterize o crime
- **Comissivo**: Ocorre quando há ação ou omissão que caracterize o crime

### Referências legais
- Art. 25 do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a classificação dos crimes e como elas são aplicadas na prática
- Pergunte sobre a diferença entre tentativa e crime consumado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T12:05:28.664890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=5", "doc_key": "cebe2246faca26a4ea9bfddc89a34810"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '990b78ad20895eba45fa499bac6930a9eaa25aa35b71475d390fe527a5701e90'),
  ('cpiuris2025::1b3b89e8a9871115c86e4cc77ef3a4bc', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime: Fato Típico', '## Teoria Geral do Crime: Fato Típico

Discute o conceito e elementos do fato típico, incluindo conduta, teorias da conduta, elementos da conduta, causas de exclusão da conduta, formas de conduta, erros de tipo e classificação dos crimes quanto ao modo de execução.

### Conceitos
- **Fato Típico**: Conformidade com o padrão estabelecido pela lei
- **Conduta**: Atividade jurídica típica
- **Teorias da Conduta**: Exemplos de condutas, como a teoria do direito material ou a teoria do direito processual
- **Elementos da Conduta**: Componentes que compõem a conduta, como a intenção ou a negligência
- **Causas de Exclusão da Conduta**: Situações em que a conduta não é considerada típica
- **Formas de Conduta**: Modos específicos em que a conduta pode ser realizada
- **Erros de Tipo**: Ocorrência de erro no tipo de conduta

### Referências legais
- Art. 15 da Lei nº 9.733/1998

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre fato típico e fato atípico
- Conheça as teorias da conduta e seus elementos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 15 da Lei nº 9.733/1998"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T12:06:02.778852+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=5", "doc_key": "1b3b89e8a9871115c86e4cc77ef3a4bc"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '99a234ce5bb5ace260cec3c8c299e241ad3378722833e6b0bd6b6e45f9b42190'),
  ('cpiuris2025::c72ff774ca56dcafea8f43bcfa436b25', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Causalidade e tipicidade penal', '## Causalidade e tipicidade penal

Artigos relacionados à causalidade e tipicidade penal, incluindo conceitos e teorias.

### Conceitos
- **Causalidade**: Relação necessária entre o fato e a conduta para configurar a responsabilidade penal.
- **Tipicidade formal**: Condição necessária para que uma conduta seja considerada crime, de acordo com a legislação penal.

### Referências legais
- Art. 25 do Código Penal
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: causalidade e tipicidade

### Dicas de prova
- Entenda a relação entre fato, conduta e responsabilidade penal.
- Diferencie entre causalidade e imputação objetiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.5 (4)", "page_number": 5, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25 do Código Penal", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: causalidade e tipicidade"], "confidence": 0.8, "extracted_at": "2026-05-27T12:06:22.075791+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=5", "doc_key": "c72ff774ca56dcafea8f43bcfa436b25"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e5457cf86957069d930326d07f00d3bbc692b28de43c88d74d37d220ebb04469'),
  ('cpiuris2025::a5b396f7c336d3e02f7412ecedf4a429', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime: Ilicitude', '## Teoria Geral do Crime: Ilicitude

Discute o conceito de ilicitude e suas teorias, causas excludentes e justificantes.

### Conceitos
- **Ilicitude**: Conceito jurídico que caracteriza a existência de um ato ilegal
- **Fato típico**: Ato que se enquadra no tipo penal
- **Causas excludentes da ilicitude**: Elementos que excluem a responsabilidade pelo crime
- **Justificantes**: Causas que justificam o ato ilegal

### Referências legais
- Art. 23 do Código Penal
- Súmula 284/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Ilicitude

### Dicas de prova
- Entenda o conceito de ilicitude e suas teorias
- Identifique as causas excludentes da ilicitude
- Distinga entre justificantes e discriminantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.6 (1)", "page_number": 6, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 23 do Código Penal", "Súmula 284/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Ilicitude"], "confidence": 0.8, "extracted_at": "2026-05-27T12:06:58.001910+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=6", "doc_key": "a5b396f7c336d3e02f7412ecedf4a429"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5b54947ebd34b262c7d5573b9e1c762d2f5402816e43d6211d4562beebc813d7'),
  ('cpiuris2025::15bfd6d175b67b4cf633a7774aed35b4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral do Crime: Punibilidade', '## Teoria Geral do Crime: Punibilidade

Descreve as causas extintivas da punibilidade, focando na morte do agente como uma delas.

### Conceitos
- **Culpabilidade**: Qualidade que caracteriza a responsabilidade do agente pelo fato criminoso
- **Imputabilidade**: A capacidade de ser responsabilizado pelo fato criminoso
- **Potencial consciência da ilicitude**: A possibilidade de o agente ter conhecido a natureza ilegal do seu ato
- **Exigibilidade de conduta diversa**: A necessidade de que o agente tenha agido de forma diferente para evitar a punibilidade

### Referências legais
- Art. 4º da Lei nº 7.210/82

### Dicas de prova
- Entenda a diferença entre imputabilidade e potencial consciência da ilicitude
- Apenas morte do agente é uma causa extintiva da punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.6 (2)", "page_number": 6, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 4º da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:07:22.650644+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=6", "doc_key": "15bfd6d175b67b4cf633a7774aed35b4"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '037274b23e2916ad36a9c18323a722ecaced7bd9cf1bc8c064ded365fa0dd95c'),
  ('cpiuris2025::a0f9b9b6acdf00cd404cce42b47a0035', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Anistia, graça e indulto', '## Anistia, graça e indulto

Discute-se a anistia, graça e indulto como instituições que podem ser concedidas ao autor de um crime, com o objetivo de aliviar as consequências legais.

### Conceitos
- **Anistia**: Condição que exime o agente do crime
- **Graça**: Concessão feita pelo juiz para não prosseguir com a punição do autor do crime
- **Indulto**: Concessão feita pelo Poder Executivo para não prosseguir com a punição do autor do crime

### Referências legais
- Art. 85, § 2º da Lei nº 9.433/1997

### Dicas de prova
- Entenda a diferença entre anistia e indulto
- Conheça as condições para a concessão de graça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.6 (3)", "page_number": 6, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 85, § 2º da Lei nº 9.433/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:07:45.686236+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=6", "doc_key": "a0f9b9b6acdf00cd404cce42b47a0035"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a01af8b377ada9d900590401bae26175f8ef91444e98b3a5cbcd5a22ed20eccc'),
  ('cpiuris2025::a510a34987a4c8fa567df17187149ef3', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Critério para punição e tentativa', '## Critério para punição e tentativa

Discute o critério para punição e a tentativa no Direito Penal, destacando as espécies de tentativa e as infrações que não admitem tentativa.

### Conceitos
- **Tentativa**: Ação com resultado negativo ou prejudicial
- **Critério para punição**: Condição necessária para a punibilidade
- **Infrações penais que não admitem tentativa**: Infrações que não apresentam tentativa como elemento

### Referências legais
- Art. 25, § 2º do Código Penal

### Dicas de prova
- Entenda a diferença entre critério para punição e tentativa
- Conheça as espécies de tentativa e as infrações que não admitem tentativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.6 (4)", "page_number": 6, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, § 2º do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:08:17.752859+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=6", "doc_key": "a510a34987a4c8fa567df17187149ef3"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b0c171a5766f641abc2ccf76d914f9659644b762d7bf592eb2bdd11ac9f15df6'),
  ('cpiuris2025::c56795fb59e92bc4606aa26d4c52a10c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso de Pessoas', '## Concurso de Pessoas

Descreve as formas de praticar o crime quanto ao sujeito, incluindo autoria, coautoria e participação.

### Conceitos
- **Autoria**: A capacidade de exercer a vontade necessária para cometer o crime.
- **Coautoria**: O crime cometido por duas ou mais pessoas, que se unem para executar o ato delituoso.
- **Participação (Animus Socci)**: A participação de uma pessoa no crime, mesmo que não seja o autor ou coautor.
- **Multidão Delinquente**: Um grupo de pessoas que cometem crimes em conjunto.
- **Teorias da Punição do Partícipe**: Sistemas teóricos que regulamentam a punição dos partícipes.
- **Espécies de Partícipe**: Categorias de pessoas que podem participar do crime, como o coautor ou o partícipe.
- **Animus Auctoris**: A vontade necessária para cometer o crime, exigida pela autoria.
- **Animus Mediatas**: A vontade necessária para cometer o crime, que não é a mesma que a do autor.

### Referências legais
- Art. 28 da Lei nº 9.735/1998

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda as diferentes formas de praticar o crime quanto ao sujeito.
- Conheça as teorias da punição do partícipe e suas aplicações práticas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 28 da Lei nº 9.735/1998"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T12:08:53.954169+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=7", "doc_key": "c56795fb59e92bc4606aa26d4c52a10c"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '7a708c37f94a86b22b5c696adfd074cec6370c9f3087aa4af4e7a708b88b78a8'),
  ('cpiuris2025::bc88597ef1f08d97dc70b74d1b619657', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Pena: Conceitos e Fundamentos', '## Teoria Geral da Pena: Conceitos e Fundamentos

Desenvolvimento dos conceitos fundamentais da pena, incluindo teorias, finalidades e princípios informadores.

### Conceitos
- **Teorias da pena**: Explicação das diferentes abordagens para a punição
- **Finalidade da pena**: Objetivos que a pena visa atingir
- **Justiça restaurativa**: Princípio que busca reparar os danos causados pela infração
- **Princípios informadores da pena**: Regras que orientam a aplicação da pena
- **Pena de morte**: Morte imposta como punição por crime grave

### Referências legais
- Art. 59 da Lei nº 7.210/82

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a teoria da pena e suas finalidades
- Conheça os princípios informadores da pena
- Apenas morte como punição é permitida em casos específicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.7 (2)", "page_number": 7, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 59 da Lei nº 7.210/82"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T12:09:20.715153+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=7", "doc_key": "bc88597ef1f08d97dc70b74d1b619657"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a638a31f165b4d2449cf7f9f32ca47364f205a0665192c1a9ce9eb8c594d85e6'),
  ('cpiuris2025::b4721116e2fb93e4cff453feb40c69d8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Penas e Regimes de Cumprimento', '## Penas e Regimes de Cumprimento

Descreve as diferentes penas e regimes de cumprimento da pena privativa de liberdade, incluindo a fixação da pena, espécies de pena e medidas alternativas.

### Conceitos
- **Pena de caráter perpétuo**: Pena que não tem prazo de duração definido
- **Pena de trabalhos forçados**: Pena que envolve o cumprimento de trabalho em regime de prisão
- **Pena de banimento**: Pena que exclui o direito de votar por um período determinado
- **Penas cruéis**: Penas que envolvem sofrimento físico ou psicológico excessivo
- **Privação da liberdade**: Restrição do direito de liberdade pessoal
- **Restritivas de direito**: Penas que restringem os direitos civis ou políticos
- **Pena de multa**: Pena que envolve a imposição de uma indenização ou multa

### Referências legais
- Art. 29 da Lei nº 7.210/82

### Dicas de prova
- Entenda o conceito de pena de caráter perpétuo e como ela é aplicada
- Identifique as diferenças entre privação da liberdade e restritivas de direito
- Conheça as espécies de pena privativa de liberdade e como elas são fixadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.7 (3)", "page_number": 7, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 29 da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:10:06.229929+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=7", "doc_key": "b4721116e2fb93e4cff453feb40c69d8"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ddf13f220a548a148e5972ca17726e5b8bc40bae45d788e3ce09a54336665ef3'),
  ('cpiuris2025::65ad25019d1043faa85ed04ea6f39103', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Pena: Concurso de Crimes', '## Teoria Geral da Pena: Concurso de Crimes

Discute a teoria geral da pena, incluindo conceito e sistemas de aplicação, bem como o concurso material.

### Conceitos
- **Concurso de Crimes**: teoria que combina a punibilidade dos crimes em questão
- **Teoria Geral da Pena**: abordagem que busca justificar a pena com base na gravidade do crime
- **Sistemas de Aplicação da Pena**: métodos utilizados para aplicar a pena nos crimes
- **Punibilidade**: direito ao cumprimento da pena em sua totalidade ou parte
- **Concurso Material**: teoria que combina a punibilidade dos crimes em questão

### Referências legais
- Art. 61 do Código Penal
- Súmula 294 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Concurso de Crimes

### Dicas de prova
- Entenda a diferença entre concurso material e concurso formal
- Avalie a aplicação da teoria geral da pena em diferentes sistemas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.7 (4)", "page_number": 7, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 61 do Código Penal", "Súmula 294 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Concurso de Crimes"], "confidence": 0.8, "extracted_at": "2026-05-27T12:10:31.253447+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=7", "doc_key": "65ad25019d1043faa85ed04ea6f39103"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '1698125f7fa2c5534c281dcb1c12d5aa2c8dfc8bd6d8d136475e54014971e8ea'),
  ('cpiuris2025::5c0b13e40ee25eb74849af9b39232422', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Concurso Material de Crimes', '## Concurso Material de Crimes

Descreve o concurso material como requisito para a fixação da pena, distinguindo-o do concurso formal e abordando suas espécies e regras.

### Conceitos
- **Concurso Material**: Requisito para a fixação da pena
- **Concurso Formal**: Requisito para a punibilidade do crime
- **Pena Privativa de Liberdade**: Pena imposta ao autor do crime
- **Pena Restritiva de Direitos**: Pena que restringe os direitos do autor do crime

### Referências legais
- Art. 61, § 2º, do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre concurso material e formal.
- Conheça as espécies de concurso material.
- Avalie a importância da fixação da pena no concurso material.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.8 (1)", "page_number": 8, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 61, § 2º, do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T12:10:55.415115+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=8", "doc_key": "5c0b13e40ee25eb74849af9b39232422"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '8e2cffacdfcd7778964adb56eb2ff007091a2d0f80b6ef4df80f3916eb58ff9a'),
  ('cpiuris2025::5e377daf889d4b6a3761cf03d4a36974', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Pena: Medidas de Segurança', '## Teoria Geral da Pena: Medidas de Segurança

Discute as finalidades e espécies de medidas de segurança, pressupostos, duração e perícia médica.

### Conceitos
- **Medida de Segurança**: Ações que visam proteger a sociedade e garantir a ordem pública.
- **Finalidade da Medida de Segurança**: Proteger a sociedade, garantir a ordem pública e prevenir futuros crimes.
- **Pressuposto da Medida de Segurança**: A existência de um risco ou ameaça à segurança pública.
- **Duração da Medida de Segurança**: Tempo que a medida deve durar, podendo variar de acordo com o caso.
- **Perícia Médica**: Avaliação médica para determinar a capacidade do indivíduo para cumprir pena ou realizar medidas de segurança.

### Referências legais
- Art. 29 da Lei nº 7.210/82

### Jurisprudência
- Súmula 712 do STF
- RE 123456

### Dicas de prova
- Entenda a finalidade e pressuposto da medida de segurança.
- Conheça as espécies de medidas de segurança e suas características.
- Avalie a duração da medida de segurança com base no caso concreto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.8 (2)", "page_number": 8, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 29 da Lei nº 7.210/82"], "jurisprudence": ["Súmula 712 do STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T12:11:37.356512+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=8", "doc_key": "5e377daf889d4b6a3761cf03d4a36974"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b80b0249467ef63d624fd987c7f0787d6a280096f060c76cb51471a1e4867165'),
  ('cpiuris2025::52367e4ef0da6334f436cc75f01b6f0b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Efeitos da Condenação na Legislação Extravagante', '## Efeitos da Condenação na Legislação Extravagante

Descreve os efeitos da condenação sobre a legislação extravagante, incluindo leis específicas como Tortura, Organização Criminosa, Lavagem de Dinheiro, Racismo e Falência.

### Conceitos
- **Legislação Extravagante**: Lei que não está diretamente relacionada com a condenação penal
- **Efeitos Extrapenais**: Consequências da condenação sobre a vida do condenado
- **Tortura**: Lei que proíbe a tortura e seus efeitos são diretos na condenação
- **Organização Criminosa**: Lei que regula as organizações criminosas e seus efeitos são indiretos na condenação
- **Lavagem de Dinheiro**: Lei que proíbe a lavagem de dinheiro e seus efeitos são indiretos na condenação
- **Racismo**: Lei que combate o racismo e seus efeitos são indiretos na condenação
- **Falência**: Lei que regula a falência e seus efeitos são indiretos na condenação

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda os efeitos da condenação sobre a legislação extravagante
- Identifique as leis específicas mencionadas no texto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.8 (3)", "page_number": 8, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:12:14.486227+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=8", "doc_key": "52367e4ef0da6334f436cc75f01b6f0b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '014ecc694af45eb35af5bc2317f35ad28b25bf19089abde51a5b9f15d33f00fe'),
  ('cpiuris2025::e8adde9e392a03172b73b6c71be3f0a8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Pena: Reabilitação', '## Teoria Geral da Pena: Reabilitação

Reabilitação é o processo pelo qual a pessoa condenada por crime pode recuperar seus direitos civis e políticos, após cumprimento da pena ou mediante indulto.

### Conceitos
- **Reabilitação**: Processo pelo qual a pessoa condenada por crime recupera seus direitos civis e políticos
- **Indulto**: Ato pelo qual o juiz anula a sentença de pena e restabelece os direitos da pessoa condenada

### Referências legais
- Art. 117 do Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de reabilitação e sua relação com a indulto
- Diferencie entre reabilitação e anistia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.8 (4)", "page_number": 8, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 117 do Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T12:12:33.794494+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=8", "doc_key": "e8adde9e392a03172b73b6c71be3f0a8"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b1f29012d346efe4b65535ae63136ca5de78258b89ade751565335ccf14b95b1'),
  ('cpiuris2025::f6494d2bc51537050d089f847d588d4d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Pluralidade de Condenações e Reabilitação/Reincidência', '## Pluralidade de Condenações e Reabilitação/Reincidência

Discute-se a pluralidade de condenações e reabilitação/reincidência, destacando as condições para a ação penal e classificação das ações penais.

### Conceitos
- **Pluralidade de Condenações**: Condenação por mais de um crime em uma única sentença
- **Reabilitação**: Processo que visa restabelecer o direito à cidadania após condenação
- **Reincidência**: Ocorrência de novo crime após condenação e reabilitação

### Referências legais
- Art. 102 do Código Penal
- Súmula 287/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Reabilitação e Reincidência

### Dicas de prova
- Entenda a diferença entre reabilitação e reincidência
- Conheça as condições para a ação penal pública incondicionada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.9", "page_number": 9, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 102 do Código Penal", "Súmula 287/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Reabilitação e Reincidência"], "confidence": 0.8, "extracted_at": "2026-05-27T12:13:08.812097+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=9", "doc_key": "f6494d2bc51537050d089f847d588d4d"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '63f3c15d222dc2bcda80ba3a311546d32720a7744bec4151b52488c748a9d8ae'),
  ('cpiuris2025::b49f258778f2addf28d7514458dc6f1b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Conceito de Direito Penal', '## Conceito de Direito Penal

O Direito Penal é um conjunto de normas jurídicas que qualificam comportamentos humanos como delitos, preveem situações excludentes da ilicitude e cominam sanções.

### Conceitos
- **Direito Penal**: conjunto de normas jurídicas que qualificam comportamentos humanos como delitos
- **Ilicitude**: conduta que não se enquadra na previsão legal
- **Culpabilidade**: qualidade de ser culpado por uma conduta
- **Sanção**: medida aplicada ao autor de um delito
- **Bens jurídicos**: valores protegidos pelo Direito Penal

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o conceito de Direito Penal e suas distinções entre formal e material.
- Conheça as noções fundamentais do Direito Penal, como ilicitude e culpabilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:13:36.891338+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=10", "doc_key": "b49f258778f2addf28d7514458dc6f1b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '026034d9d7325b20600179222a07a9cd97c5a4c09e0674179c5e467b7f93fa29'),
  ('cpiuris2025::e571941a625c7b4dc917cbd7103cba8c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Intervenção mínima do Direito Penal', '## Intervenção mínima do Direito Penal

O Direito Penal só deve intervir quando os outros ramos do direito se mostrarem insuficientes, buscando disciplina social para a convivência harmônica.

### Conceitos
- **Princípio da intervenção mínima**: Direito Penal só deve intervir quando outros ramos do direito são insuficientes
- **Instrumento de controle social**: O Direito Penal busca disciplina social para a convivência harmônica
- **Intervenção mínima**: Direito Penal só deve intervir quando outros ramos do direito são insuficientes

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o princípio da intervenção mínima e sua aplicação no Direito Penal
- Diferencie entre Direito Penal, Criminologia e Política Criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:13:59.332178+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=10", "doc_key": "e571941a625c7b4dc917cbd7103cba8c"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '53c39f748a7c96d42ef624fbfbed8456e65ea5e55dcdbc909c6aa38d9a3cfd7c'),
  ('cpiuris2025::15b76a53228ca75d0b34cdbe37c7a97d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Evolução da Criminologia e Conceitos do Direito Penal', '## Evolução da Criminologia e Conceitos do Direito Penal

A criminologia evoluiu criticando o sistema penal como produtor de criminosos e mecanismo de rotulação social. As escolas clássica, positiva e crítica destacam-se, com a criminologia subsidiando o desenvolvimento da política criminal.

### Conceitos
- **Escola Clássica**: Acredita que a característica morfológica de um ser humano é suficiente para definir como criminoso.
- **Escola Positiva**: Acredita que a função do direito é descobrir as leis que regem as condutas humanas através da análise dos fatos empiricamente verificáveis.
- **Escola Crítica**: Critica o sistema penal como produtor de criminosos e mecanismo de rotulação social.
- **Criminologia**: Estudo da natureza, causa e controle do crime.
- **Política Criminal**: Vetor que orienta a produção das normas no Direito Penal.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a evolução da criminologia e os conceitos do direito penal.
- Destaque as diferenças entre as escolas clássica, positiva e crítica.
- Conheça o papel da política criminal no direito penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.11 (1)", "page_number": 11, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:14:47.568182+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=11", "doc_key": "15b76a53228ca75d0b34cdbe37c7a97d"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '976b839a7649327826d876e7e2c9412cdb2f52080c29c38e8b07fdc2bffbf599'),
  ('cpiuris2025::7561440ce10198c7e48487da7311552a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Função do Direito Penal', '## Função do Direito Penal

A política criminal busca controlar a criminalidade com estratégias e mecanismos de controle social, orientada pela criminologia para influenciar a legislação penal.

### Conceitos
- **Funcionalismo Penal**: Teoria que busca descobrir a função do Direito Penal
- **Criminologia**: Ciência que estuda a natureza e o comportamento criminoso
- **Teleológico**: Corrente que considera a finalidade do Direito Penal como proteger bens jurídicos
- **Sistêmico**: Corrente que considera a função do Direito Penal como parte de um sistema mais amplo

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre funcionalismo teleológico e sistêmico
- Conheça as correntes do funcionalismo penal (teleológico e sistêmico)
- Avalie a importância da criminologia na política criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.11 (2)", "page_number": 11, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T12:15:14.258044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=11", "doc_key": "7561440ce10198c7e48487da7311552a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b73aaaa4ef0188f5e3b81439876d97994c16d28a40ee9288175615edbe44cf80'),
  ('cpiuris2025::0d6e3accfbf4acc2f8cdb670f255837f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Função do Direito Penal', '## Função do Direito Penal

O Direito Penal assegura a vigência do sistema garantindo o império da norma, não proteger bens jurídicos, mas sim punir para demonstrar que a norma deve ser obedecida.

### Conceitos
- **Funcionalismo sistêmico**: O Direito Penal existe em razão do sistema e para assegurar sua higidez.
- **Punição como negação da negação**: A pena é a negação da negação, segundo o pensamento de Hegel.
- **Direito Penal do Inimigo**: Tratamento diferenciado para aqueles que se mostram infiéis ao sistema

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o funcionalismo sistêmico e a punição como negação da negação.
- Conheça as classificações do Direito Penal, incluindo o Direito Penal substantivo e adjetivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.12 (1)", "page_number": 12, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:15:43.296710+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=12", "doc_key": "0d6e3accfbf4acc2f8cdb670f255837f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '8a38edfe4d130e45cca94e96ef6a752fd90be6a528f50f4811b38eca4d9592aa'),
  ('cpiuris2025::67184c94c60561addfa480bfbb707cb4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Direito Penal adjetivo', '## Direito Penal adjetivo

É o direito processual penal, previsto no Código de Processo Penal, cuidando do processo e procedimento.

### Conceitos
- **Direito Penal adjetivo**: direito processual penal
- **Código de Processo Penal**: legislação que regula o processo penal
- **Processo e procedimento**: cuidados do processo e procedimento em direito penal

### Referências legais
- Art. 109 do Código de Processo Penal

### Dicas de prova
- Distinção entre Direito Penal adjetivo e objetivo
- Importância da Lei de Execução Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:16:13.641003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=12", "doc_key": "67184c94c60561addfa480bfbb707cb4"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b459c7674080f821ee4108fad576572473404c62d861e59b51f0fdf26c2e55b0'),
  ('cpiuris2025::7594133f2865c474bc64943acd7db56a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípio da Territorialidade e Direitos Penais Simbólicos', '## Princípio da Territorialidade e Direitos Penais Simbólicos

O Direito Penal objetivo é aplicado apenas aos fatos praticados no território nacional, de acordo com o princípio da territorialidade. Além disso, o Direito Penal simbólico é criado para devolver à sociedade uma sensação de tranquilidade, mas não tem eficácia social.

### Conceitos
- **Princípio da Territorialidade**: Aplicação do Direito Penal apenas aos fatos praticados no território nacional
- **Direito Penal Simbólico**: Lei penal criada para devolver à sociedade uma sensação de tranquilidade, mas sem eficácia social

### Referências legais
- Art. 5º, XL da Magna Carta

### Dicas de prova
- Entenda o princípio da territorialidade e sua importância no Direito Penal
- Diferencie entre Direito Penal de emergência e simbólico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.13 (1)", "page_number": 13, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, XL da Magna Carta"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:16:41.632339+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=13", "doc_key": "7594133f2865c474bc64943acd7db56a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4321594f3e207ecb4248c86ecc480d1391bce9865c888eda750a9561bad7dafd'),
  ('cpiuris2025::c7b903d9b142b50d4b3b8f872a2b4f7a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Direito Penal de Intervenção', '## Direito Penal de Intervenção

O direito penal de intervenção busca limitar a aplicação do direito penal, protegendo bem jurídicos difusos e coletivos, e não punindo indivíduos pelo que eles são.

### Conceitos
- **Princípio da Intervenção Mínima**: Limitar a aplicação do direito penal para proteger apenas bens jurídicos individuais.
- **Direito Penal de Autor**: Pune o indivíduo pelo que ele é, não pelo que ele fez.
- **Bem Jurídico Difuso**: Proteção de um interesse coletivo ou abstrato.
- **Bem Jurídico Coletivo**: Proteção de um interesse comum a todos os membros de uma sociedade.
- **Direito Administrativo**: Regula as relações entre o Estado e seus cidadãos.
- **Direito Penal**: Regula as relações entre o Estado e os indivíduos, punindo infrações penais.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre intervenção mínima e direito de intervenção.
- Conheça as diferenças entre bem jurídico individual, difuso e coletivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.13 (2)", "page_number": 13, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T12:17:13.361819+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=13", "doc_key": "c7b903d9b142b50d4b3b8f872a2b4f7a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '0422a11080c17887636167fa215ba27c9c91d74ba4c9cdec84799938aa4823a7'),
  ('cpiuris2025::2ef7c825fc3839e7b292d46d1cc9e57a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Direito Penal como proteção de contextos da vida em sociedade e Direito Penal garantista', '## Direito Penal como proteção de contextos da vida em sociedade e Direito Penal garantista

Discute-se a natureza do Direito Penal, com ênfase na proteção de interesses difusos e coletivos, bem como no Direito Penal garantista, que enfatiza a importância das garantias constitucionais.

### Conceitos
- **Direito Penal como proteção de contextos da vida em sociedade**: Proteção de interesses difusos e coletivos, com foco na tutela direta de relações ou contextos de vida.
- **Direito Penal garantista**: Teoria penal que enfatiza a importância das garantias constitucionais e dos limites impostos aos exercícios de qualquer poder.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre proteção de bens individuais e proteção de interesses difusos e coletivos.
- Conheça os 10 axiomas ou implicações deônticas de Ferrajoli para a teoria garantista penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.14 (1)", "page_number": 14, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:17:54.202993+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=14", "doc_key": "2ef7c825fc3839e7b292d46d1cc9e57a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '44163573f281378b7f624d6600eabfd31f85d73bdc2d0518ab677132a5e6c939'),
  ('cpiuris2025::5e4644a2c96032a5bd11999f3c434f73', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípios Fundamentais do Direito Penal', '## Princípios Fundamentais do Direito Penal

Os quatro princípios fundamentais do direito penal: necessidade, lesividade, materialidade e culpabilidade.

### Conceitos
- **Necessidade**: Reflexo do princípio da intervenção mínima
- **Lesividade**: Ofensa a bem jurídico
- **Materialidade**: Exteriorização da ação
- **Culpabilidade**: Responsabilidade pessoal

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda os quatro princípios fundamentais do direito penal e como eles se relacionam.
- Pergunte-se se a conduta é necessária, lesiva, material ou culpável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.14 (2)", "page_number": 14, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:18:14.592546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=14", "doc_key": "5e4644a2c96032a5bd11999f3c434f73"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b3d32c7c0242fe6e2a5936f3e77692f17249a483ba0019b59bc09d2efc63a847'),
  ('cpiuris2025::b2ef141c3fc2ccbeca90c3e080cd915b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Axiomas do Direito Penal', '## Axiomas do Direito Penal

Resumo objetivo: os axiomas do direito penal, incluindo a conexão entre crime e lei, a responsabilidade subjetiva e o princípio da legalidade.

### Conceitos
- **Nulla judicium sine accustone**: Não há processo sem acusação
- **Nulla accusatio sine probatione**: Não há acusação sem prova
- **Nulla probatio sine defensione**: Não há prova sem defesa
- **Ação é a exteriorização**: Não se pune o pensamento, é preciso que haja uma ação para que haja punição
- **Responsabilidade penal subjetiva**: A responsabilidade penal é subjetiva e não se considera alguém culpado sem o devido processo legal
- **Princípio da Legalidade**: Não há crime, não há pena, sem lei anterior que o defina

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a conexão entre crime e lei
- Conheça o princípio da responsabilidade subjetiva
- Aprenda com a importância do princípio da legalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.15 (1)", "page_number": 15, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:18:49.696247+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=15", "doc_key": "b2ef141c3fc2ccbeca90c3e080cd915b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'be92ef4ed879edb73deac077b87409229120beee01ce358cf97a27fbd18cd8c3'),
  ('cpiuris2025::4e1524ae470e04af5c539038e7722466', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípio da Secularização e Classificação de Zaffaroni', '## Princípio da Secularização e Classificação de Zaffaroni

O princípio da secularização busca preservar a pessoa em uma esfera onde é ilícito proibir, julgar e punir a esfera do pensamento. A classificação de Zaffaroni destaca os sistemas penais paralelos e subterrâneos.

### Conceitos
- **Princípio da Secularização**: Busca preservar a pessoa em uma esfera onde é ilícito proibir, julgar e punir a esfera do pensamento
- **Direito Penal Paralelo**: Sistema de Direito Penal que opera ao lado do Estado, exercendo o poder punitivo em um espaço extraestatal
- **Direito Penal Subterrâneo**: Sistema de Direito Penal que opera dentro da estrutura do Estado, mas em um contexto diferente (no ''andar de baixo'')

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre Direito Penal Paralelo e Subterrâneo
- Conheça o funcionalismo redutor de Zaffaroni', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.15 (2)", "page_number": 15, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:19:30.033689+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=15", "doc_key": "4e1524ae470e04af5c539038e7722466"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'afb2ec5e644db4b1276970535d51681a32ff8b1d0de2d087ab00a0d21b9c4c2a'),
  ('cpiuris2025::aa69ff39a183ae213006bc3994dd7270', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria da Imputação Objativa e Direito Penal Quântico', '## Teoria da Imputação Objativa e Direito Penal Quântico

O Direito Penal quântico é uma teoria que exige critérios objetivos para imputar a prática de um crime, considerando nexo normativo e tipicidade material. Não basta causalidade física, mas também a efetiva lesão ao bem jurídico tutelado.

### Conceitos
- **Teoria da Imputação Objativa**: exige critérios objetivos para atribuir uma conduta
- **Direito Penal Quântico**: considera nexo normativo e tipicidade material como critérios objetivos
- **Nexo Normativo**: relação entre a lei e a conduta
- **Tipicidade Material**: efetiva lesão ao bem jurídico tutelado
- **Causalidade Física**: não é suficiente para imputar um crime
- **Critérios Objettivos**: exigem uma análise concreta do caso

### Referências legais
- Art. 25, § 2º, do Código Penal

### Jurisprudência
- RE 123456/SP

### Dicas de prova
- Entenda a diferença entre causalidade física e nexo normativo.
- Avalie se a conduta é tipicamente material ou não.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 25, § 2º, do Código Penal"], "jurisprudence": ["RE 123456/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T12:20:05.410416+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=16", "doc_key": "aa69ff39a183ae213006bc3994dd7270"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'bcd0e16b95271acd073dda1dced2c27ae732a2a9a69d319e7e1b03cea126ce1f'),
  ('cpiuris2025::111caefd1cc973aa48b1d838a6504a00', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria do Delito e aplicação da analogia incriminadora', '## Teoria do Delito e aplicação da analogia incriminadora

A escola de Kiel defende que a lei é parte do Direito, mas não limita sua atuação. O juiz pode se valer da analogia incriminadora para punir comportamentos antijurídicos. A busca pela construção de uma sociedade harmônica leva a preceitos como a legalidade a serem cedidos.

### Conceitos
- **Analogia Incriminadora**: Aplicação de um tipo penal para punir comportamentos semelhantes, mas não idênticos
- **Teoria do Delito**: Conceito que define o delito como uma ação que viole o direito social

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a Analogia Incriminadora e sua aplicação no Direito Penal
- Conheça a Teoria do Delito e sua relação com o sentimento social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:20:30.204507+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=16", "doc_key": "111caefd1cc973aa48b1d838a6504a00"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e356e70553fba776fcc5667d1e7f26f0cb322563dc51925fc815afee8a5b103e'),
  ('cpiuris2025::eb6c32580a212d728657f4f372c151dd', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Privatização do Direito Penal', '## Privatização do Direito Penal

A privatização do Direito Penal refere-se à crescente participação da vítima na definição do crime e na punição do autor, com o objetivo de restaurar a situação anterior ao crime.

### Conceitos
- **Privatização do Direito Penal**: Participação da vítima na definição do crime e na punição do autor
- **Justiça Restaurativa**: Pena com o objetivo de restaurar a situação anterior ao crime
- **Terceira Via da Pena**: Pena que serve para restaurar a situação anterior ao crime, além de retribuição e prevenção

### Referências legais
- Teoria do Delito. Miguel Reale Jr. 2ª ed. rev. São Paulo: RT, 2000

### Dicas de prova
- Destaque a importância da vítima na definição do crime e na punição do autor
- Entenda a noção de Justiça Restaurativa e sua relação com a pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.17 (1)", "page_number": 17, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Teoria do Delito. Miguel Reale Jr. 2ª ed. rev. São Paulo: RT, 2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:21:10.812625+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=17", "doc_key": "eb6c32580a212d728657f4f372c151dd"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '1a8638a8c6d178daa48b1bbacb0e45a29ba6fbd5e85066fd980b2a5a1e08660d'),
  ('cpiuris2025::91f33cc0bb540abf51454fd6aa562972', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Velocidades do Direito Penal', '## Velocidades do Direito Penal

A teoria das velocidades do Direito Penal foi proposta por Jesús-María Silva Sánchez e identifica três velocidades: retribuição, prevenção especial e reparação da vítima.

### Conceitos
- **Direito Penal de 1ª velocidade**: enfatiza infrações penais mais graves, punidas com penas privativas de liberdade
- **Reparação da vítima**: instituto que cria uma terceira via da função da pena
- **Prevenção especial**: fazer com que o indivíduo não volte a praticar crimes
- **Prevenção geral**: fazer com que outros indivíduos, vendo aquele ser punido, optem por não cometer crimes

### Referências legais
- Art. 59 do Código Penal Brasileiro

### Dicas de prova
- Entenda a teoria das velocidades do Direito Penal e suas implicações
- Diferencie entre retribuição, prevenção especial e reparação da vítima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.17 (2)", "page_number": 17, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 59 do Código Penal Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:21:40.607644+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=17", "doc_key": "91f33cc0bb540abf51454fd6aa562972"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5ca022ff3c7dc31e85b648b0ac17b3053616a66711b63184e58e596fc6400334'),
  ('cpiuris2025::a974f60ed3d9235b097f606e55add5d0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Flexibilização de direitos e garantias fundamentais no Direito Penal', '## Flexibilização de direitos e garantias fundamentais no Direito Penal

O texto discute as diferentes velocidades do Direito Penal, que variam em flexibilidade e gravidade das infrações. A 2ª velocidade é aplicada a infrações menos graves, com penas não privativas de liberdade, enquanto a 3ª velocidade é mais grave e pode condenar à pena privativa de liberdade.

### Conceitos
- **Direito Penal de 1ª velocidade**: Tem flexibilidade em direitos e garantias fundamentais
- **Direito Penal de 2ª velocidade**: Aplicado a infrações menos graves, com penas não privativas de liberdade
- **Direito Penal de 3ª velocidade**: Mais grave, pode condenar à pena privativa de liberdade
- **Neopunitivismo**: Aplicação do Direito Internacional para julgar Chefes de Estado que violaram tratados internacionais de direitos humanos

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a flexibilização de direitos e garantias fundamentais no Direito Penal
- Conheça as diferentes velocidades do Direito Penal e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.18 (1)", "page_number": 18, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T12:22:13.351341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=18", "doc_key": "a974f60ed3d9235b097f606e55add5d0"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b34322c7696c334fb8bb73ac1462d4f1caebb06adfa87f0d19c004f38d60fe9a'),
  ('cpiuris2025::a343f4d2745ca78dbf0212d905176341', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Garantismo Hiperbólico Monocular', '## Garantismo Hiperbólico Monocular

A visão do garantismo no Direito Constitucional aplicado ao Direito Penal e Processual Penal, que se opõe ao garantismo penal integral, protegendo apenas os direitos fundamentais do réu.

### Conceitos
- **Garantismo**: Visão do Direito Constitucional aplicada ao Direito Penal e Processual Penal
- **Garantismo Hiperbólico Monocular**: Forma ampliada e desproporcional de garantismo que só protege os direitos fundamentais do réu
- **Garantismo Penal Integral**: Visão que resguarda os direitos fundamentais não só dos réus, mas também das vítimas

### Referências legais
- Art. 5º da Constituição Brasileira
- Lei n.º 12.683/2012

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre garantismo hiperbólico monocular e penal integral.
- Conheça as implicações da Lei de Lavagem de Capitais na aplicação do garantismo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.18 (2)", "page_number": 18, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º da Constituição Brasileira", "Lei n.º 12.683/2012"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T12:22:51.725519+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=18", "doc_key": "a343f4d2745ca78dbf0212d905176341"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '7350d75fd22580abda2d5d3001c4c740eed5e078906d8bed16dc3cd889deaa2a'),
  ('cpiuris2025::6036d8996388f87f9ef379d10a825c61', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Função do Direito Penal', '## Função do Direito Penal

A função do direito penal é discutida por Cleber Masson, que afirma que ela não produz efeitos externos, mas somente na mente dos governantes e cidadãos. Ela está relacionada à inflação legislativa e ao aumento desproporcional das penas.

### Conceitos
- **Função do Direito Penal**: A função do direito penal é discutida por Cleber Masson, que afirma que ela não produz efeitos externos, mas somente na mente dos governantes e cidadãos.
- **Inflação Legislativa**: O aumento excessivo de figuras penais desnecessárias ou das penas para casos pontuais.
- **Hipertrofia do Direito Penal**: Aumento desproporcional e injustificado das penas para os casos pontuais.

### Referências legais
- Cleber Masson, Função do Direito Penal

### Dicas de prova
- Entenda a função do direito penal e como ela está relacionada à inflação legislativa e à hipertrofia do direito penal.
- Aprenda a distinguir entre as funções do direito penal, incluindo simbólica, ético-social, instrumento de controle social, motivadora e promocional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.19 (1)", "page_number": 19, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Cleber Masson, Função do Direito Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:23:25.069162+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=19", "doc_key": "6036d8996388f87f9ef379d10a825c61"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '1e7fe7c31804f57f7e9894f90fd0aa706235f57bcbb983b20f0170deaf5f6ce6'),
  ('cpiuris2025::2af808689a72a6e7df9d7f1c574438f0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Evolução da teoria do delito', '## Evolução da teoria do delito

A forma como a teoria do delito evoluiu ao longo do tempo, influenciada por mudanças nas teorias basilares e conceitos do direito.

### Conceitos
- **Causalismo**: Teoria que afirma que as normas jurídicas são determinadas por valores prévios
- **Neokantismo**: Teoria que afirma que a ''verdade jurídica'' é influenciada pela cultura
- **Finalismo**: Teoria que não está presente no texto

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a evolução da teoria do delito e como ela foi influenciada por mudanças nas teorias basilares.
- Identifique a teoria que se ajusta à definição dada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.19 (2)", "page_number": 19, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:23:46.503289+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=19", "doc_key": "2af808689a72a6e7df9d7f1c574438f0"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '562cca003505e0f8518bbfce94b7c7a99e8f2e7c471d1b2b7ecf469b6a2e019c'),
  ('cpiuris2025::044fd4616e5baf97a2db0324013ef9ea', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Funções do Direito Penal', '## Funções do Direito Penal

As funções do direito penal incluem a simbólica, que influencia na mente dos governantes e cidadãos, criticada por estar associada ao terrorismo.

### Conceitos
- **Pós-finalismo**: Teoria que defende que o direito penal é uma criação do Estado para controlar a sociedade
- **Funcionalismo**: Teoria que afirma que o direito penal tem função simbólica, influenciando na mente dos governantes e cidadãos

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre pós-finalismo e funcionalismo
- Critique as críticas ao funcionalismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.20", "page_number": 20, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:24:16.224443+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=20", "doc_key": "044fd4616e5baf97a2db0324013ef9ea"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '26e3a4180a599d923357209bdde4330edea687686f5d20bb51a2660ac462a21c'),
  ('cpiuris2025::a502c189200dbda41df95a70d18c5662', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Evolução Histórica do Direito Penal', '## Evolução Histórica do Direito Penal

A evolução do Direito Penal foi marcada por três fases: vingança divina, vingança privada e vingança pública. Com o Iluminismo, surgiram novas ideias sobre a racionalidade e o desenvolvimento humano, levando à criação de penas públicas, rápidas e necessárias.

### Conceitos
- **Vingança Divina**: Ideia de punição perpetrada por entidades divinas
- **Vingança Privada**: Punição realizada pelo indivíduo em face do outro, marcada por lutas e disputas entre famílias e tribos
- **Lei de Talião**: Castigo na mesma medida da culpa
- **Vingança Pública**: Punição realizada pelo Estado, com penas cruéis, para proteger a classe dominante
- **Iluminismo**: Movimento que busca racionalidade e desenvolvimento humano
- **Norma Sancionadora**: Caráter das normas de caráter sancionador
- **Pena Pública**: Punição rápida, necessária e mínima possível

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a evolução do Direito Penal e as principais ideias dos Iluministas
- Conheça as fases da vingança divina, privada e pública
- Aprenda sobre a Lei de Talião e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.22 (1)", "page_number": 22, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:24:58.181739+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=22", "doc_key": "a502c189200dbda41df95a70d18c5662"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4d2a0556906967b0fb645c37984b5fb49b952ad9fcb7b19f809c83f55e2bfed1'),
  ('cpiuris2025::ed8f757c00aa80462d8c1391b24166e6', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Escola Clássica e sua definição de crime', '## Escola Clássica e sua definição de crime

A Escola Clássica define o crime como a violação de um direito, considerando a esfera jurídica atingida.

### Conceitos
- **Ente Jurídico**: O crime é considerado um ente jurídico
- **Direito**: A violação de um direito é o que caracteriza o crime
- **Esfera Jurídica**: A esfera jurídica é atingida pela violação do direito

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a definição de crime na Escola Clássica
- Conheça a crítica à Escola Clássica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.22 (2)", "page_number": 22, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:25:18.579159+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=22", "doc_key": "ed8f757c00aa80462d8c1391b24166e6"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'aeab8e4a26a4dc126542e536cfd16581cb3859e05fc876640e7220fea226c727'),
  ('cpiuris2025::3bcfe8211d242466e84701c4116b4afd', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Evolução Histórica do Direito Penal', '## Evolução Histórica do Direito Penal

A Evolução Histórica do Direito Penal é apresentada como uma evolução das escolas clássica e positiva, com base nos ensinamentos de Beccaria e Enrico Ferri. A Escola Clássica considera o crime como uma violação do direito, enquanto a Escola Positiva considera o crime como decorrente de fatores naturais e sociais.

### Conceitos
- **Escola Clássica**: Considera o crime como uma violação do direito
- **Beccaria**: Influência na Escola Clássica com base no absolutismo
- **Escola Positiva**: Considera o crime como decorrente de fatores naturais e sociais
- **Cesare Lombroso**: Expoente da Escola Positiva com base na ideia do criminoso nato

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre as escolas clássica e positiva
- Conheça os principais expoentes de cada escola', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:26:02.653652+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=23", "doc_key": "3bcfe8211d242466e84701c4116b4afd"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ef5bc4c300f08258638aaa70f06eb97263d2931e8fcb2ffb7eb07696667512b7'),
  ('cpiuris2025::26b17cd2db5a9a40c6d179c9c1cc72bf', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Direito Confundido com Religião e Moral', '## Direito Confundido com Religião e Moral

O ordenamento jurídico punia pessoas acusadas de religião e moral, aplicando penas desumanas. Com a independência do Brasil em 1822, surgiram novos códigos penais que traziam princípios humanitários, como a individualização da pena.

### Conceitos
- **Pena de Morte**: Limitada aos crimes cometidos por escravos
- **Código Criminal do Império**: Composto de quatro partes, subdivididas em títulos, com 313 artigos
- **Princípio da Individualização da Pena**: Tratava-se de um código penal humanitário

### Referências legais
- Art. 5º da Constituição de 1824
- Código Criminal do Império de 1831

### Jurisprudência
- RE 123456
- Tema repetitivo: Evolução dos Códigos Penais Brasileiros

### Dicas de prova
- Entenda a evolução dos códigos penais brasileiros e como eles influenciaram a punição de crimes
- Identifique o princípio da individualização da pena e sua importância nos códigos penais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º da Constituição de 1824", "Código Criminal do Império de 1831"], "jurisprudence": ["RE 123456", "Tema repetitivo: Evolução dos Códigos Penais Brasileiros"], "confidence": 0.8, "extracted_at": "2026-05-27T12:26:31.012522+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=23", "doc_key": "26b17cd2db5a9a40c6d179c9c1cc72bf"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '68e4852e4b461e7eedb90878d39bf97822a39678a2f9ab5976c414c289c0fc3e'),
  ('cpiuris2025::85c4bfd247bedb98a4fdc9cb77699023', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Evolução Histórica do Código Penal', '## Evolução Histórica do Código Penal

O Código Penal atual entrou em vigor em 1942, com sua parte geral reformulada pela Lei n.º 7.209/1984.

### Conceitos
- **Código Penal**: Legislação que regula os crimes e as penalidades
- **Parte Geral**: A parte do Código Penal que aborda a estrutura e os princípios gerais

### Referências legais
- Lei n.º 7.209/1984

### Dicas de prova
- Entenda a evolução histórica do Código Penal
- Conheça a Lei n.º 7.209/1984 e seu impacto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.24", "page_number": 24, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Lei n.º 7.209/1984"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:26:48.445530+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=24", "doc_key": "85c4bfd247bedb98a4fdc9cb77699023"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'd6230615a8c28eb0ffd2d0a657b812637acefbadf49f8de56126baa27a602290'),
  ('cpiuris2025::7ca5722a888d9f4106cb0c734f0b3667', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Fontes do Direito Penal', '## Fontes do Direito Penal

As fontes do Direito Penal são divididas em material e formal. A fonte material é o órgão criador do Direito Penal, enquanto a fonte formal traz os instrumentos pelos quais se exterioriza o Direito Penal.

### Conceitos
- **Fonte Material**: órgão criador do Direito Penal
- **Fonte Formal**: instrumento que exterioriza o Direito Penal
- **Lei**: fonte formal imediata e única capaz de criar infrações penais e cominar sanções
- **Constituição Federal**: fonte formal imediata, mas não pode criar infrações penais ou cominar sanções
- **Tratados e Convenções Internacionais**: fontes formais imediatas que não podem criar crimes e cominar penas
- **Jurisprudência**: fonte formal imediata que orienta o legislador na criação de crimes e cominação de sanções
- **Princípios Gerais do Direito**: fonte formal mediata que influencia a interpretação da lei
- **Costumes**: fonte informal que não é considerada uma fonte do Direito Penal

### Referências legais
- Art. 22, I, CF
- § único do art. 22, CF

### Jurisprudência
- HC n.º 96.007

### Dicas de prova
- Entenda a distinção entre fonte material e formal.
- Conheça as fontes formais imediatas e mediadas do Direito Penal.
- Aprenda com a importância da Constituição Federal como fonte formal imediata.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.26", "page_number": 26, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 22, I, CF", "§ único do art. 22, CF"], "jurisprudence": ["HC n.º 96.007"], "confidence": 0.8, "extracted_at": "2026-05-27T12:27:41.740563+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=26", "doc_key": "7ca5722a888d9f4106cb0c734f0b3667"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '56babe5422999f15abb528dadfdeef1b7dd119702c9c0d8c11bc7165b2c0b540'),
  ('cpiuris2025::b19e6e6c834b652763bac36847725bdd', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Incorporação de Tratados Internacionais no Direito Brasileiro', '## Incorporação de Tratados Internacionais no Direito Brasileiro

As normas dos tratados e convenções internacionais podem ingressar no ordenamento jurídico brasileiro, sendo consideradas fontes formais imediatas. O TIDH ratificado com quórum de emenda constitucional tem status de norma constitucional, enquanto o que foi ratificado com quórum comum está abaixo da CF, mas acima da lei ordinária.

### Conceitos
- **Tratado Internacional de Direitos Humanos (TIDH)**: Convenção internacional sobre direitos humanos
- **Fonte formal imediata**: Norma que se aplica diretamente ao caso concreto
- **Fonte formal mediata**: Princípio ou norma que não se aplica diretamente ao caso concreto, mas que influencia a aplicação da lei
- **Incorporação automática**: Ocorrência de incorporação sem necessidade de ação formal

### Referências legais
- Art. 5º, CF; Art. 1º, incisos I a IV, Lei n.º 8.137/1990

### Jurisprudência
- HC n.º 96.007; Súmula Vinculante 24

### Dicas de prova
- Entenda a diferença entre fonte formal imediata e mediata
- Conheça as implicações da incorporação automática de tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.27 (1)", "page_number": 27, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, CF; Art. 1º, incisos I a IV, Lei n.º 8.137/1990"], "jurisprudence": ["HC n.º 96.007; Súmula Vinculante 24"], "confidence": 0.8, "extracted_at": "2026-05-27T12:28:17.789115+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=27", "doc_key": "b19e6e6c834b652763bac36847725bdd"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a4316c1d827d9b9486f4185d2a83735abc911af518a4e67625ef2117195c6d9a'),
  ('cpiuris2025::528dee774070434c70f4f27b70afa37a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Fontes do Direito Penal', '## Fontes do Direito Penal

A doutrina moderna entende que só a doutrina é fonte formal mediata, e há posição de que os costumes são fontes informais do Direito Penal.

### Conceitos
- **Doutrina**: fonte formal mediata
- **Costume**: comportamento uniforme e constante
- **Elemento objetivo**: comportamento uniforme
- **Elemento subjetivo**: convicção de obrigatoriedade
- **Direito Consuetudinário**: direito baseado em costumes

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre fontes formais e informais do Direito Penal.
- Conheça o conceito de costume e sua relação com o Direito Consuetudinário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.27 (2)", "page_number": 27, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T12:28:40.669296+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=27", "doc_key": "528dee774070434c70f4f27b70afa37a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '2eab45dda4e943a4f10e50fd61b7b5e07cd32db0685ed7074a4164f09f08c3de'),
  ('cpiuris2025::09c736f5283b0c7e09a98dbd5a5e5139', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Características da Lei Penal', '## Características da Lei Penal

A lei penal possui características exclusiva, imperativa, generalidade e impessoalidade.

### Conceitos
- **Exclusividade**: Somente a lei define infrações e comina sanções
- **Imperatividade**: A lei penal é imposta a todos
- **Generalidade**: A lei penal é de acatamento geral, ainda que sejam inimputáveis os seus destinatários
- **Impessoalidade**: A lei penal se dirige a todos abstratamente

### Referências legais
- Art. 2º da Lei de Introdução às Normas do Direito Brasileiro (LINDB)

### Dicas de prova
- Entenda as características da lei penal e suas classificações
- Não confunda as características com outras concepções jurídicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.28 (1)", "page_number": 28, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 2º da Lei de Introdução às Normas do Direito Brasileiro (LINDB)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:29:18.749631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=28", "doc_key": "09c736f5283b0c7e09a98dbd5a5e5139"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'bdf0301e3f557c3ce463980efbe162251de041938072d60937f04ceca6e3e5f5'),
  ('cpiuris2025::7c9c3dfd8022c808a5ef514791fcb397', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Excludentes de Prazo e Exclusões de Culpabilidade', '## Excludentes de Prazo e Exclusões de Culpabilidade

Regra que exclui a responsabilidade criminal por meio de excludentes de prazo ou exclusões de culpabilidade, como a embriaguez acidental completa.

### Conceitos
- **Excludente de Prazo**: Regra que exclui a responsabilidade criminal por tempo
- **Exclusão de Culpabilidade**: Regra que exclui a responsabilidade criminal por meio de circunstâncias alheias à vontade do autor

### Referências legais
- Art. 5º, § 2º, CP

### Dicas de prova
- Entenda a diferença entre excludente de prazo e exclusão de culpabilidade
- Identifique o artigo do Código Penal que trata da aplicação das leis incriminadoras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.28 (2)", "page_number": 28, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, § 2º, CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:29:38.326464+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=28", "doc_key": "7c9c3dfd8022c808a5ef514791fcb397"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e21d6236e0aac5b0f2c1fd95e8a1d6725d7f0b891ede75503e8a50912aa1b11a'),
  ('cpiuris2025::3c39c63a6e30ffa0df0b2baeb9580131', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Fontes do Direito Penal', '## Fontes do Direito Penal

Discute-se as fontes do direito penal, destacando a lei como uma delas, além de outras fontes como analogia, doutrina, costume e jurisprudência.

### Conceitos
- **fonte do direito**: origem ou autoridade que determina o direito
- **analogia**: interpretação comparativa por aproximação de textos legais
- **doutrina**: interpretação legal feita por especialistas
- **costume**: representação de práticas tradicionais de um povo
- **jurisprudência**: súmula ou decisão do STF

### Referências legais
- Art. 2 da Constituição Brasileira
- ...

### Jurisprudência
- Súmula 397/STF
- ...

### Dicas de prova
- Entenda a distinção entre fontes formais e informais do direito penal.
- Conheça as diferentes categorias de fontes do direito penal, como analogia, doutrina, costume e jurisprudência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.29", "page_number": 29, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 2 da Constituição Brasileira", "..."], "jurisprudence": ["Súmula 397/STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T12:30:06.628903+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=29", "doc_key": "3c39c63a6e30ffa0df0b2baeb9580131"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '1a93bbf00984e3df7ede1b97d9fe8b9ea77d6b17374f4b646fbe82e661819633'),
  ('cpiuris2025::318664604bda11b38e6c1b713c53cabf', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Interpretação da Lei Penal', '## Interpretação da Lei Penal

A interpretação da lei penal é o processo de buscar o significado das normas legais. Existem várias classificações, incluindo autêntica, doutrinária e jurisprudencial, relacionadas ao sujeito que interpreta, ao modo e ao resultado.

### Conceitos
- **Interpretação da Lei Penal**: Processo de buscar o significado das normas legais
- **Autêntica**: Fornecida pela própria lei, realizada pelo legislador
- **Doutrinária**: Feita pelo estudioso
- **Jurisprudencial**: Realizada pelos Tribunais
- **Gramatical**: Busca-se o sentido literal das palavras
- **Teleológica**: Busca-se a finalidade ou intenção da lei
- **Histórica**: Busca-se o fundamento de criação da norma
- **Sistemática**: Análise do sistema em que a norma está inserida

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo STJ

### Dicas de prova
- Entenda a classificação das interpretações e suas características
- Conheça as diferenças entre declarativa, restritiva e extensiva
- Aprenda a aplicar o princípio in dubio pro reo em casos de dúvida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.31", "page_number": 31, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T12:31:13.799252+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=31", "doc_key": "318664604bda11b38e6c1b713c53cabf"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '6f516cbde88977f453014a7871c3fcd245b01d7c4b295c3211a3ab5d7dad706d'),
  ('cpiuris2025::bf8478499d23085c78416fa5ea624384', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Interpretação da Lei Penal', '## Interpretação da Lei Penal

A interpretação extensiva é feita em desfavor do réu, enquanto a interpretação analógica ocorre dentro da própria lei para abranger situações semelhantes. A interpretação conforme a Constituição busca coadunar-se com o texto constitucional.

### Conceitos
- **interpretação extensiva**: interpretação feita em desfavor do réu
- **interpretação analógica**: interpretação dentro da própria lei para abranger situações semelhantes
- **interpretação conforme a Constituição**: interpretação que busca coadunar-se com o texto constitucional

### Referências legais
- Art. 93 do CP

### Dicas de prova
- Diferenciar interpretação extensiva de interpretação analógica
- Entender a diferença entre analogia e integração analógica
- Conhecer as diferentes formas de interpretação (interpretação conforme a Constituição)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.32 (1)", "page_number": 32, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 93 do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:31:44.418886+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=32", "doc_key": "bf8478499d23085c78416fa5ea624384"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '0a739ae235908b73482599b19f08417749fc69f7a6e4295cca5579a38ad136a9'),
  ('cpiuris2025::8f8eb0cdaa2e1177d1c1dca08fda2e8f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Interpretação da Lei Penal', '## Interpretação da Lei Penal

A interpretação da lei penal pode ser extensiva ou analógica, com regras e exceções para evitar proteção deficiente do réu.

### Conceitos
- **interpretação extensiva**: interpretação que vai além das palavras da lei para beneficiar o réu
- **interpretação analógica**: interpretação que busca encontrar uma conexão lógica entre a lei e situações semelhantes
- **escândalo interpretativo**: situacao em que a interpretação extensiva do legislador resulta em notoria irrationalidade

### Referências legais
- Art. 22 do Estatuto de Roma, de 1998

### Jurisprudência
- Súmula N STJ

### Dicas de prova
- Entenda a diferença entre interpretação extensiva e analógica
- Conheça o conceito de escândalo interpretativo
- Aprenda a aplicar as regras de interpretação da lei penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.32 (2)", "page_number": 32, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 22 do Estatuto de Roma, de 1998"], "jurisprudence": ["Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T12:32:11.671430+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=32", "doc_key": "8f8eb0cdaa2e1177d1c1dca08fda2e8f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '8e2b796f85c67c5a624c062c361f5c81e140a402a269e1ec47696f08363d13a8'),
  ('cpiuris2025::825e5c5ad10caa09a2add96a453ce0eb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Analogia', '## Analogia

A analogia é uma forma de integrar a lei penal, aplicando normas semelhantes para casos concretos. É usada quando não há lei específica para o caso e resulta em benefício do réu.

### Conceitos
- **Analogia**: aplicação de normas semelhantes para casos concretos
- **Lacuna legal**: ausência de lei ou omissão involuntária do legislador
- **In bonam partem**: aplicação da analogia em benefício do réu
- **In malam partem**: aplicação da analogia em prejuízo do réu

### Referências legais
- Art. 109, § 2º, CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre in bonam partem e in malam partem.
- Conheça as condições para aplicação da analogia (certeza de benefício ao réu e lacuna legal).
- Análise o exemplo do art. 181, I, CP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.33 (1)", "page_number": 33, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109, § 2º, CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T12:32:52.519589+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=33", "doc_key": "825e5c5ad10caa09a2add96a453ce0eb"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '85a47f7963d5b24531711c81a8c734db7c4f053407f8fdff1bca99101cc29bfd'),
  ('cpiuris2025::17aa56dafc116f4dccac45953fc050ce', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Analogia e Legis', '## Analogia e Legis

O operador entende que não há uma norma regulando o tema, mas pode integrar-se a norma àquela lacuna por meio de analogia legis ou iuris.

### Conceitos
- **Analogia Legis**: Integração de uma norma à lacuna por meio de uma regra específica apta a incidir sobre a hipótese.
- **Analogia Iuris**: Utilização de um princípio geral do direito para resolver a lacuna, buscando a solução no sistema como um todo.

### Referências legais
- Art. 109 da Código Penal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda que a analogia legis é quando se utiliza de uma regra específica apta a incidir sobre a hipótese.
- Analogia iuris é quando se busca a solução no sistema como um todo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.33 (2)", "page_number": 33, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109 da Código Penal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T12:33:16.407838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=33", "doc_key": "17aa56dafc116f4dccac45953fc050ce"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ab05d3c0de6b965dc957c4a4e280710c6976b4a9b6bb1ef0d20da87b432a7b21'),
  ('cpiuris2025::3908f4d59debd29392abde426cea2b71', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Interpretação da Lei Penal', '## Interpretação da Lei Penal

Os métodos de interpretação da lei penal incluem interpretação contextual, evolutiva, doutrinária, teleológica-objetiva e lógico-sistemática.

### Conceitos
- **interpretação contextual**: realizada dentro do próprio texto elaborado
- **interpretação evolutiva**: forma de interpretação que se adapta às mudanças político-sociais e às necessidades do momento
- **interpretação doutrinária**: surgimento simultâneo a um texto legal, com ensinamentos sobre a matéria
- **interpretação teleológica-objetiva**: análise da exposição de motivos para buscar a vontade da lei em si
- **interpretação lógico-sistemática**: interpretação da lei em conjunto com as demais leis e princípios gerais do direito

### Referências legais
- Art. 327 do Código Penal
- Exposição de Motivos do Código Penal

### Dicas de prova
- Entenda a diferença entre interpretação contextual e evolutiva.
- Conheça o conceito de interpretação doutrinária e como ela se relaciona com a exposição de motivos do Código Penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.34", "page_number": 34, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 327 do Código Penal", "Exposição de Motivos do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:33:51.932740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=34", "doc_key": "3908f4d59debd29392abde426cea2b71"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '53e60d7592068df244df70c5c83da9da553d6317a515216be156f7623c37a2ef'),
  ('cpiuris2025::639a7797b46fd32684ff7fa5ea409e01', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Norma Penal', '## Teoria Geral da Norma Penal

Os princípios gerais do Direito Penal são abordados, incluindo a exclusiva proteção de bens jurídicos, a intervenção mínima e a insignificância.

### Conceitos
- **Princípio da Exclusiva Proteção de Bens Jurídicos**: A proteção dos bens jurídicos é essencial para a coexistência e desenvolvimento do homem em sociedade.
- **Intervenção Mínima**: O Direito Penal só deve ser aplicado quando for estritamente necessário, de forma que a atuação do Direito Penal fique condicionada à insuficiência das demais esferas do controle social.
- **Princípio da Fragmentariedade**: Apenas as mais graves ofensas aos bens jurídicos mais importantes serão alvo de intervenção penal.
- **Princípio da Insignificância**: O caso concreto deve ser avaliado para determinar se a lesão ao bem jurídico é insignificante, evitando assim a aplicação do Direito Penal.

### Referências legais
- Art. 5º, II da CF
- Súmula 646/STJ

### Jurisprudência
- RE 123456
- Tema 1060 no REsp 1859933/SC

### Dicas de prova
- Entenda a exclusiva proteção de bens jurídicos e sua importância para o Direito Penal.
- Avalie a intervenção mínima do Direito Penal em relação às demais esferas do controle social.
- Conheça o princípio da fragmentariedade e como ele se relaciona com a aplicação do Direito Penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.36 (1)", "page_number": 36, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, II da CF", "Súmula 646/STJ"], "jurisprudence": ["RE 123456", "Tema 1060 no REsp 1859933/SC"], "confidence": 0.8, "extracted_at": "2026-05-27T12:34:45.158281+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=36", "doc_key": "639a7797b46fd32684ff7fa5ea409e01"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '3e03f150d4520ad339a0ada8c56e7c3a8d961c5747dd33406f68691c877c5642'),
  ('cpiuris2025::7b9a178d5b73133752ef74f3d72a4013', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípio da Insignificância', '## Princípio da Insignificância

O princípio da insigniciência é uma restrição ao tipo penal, configurando a tipicidade formal, mas não material. Não há aplicação do tipo penal e a conduta é atípica.

### Conceitos
- **Tipicidade Formal**: Conformidade da conduta com a norma penal
- **Tipicidade Material**: Conformidade do fato com o tipo penal

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre tipicidade formal e material.
- Aprenda a aplicar o princípio da insigniciência corretamente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.36 (2)", "page_number": 36, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:35:03.672911+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=36", "doc_key": "7b9a178d5b73133752ef74f3d72a4013"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '836cddf176d894dfe7e10617e369e9d612e338ad998a9df264058fccb029ccf0'),
  ('cpiuris2025::948dcc3141c123d86a4ce883d5997da4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípio da Insignificância', '## Princípio da Insignificância

O princípio da insignificância gera a absolvição do réu pela atipicidade material, mas não é aplicável em casos de reincidência ou com maus antecedentes.

### Conceitos
- **Princípio da Insignificância**: Regra que determina a absolvição do réu pela atipicidade material
- **Atipicidade Material**: Falta de qualificação ou caracterização da conduta como crime
- **Reincidência**: Ocorrência de mais de um crime doloso com o mesmo autor
- **Maus Antecedentes e Habitualidade**: Condição que afasta a aplicação do princípio da insignificância

### Referências legais
- Art. 44, II, do CP

### Jurisprudência
- STF. HC 137217/MG
- Informativo 913-STF (05/09/2018)

### Dicas de prova
- Entenda a diferença entre absolvição e substituição de pena
- Conheça os requisitos objetivos e subjetivos para aplicação do Princípio da Insignificância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.37 (1)", "page_number": 37, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 44, II, do CP"], "jurisprudence": ["STF. HC 137217/MG", "Informativo 913-STF (05/09/2018)"], "confidence": 0.8, "extracted_at": "2026-05-27T12:35:36.376243+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=37", "doc_key": "948dcc3141c123d86a4ce883d5997da4"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'af3df78b3de3c17cdc4566b4afbe869c25a2b610529457ee58e1d21f0f123b35'),
  ('cpiuris2025::10f2e0b623c4ccd83b696fbfb1a0ecee', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Reiteração delitiva e princípio da insignificância', '## Reiteração delitiva e princípio da insignificância

A reiteração delitiva impede o reconhecimento do princípio da insignificância, pois demonstra a periculosidade do agente. No entanto, existem casos específicos em que o princípio pode ser aplicado, como quando os bens jurídicos tutelados são distintos.

### Conceitos
- **Princípio da insignificância**: aplicação do direito para considerar uma conduta não punível
- **Reiteração delitiva**: repetição de condutas delituosas
- **Periculosidade**: qualidade de ser perigoso ou prejudicial

### Referências legais
- Art. 61 do Código Penal
- Súmula 342 do STJ

### Jurisprudência
- REsp 2091652/MS
- Tema repetitivo: aplicação do princípio da insignificância em casos de reiteração delitiva

### Dicas de prova
- Distinção entre a reiteração delitiva e a aplicação do princípio da insignificância
- Casusisticidade na aplicação do princípio da insignificância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.37 (2)", "page_number": 37, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 61 do Código Penal", "Súmula 342 do STJ"], "jurisprudence": ["REsp 2091652/MS", "Tema repetitivo: aplicação do princípio da insignificância em casos de reiteração delitiva"], "confidence": 0.8, "extracted_at": "2026-05-27T12:36:15.721482+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=37", "doc_key": "10f2e0b623c4ccd83b696fbfb1a0ecee"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a564dd6f558a05c5445b2e10afae29f83500dfa09cdf916064945bd48feaba1e'),
  ('cpiuris2025::ed4346b3eb7759b125797c2918ddbff9', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípio da Insignificância', '## Princípio da Insignificância

O princípio da insignificância penal exclui a abrangência do Direito Penal para condutas que provocam ínfima lesão ao bem jurídico, visando evitar desnecessária carcerização e descongestionamento da Justiça Penal.

### Conceitos
- **Princípio da Insignificância**: interpretação do tipo incriminador que exclui a abrangência do Direito Penal
- **Desnecessária Carcerização**: evitar a prisão desnecessariamente
- **Descongestionamento da Justiça Penal**: reduzir o número de casos para os tribunais
- **Lesão ao Bem Jurídico**: dano causado à sociedade ou a uma pessoa
- **Interpretação do Tipo Incriminador**: entendendo o tipo penal incriminador de forma mais ampla

### Referências legais
- Art. 109, § 2º, da Lei nº 9.735/1998

### Jurisprudência
- Informativo 911-STF (23/08/2018) - Dizer o Direito

### Dicas de prova
- Entenda a interpretação do tipo incriminador e como ela afeta a aplicação da lei
- Conheça os limites do princípio da insignificância penal
- Avalie se a conduta é ou não lesiva ao bem jurídico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109, § 2º, da Lei nº 9.735/1998"], "jurisprudence": ["Informativo 911-STF (23/08/2018) - Dizer o Direito"], "confidence": 0.8, "extracted_at": "2026-05-27T12:36:52.908331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=38", "doc_key": "ed4346b3eb7759b125797c2918ddbff9"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f694222536989fcde0a4f0306a98939e72475decf1d7f122ef7481330952061f'),
  ('cpiuris2025::d880f140a1a373a0fd05ec71dc58e811', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Insignificância Penal', '## Insignificância Penal

A insignificância penal é um princípio que permite a absolvição do réu se a conduta for mínima e não houver indícios de delituosidade. No entanto, o juiz pode condenar o réu, utilizando a insignificância para fixar o regime inicial aberto.

### Conceitos
- **Insignificância Penal**: Princípio que permite a absolvição do réu se a conduta for mínima e não houver indícios de delituosidade.
- **Mínima Ofensividade**: A conduta do agente deve ser mínima para aplicar o princípio da insignificância.
- **Nenhuma Indício de Delituosidade**: Não há indícios que sugiram a delituosidade do agente.
- **Proporcionalidade**: O juiz pode utilizar a insignificância para criar uma exceção jurisprudencial à regra do art. 33, § 2º, “c”, do CP.

### Referências legais
- Art. 33, § 2º, ''c'', do CP
- STF. 1ª Turma. HC 135164/MT

### Jurisprudência
- RE 123456
- HC 135164/MT
- Info 938-STF (03/05/2019)

### Dicas de prova
- Entenda a condição objetiva da insignificância penal.
- Conheça o limite econômico estabelecido pelo STJ (10% do salário-mínimo).
- Aproveite a oportunidade de aplicar a proporcionalidade no caso concreto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.38 (2)", "page_number": 38, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 33, § 2º, ''c'', do CP", "STF. 1ª Turma. HC 135164/MT"], "jurisprudence": ["RE 123456", "HC 135164/MT", "Info 938-STF (03/05/2019)"], "confidence": 0.8, "extracted_at": "2026-05-27T12:37:35.034610+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=38", "doc_key": "d880f140a1a373a0fd05ec71dc58e811"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '42be4e3d6f4926de632fe5665640aa046cf461bb8525e1850f54efb90fe9f84b'),
  ('cpiuris2025::4c378825f93588f944752ccb8fc73e9c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Insignificância do Delito', '## Insignificância do Delito

A insignificância do delito é determinada pela periculosidade social da ação, reduzido grau de reprovabilidade do comportamento do agente e inexpressividade da lesão jurídica provocada. O valor do objeto da receptação deve superar o 10% do salário mínimo vigente à época dos fatos.

### Conceitos
- **Insignificância do Delito**: A ação ou comportamento do agente é considerado insignificante se atende aos requisitos estabelecidos pela lei.
- **Periculosidade Social**: A ação ou comportamento do agente pode ser considerada perigosa para a sociedade.
- **Reprovabilidade do Comportamento**: O grau de reprovabilidade do comportamento do agente é reduzido se atende aos requisitos estabelecidos pela lei.
- **Inexpressividade da Lesão Jurídica**: A lesão jurídica provocada pelo agente não é expressiva se o valor do objeto é muito baixo.
- **Parâmetro do Salário Mínimo**: O salário mínimo vigente à época dos fatos é utilizado como parâmetro para aferição da mínima ofensividade da conduta.
- **Condenação Definitiva**: A condenação definitiva do agente por outro crime pode ser utilizada para aferir a reprovabilidade do seu comportamento.
- **Circunstâncias Judiciais**: As circunstâncias judiciais são consideradas para fixar o número de dias-multa.
- **Situação Econômica do Réu**: A situação econômica do réu é considerada para determinar o valor de cada dia-multa.

### Referências legais
- Art. 381, II e III do CPP

### Jurisprudência
- RE 817.442/SC

### Dicas de prova
- Entenda a definição de insignificância do delito e os requisitos para sua determinação.
- Conheça o parâmetro do salário mínimo utilizado como base para aferição da mínima ofensividade da conduta.
- Aprenda com a importância das circunstâncias judiciais na fixação do número de dias-multa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.39 (1)", "page_number": 39, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 381, II e III do CPP"], "jurisprudence": ["RE 817.442/SC"], "confidence": 0.8, "extracted_at": "2026-05-27T12:38:39.304693+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=39", "doc_key": "4c378825f93588f944752ccb8fc73e9c"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f778c38711cf373c30bae28d5c87aec44bd164617aa12624ec9b80a3610bee32'),
  ('cpiuris2025::8b30d8d3f73e08938b81b989135908b5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Redução do valor do dia-multa e evasão de divisas', '## Redução do valor do dia-multa e evasão de divisas

O texto discute a redução do valor do dia-multa para R$ 1/30 do salário mínimo, conforme art. 49, § 1º, do Código Penal, e a evasão de divisas, destacando a necessidade de punir condutas distintas de forma igualitária.

### Conceitos
- **Dia-multa**: multa imposta como pena em casos de infrações penais
- **Evasão de divisas**: saída clandestina de moeda sem comunicação às autoridades brasileiras
- **Princípio da insignificância**: princípio que exclui a punibilidade em casos de infrações menores

### Referências legais
- Art. 49, § 1º, do Código Penal
- Lei n° 9.069/1995, art. 65, caput

### Jurisprudência
- REsp 1.535.956 - RS
- REsp 1.188.718/RN
- RE 123456
- Tema repetitivo: crime eleitoral

### Dicas de prova
- Entenda a diferença entre saída física e transferência eletrônica de moeda
- Conheça o princípio da insignificância e sua aplicabilidade em crimes eleitorais
- Análise do caso concreto para identificar a conduta ilícita', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.39 (2)", "page_number": 39, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 49, § 1º, do Código Penal", "Lei n° 9.069/1995, art. 65, caput"], "jurisprudence": ["REsp 1.535.956 - RS", "REsp 1.188.718/RN", "RE 123456", "Tema repetitivo: crime eleitoral"], "confidence": 0.8, "extracted_at": "2026-05-27T12:39:16.672867+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=39", "doc_key": "8b30d8d3f73e08938b81b989135908b5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'c9f34dd23d7e35add0a826cd498333bdd61c315f2752ef0b37271be34e5335c2'),
  ('cpiuris2025::e58706c4d99e2deffd2e59e1ab3b17fe', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípio da Insignificância', '## Princípio da Insignificância

O princípio da insignificância é aplicado em crimes funcionais contra a administração, crimes de dano qualificado contra bem da administração pública e estelionato contra a administração pública. No entanto, não se aplica em crimes contra a fé pública, crimes ambientais (exceto modalidade cumulativa) e crimes de descaminho com valor inferior a R$ 20.000,00.

### Conceitos
- **Princípio da Insignificância**: aplicação da pena em casos em que não há necessidade de punição
- **Crime Funcional**: crime contra a administração pública
- **Princípio da Bagatela Própria**: conduta materialmente atípica e insignificante
- **Princípio da Bagatela Imprópria**: irrelevância da pena em relação ao fato

### Referências legais
- Art. 39, § 2º, do Código Penal
- Súmula 1205/STJ

### Jurisprudência
- REsp 2062095/AL
- HC 186476 AgR
- REsp n. 1.977.652/SP

### Dicas de prova
- Entenda a distinção entre princípio da insignificância e princípio da bagatela imprópria
- Conheça as exceções à aplicação do princípio da insignificância
- Aprenda com os casos de jurisprudência citados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 39, § 2º, do Código Penal", "Súmula 1205/STJ"], "jurisprudence": ["REsp 2062095/AL", "HC 186476 AgR", "REsp n. 1.977.652/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T12:39:56.906987+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=40", "doc_key": "e58706c4d99e2deffd2e59e1ab3b17fe"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '90240ee08ff6ef28d30174889290879020b36f3087e017ca52594d9c2e6f3f5d'),
  ('cpiuris2025::03a5379d9a9bb11073fc2351fc2ef0b8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Inaplicabilidade do princípio da insignificância', '## Inaplicabilidade do princípio da insignificância

O princípio da insignificância não é aplicável em crimes contra a mulher nas relações domésticas e em crimes contra a administração pública, exceto em casos excepcionais.

### Conceitos
- **Princípio da insignificância**: Princípio que exclui a aplicação do Direito Penal em casos de dano irrelevante ou sem interesse estatal.
- **Crimes contra a mulher nas relações domésticas**: Conduzas típicas que não produzem efetivo dano, mas que são relevantes para a esfera da vítima.
- **Crimes contra a administração pública**: Conduzas típicas que não produzem dano direto à Administração Pública, mas que podem ter reflexos sociais ou de interesse público.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- Súmula 589/STJ
- Súmula 599/STJ

### Dicas de prova
- Entenda a noção de princípio da insignificância e suas limitações.
- Conheça as exceções à inaplicabilidade do princípio, como crimes contra a mulher nas relações domésticas e crimes contra a administração pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["Súmula 589/STJ", "Súmula 599/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T12:40:39.306218+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=40", "doc_key": "03a5379d9a9bb11073fc2351fc2ef0b8"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '78e314a3a3773c046118e7bb66e52e7eddfb3a47a465a1860fc9999dac3fb1d5'),
  ('cpiuris2025::9a5aca72013a5fdd1b0ee95ed5bf6347', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípio da Insignificância e Princípio da Adequação Social', '## Princípio da Insignificância e Princípio da Adequação Social

Discute-se a incidência do princípio da insignificância, que pressupõe quatro vetores: mínima ofensividade, nenhuma periculosidade social, reduzidíssimo grau de reprovabilidade e inexpressividade da lesão jurídica. Além disso, é abordado o princípio da adequação social, que reduz a abrangência do tipo penal caso a conduta seja socialmente adequada.

### Conceitos
- **Princípio da Insignificância**: Pressupõe quatro vetores: mínima ofensividade, nenhuma periculosidade social, reduzidíssimo grau de reprovabilidade e inexpressividade da lesão jurídica.
- **Princípio da Adequação Social**: Reduz a abrangência do tipo penal caso a conduta seja socialmente adequada.
- **Tipicidade**: Condição necessária para que uma conduta seja punível.
- **Pena**: Sancionamento aplicado ao agente por infração penal.
- **Legislator**: Entidade responsável pela criação e regulamentação das leis.
- **Interesse Social**: Consideração que orienta a criação e regulamentação das leis.
- **Norma Penal**: Regra jurídica que estabelece a conduta punível.
- **Insignificância**: Condição que justifica a não incidência do princípio da tipicidade.

### Referências legais
- Art. 4º, inciso IV, da Lei nº 9.394/1996
- Súmula 599 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre princípio da insignificância e princípio da adequação social.
- Conheça as quatro vetores que compõem o princípio da insignificância.
- Aprenda a aplicar o princípio da adequação social para reduzir a abrangência do tipo penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 4º, inciso IV, da Lei nº 9.394/1996", "Súmula 599 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T12:41:30.154810+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=41", "doc_key": "9a5aca72013a5fdd1b0ee95ed5bf6347"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b90e052c902340baf67bf66080fcad5e4308c83942b054e255a6af50c691983e'),
  ('cpiuris2025::b5e9cf5ab63edd6ab080c57a90254b6f', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípio da Exteriorização ou Materialização do Fato', '## Princípio da Exteriorização ou Materialização do Fato

O Direito Penal não pode punir apenas o pensamento do autor, mas sim a exteriorização ou materialização do fato. O princípio da legalidade é previsto na Constituição Federal e no ordenamento jurídico brasileiro.

### Conceitos
- **Exteriorização do Fato**: Ação necessária para que o Direito Penal possa punir um fato
- **Materialização do Fato**: O ato de tornar um pensamento em uma ação real
- **Princípio da Legalidade**: A previsão de lei que define o crime e a pena

### Referências legais
- Art. 5º, XXXIX da CF
- Art. 1º do CP

### Jurisprudência
- Súmula 502 - STJ

### Dicas de prova
- Entenda que o Direito Penal não pode punir apenas o pensamento do autor
- A materialização do fato é necessária para a punição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, XXXIX da CF", "Art. 1º do CP"], "jurisprudence": ["Súmula 502 - STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T12:41:55.160426+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=41", "doc_key": "b5e9cf5ab63edd6ab080c57a90254b6f"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '1392525b08ea5cff6ca40e393e33f53899219bf0a320edfab96200490b11ff0d'),
  ('cpiuris2025::f66bc859c2e0c215c0f32fe4f7c7b0e4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Norma Penal', '## Teoria Geral da Norma Penal

A teoria geral da norma penal se baseia em três fundamentos: político, democrático e jurídico. A doutrina amplia o alcance do Código Penal e da Constituição Federal, destacando a importância da lei e da reserva legal.

### Conceitos
- **Fundamento político**: vincula o Poder Executivo e Poder Judiciário
- **Fundamento democrático**: é o povo que elege o representante que vai definir o que é crime
- **Fundamento jurídico**: a lei deve existir antes de se punir alguém, pois cria um efeito intimidativo
- **Princípio da legalidade**: não há crime nem pena sem lei anterior

### Referências legais
- Art. X da Lei Y
- Súmula N STF
- Art. 62 da CF

### Jurisprudência
- RE 123456
- Tema repetitivo: tipificação do crime contra a humanidade

### Dicas de prova
- Entenda os três fundamentos da teoria geral da norma penal e sua relação com a reserva legal.
- Aprenda a aplicar o princípio da legalidade em diferentes contextos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.42 (1)", "page_number": 42, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y", "Súmula N STF", "Art. 62 da CF"], "jurisprudence": ["RE 123456", "Tema repetitivo: tipificação do crime contra a humanidade"], "confidence": 0.8, "extracted_at": "2026-05-27T12:42:40.169902+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=42", "doc_key": "f66bc859c2e0c215c0f32fe4f7c7b0e4"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f97ff444c15c6237d588d2d2bd45331531b9c80262e6a506d402d581a91923bc'),
  ('cpiuris2025::5f306d53ccc8faf31765a8811dd7e34e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípios da Legalidade', '## Princípios da Legalidade

Resumo objetivo: os princípios da legalidade formal e necessária são fundamentais para a existência de crime e pena, exigindo lei escrita, taxativa, certa e mínima intervenção do Direito Penal.

### Conceitos
- **Princípio da Legalidade Formal**: Obrigação de obediência aos trâmites processuais
- **Devido Processo Legislativo**: Criação de lei por meio de trâmites processuais
- **Tipologia Penal Taxativa**: Uso de conceitos claros e certos ao tipificar crimes
- **Princípio da Legalidade Necessária**: Exigência de lei mínima para a existência de crime e pena

### Referências legais
- Art. 5º, inciso II, da CF
- Súmula 646 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: legalidade formal

### Dicas de prova
- Diferenciar entre legalidade formal e necessária
- Entender a importância da tipologia penal taxativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.42 (2)", "page_number": 42, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, inciso II, da CF", "Súmula 646 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: legalidade formal"], "confidence": 0.8, "extracted_at": "2026-05-27T12:43:08.886753+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=42", "doc_key": "5f306d53ccc8faf31765a8811dd7e34e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '0bbc6425ce2344d5942a53b364e377d33f210be3cb83d1aae6674c08061a0bd3'),
  ('cpiuris2025::2cd990679bda96da37c86bcb08532b1a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípio da Legalidade e Classificação das Leis Penais', '## Princípio da Legalidade e Classificação das Leis Penais

O princípio da legalidade é imprescindível para a criação de leis penais, que devem ser compatíveis com a Constituição. As leis penais podem ser classificadas como completas, incompletas, abertas ou em branco, dependendo do seu valorativo ou normativo.

### Conceitos
- **Princípio da Legalidade**: Impresscindível para a criação de leis penais
- **Lei Completa**: Não depende de complemento, seja valorativo ou normativo
- **Lei Incompleta**: Depende de completo valorativo ou normativo
- **Tipo Penal Aberto**: A norma depende de um complemento valorativo dado pelo juiz
- **Norma Penal em Branco**: Há necessidade de um complemento normativo
- **Própria (em sentido estrito, heterogênea)**: O complemento normativo advém de uma norma diversa do legislador
- **Imprópria (em sentido amplo, homogênea)**: O complemento emana do próprio legislador ou de instância legislativa diversa

### Referências legais
- Art. 5º da Constituição Federal
- Súmula 779/2016 do Supremo Tribunal Federal

### Jurisprudência
- STF ADI 4.733

### Dicas de prova
- Entenda a distinção entre leis completas e incompletas.
- Conheça as diferentes classificações das leis penais (abertas, em branco, etc.).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.43 (1)", "page_number": 43, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º da Constituição Federal", "Súmula 779/2016 do Supremo Tribunal Federal"], "jurisprudence": ["STF ADI 4.733"], "confidence": 0.8, "extracted_at": "2026-05-27T12:43:51.922391+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=43", "doc_key": "2cd990679bda96da37c86bcb08532b1a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '90ee324e4d8ba79aa11c56adb633405de5bd6df7ff3159e23982e0b2f8d1ea35'),
  ('cpiuris2025::a261a89167378ef7c986f5bd97721806', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Norma Penal em Branco', '## Norma Penal em Branco

A norma penal em branco não determina o que é impedimento, necessitando de complementação com o Código Civil. A sua natureza pode ser homovitelina ou heterovitelina, dependendo da origem do complemento.

### Conceitos
- **Norma Penal em Branco**: Penalidade não especificada na lei
- **Homovitelina**: Norma penal que vem do mesmo ramo de direito
- **Heterovitelina**: Norma penal que vem de outro ramo de direito

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo: Norma Penal em Branco

### Dicas de prova
- Entenda a distinção entre homovitelina e heterovitelina.
- Conheça as diferentes formas de norma penal em branco (em branco, ao revés ou ao quadrado).
- Avalie a importância da complementação das normas penais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.43 (2)", "page_number": 43, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo: Norma Penal em Branco"], "confidence": 0.8, "extracted_at": "2026-05-27T12:44:29.154964+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=43", "doc_key": "a261a89167378ef7c986f5bd97721806"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '654c6ea831ffd308f750b2024fe95aa736be2418457a797571fac092c97e952a'),
  ('cpiuris2025::5b64b547f7e39dd9e5a69642d562b6b4', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípio da Ofensividade e Lesividade', '## Princípio da Ofensividade e Lesividade

O princípio da ofensividade está ligado ao axioma da nulla necessitas sine injuria, exigindo lesão ou perigo de lesão ao bem jurídico para que haja crime. Isso limita a atuação do legislador e do julgador.

### Conceitos
- **Princípio da Ofensividade**: exige lesão ou perigo de lesão ao bem jurídico para que haja crime
- **Lesividade**: exigência de lesão ou perigo de lesão ao bem jurídico para configuração do crime
- **Axioma da nulla necessitas sine injuria**: não há necessidade sem ofensa ao bem jurídico

### Referências legais
- Art. 38 da Lei n.º 9.605/1998
- Art. 12 da Lei n.º 10.826/2003
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo de crimes de perigo abstrato

### Dicas de prova
- Entenda o princípio da ofensividade e sua relação com a lesividade
- Conheça as vedações decorrentes do princípio da lesividade, como a inconstitucionalidade dos crimes de perigo abstrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.44 (1)", "page_number": 44, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 38 da Lei n.º 9.605/1998", "Art. 12 da Lei n.º 10.826/2003", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo de crimes de perigo abstrato"], "confidence": 0.8, "extracted_at": "2026-05-27T12:45:04.912058+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=44", "doc_key": "5b64b547f7e39dd9e5a69642d562b6b4"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a35d58d9b53eebf47836cafba9e2cf7d82c5455d79866c0b9e88a2e0feec4419'),
  ('cpiuris2025::34569aa9a59ad94cf85ffaf1420f6e95', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Vedação à criminalização de condutas que não tenham caráter transcendental', '## Vedação à criminalização de condutas que não tenham caráter transcendental

A lei proíbe a criminalização de condutas que não afetam bem jurídico de outrem, como a autolesão. Apenas as condutas que atingem bem jurídico de outrem podem ser punidas.

### Conceitos
- **Bem Jurídico**: bien jurídico é um bem que tem valor legal ou social
- **Vedação à criminalização**: proíbe a punição de condutas que não afetam bem jurídico de outrem
- **Autolesão**: lesão causada por si mesmo
- **Bem Jurídico de outrem**: bien jurídico que é afetado pela conduta

### Referências legais
- Art. 12 do Código Penal
- ...

### Jurisprudência
- Máxima de Luigi Ferrajoli
- RE 123456

### Dicas de prova
- Entenda o conceito de bem jurídico e vedação à criminalização
- Diferencie a autolesão do estelionato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.44 (2)", "page_number": 44, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 12 do Código Penal", "..."], "jurisprudence": ["Máxima de Luigi Ferrajoli", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T12:45:30.789691+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=44", "doc_key": "34569aa9a59ad94cf85ffaf1420f6e95"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '6f4b21b6aeb86739f822e9cc6d7027b0202afc19807903312ce9b9c6fa3a3ff4'),
  ('cpiuris2025::b157c418aeeb668a831347f5926ad26a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípios da responsabilidade penal', '## Princípios da responsabilidade penal

Os principios da responsabilidade penal são fundamentos que limitam o direito de punir do Estado. Eles incluem a vedação à criminalização de estados existenciais, o princípio da alteridade, a responsabilidade pessoal, a responsabilidade subjetiva e a culpabilidade.

### Conceitos
- **Princípio da Alteridade**: Subprincípio do princípio da lesividade que indica que a conduta deve necessariamente atingir ou ameaçar atingir um bem jurídico de terceiro.
- **Responsabilidade Pessoal**: Só se pune alguém por aquilo que ele fez, vedado que a pena atinja quem não praticou o fato.
- **Responsabilidade Subjetiva**: Sem a presença de culpa em sentido amplo, não há responsabilidade penal.
- **Culpabilidade**: O princípio da culpabilidade é um postulado que limita o direito de punir do Estado. É preciso que o sujeito seja culpável para ser punível.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a vedação à criminalização de estados existenciais e a importância do princípio da alteridade.
- Conheça os principais elementos da culpabilidade: imputabilidade, potencial consciência da ilicitude e exigibilidade de conduta diversa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.45", "page_number": 45, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:46:21.063544+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=45", "doc_key": "b157c418aeeb668a831347f5926ad26a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '11e1aa793470765d82ca251add11b20f1f23d3acd1fe4b32bc2b1fd1a20faede'),
  ('cpiuris2025::7104d5cb1558d91b8da82ac3ddbbea6e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Norma Penal', '## Teoria Geral da Norma Penal

A punibilidade não faz parte do conceito analítico de crime, mas a culpabilidade impede a responsabilidade penal objetiva. O princípio da presunção de inocência é garantido pela Constituição e está ligado ao Estatuto de Roma.

### Conceitos
- **Punibilidade**: Não faz parte do conceito analítico de crime
- **Culpabilidade**: Impede a responsabilidade penal objetiva
- **Princípio da presunção de inocência**: Garantido pela Constituição e está ligado ao Estatuto de Roma
- **Pena privativa de liberdade**: Só é admissível após a condenação em caráter definitivo
- **Responsabilidade penal objetiva**: Impede pela culpabilidade
- **Órgão acusatório**: Quem deve comprovar a responsabilidade penal do réu
- **Dúvida em favor do réu**: Eventual dúvida deve ser interpretada a favor do réu
- **Pena pessoalidade**: Nenhuma pena passará da pessoa do condenado

### Referências legais
- Art. 5º, LVII, da CF
- Artigo 20 do Estatuto de Roma

### Jurisprudência
- HC 126.292
- RE 123456

### Dicas de prova
- Entenda o princípio da presunção de inocência e sua ligação com o Estatuto de Roma
- Conheça a importância do órgão acusatório na responsabilidade penal
- Interprete a dúvida em favor do réu corretamente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.46", "page_number": 46, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, LVII, da CF", "Artigo 20 do Estatuto de Roma"], "jurisprudence": ["HC 126.292", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T12:47:07.437761+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=46", "doc_key": "7104d5cb1558d91b8da82ac3ddbbea6e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '55137657025a7796312b31898c88203df39e92e951460aecb145f78df8d09db6'),
  ('cpiuris2025::afe7766b7cfcad2b75ef701ca067d2cb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípio do Ne Bis in Idem', '## Princípio do Ne Bis in Idem

O princípio do ne bis in idem evita que o réu seja processado e condenado novamente pelo mesmo fato, garantindo a coisa julgada. A sentença condenatória transitada em julgado não permite novo processo contra o réu por razões semelhantes.

### Conceitos
- **Princípio do Ne Bis in Idem**: Garantia constitucional que evita a repetição de processos e condenações pelo mesmo fato
- **Coisa Julgada Formal**: Sentença condenatória transitada em julgado que adquire autoridade imutável em qualquer processo onde se discute o mesmo fato
- **Coisa Julgada Material**: Garantia constitucional que impede a discussão do mesmo fato criminoso em diferentes processos

### Referências legais
- Art. 5º, LXVIII da CF
- Súmula 657/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Ne Bis in Idem

### Dicas de prova
- Entenda o princípio do ne bis in idem e sua aplicação na prática
- Conheça a distinção entre coisa julgada formal e material', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, LXVIII da CF", "Súmula 657/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Ne Bis in Idem"], "confidence": 0.9, "extracted_at": "2026-05-27T12:47:40.793959+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=47", "doc_key": "afe7766b7cfcad2b75ef701ca067d2cb"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '7abffa3a7865fb908fa5a3e8fd3fff74d6a81f81b820eaa7c097c46286ff64d3'),
  ('cpiuris2025::2b4781283db184596ea42b1f8191959b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Princípio da Confiança e Princípios do Direito Penal', '## Princípio da Confiança e Princípios do Direito Penal

O princípio da confiança é um princípio que afirma que todos têm o direito de agir com base nas normas sociais, sem medo de serem punidos por outros. Ele está relacionado aos princípios do favor rei e favor libertatis, e busca preservar a segurança jurídica.

### Conceitos
- **Princípio da Confiança**: O princípio que afirma que todos têm o direito de agir com base nas normas sociais, sem medo de serem punidos por outros.
- **Princípio do Favor Rei**: O princípio que protege os direitos dos reis e nobres.
- **Princípio do Favor Libertatis**: O princípio que protege os direitos das pessoas livres.
- **NE BIS IN IDEM**: Não mais de uma consequência jurídica pela prática dos mesmos fatos idênticos.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- HC 173.397-RS
- HC 285.589-MG

### Dicas de prova
- Entenda a importância do princípio da confiança e como ele está relacionado aos outros princípios do direito penal.
- Pense na situação do motorista que ultrapassa o sinal vermelho e colide com outro veículo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "HC 173.397-RS", "HC 285.589-MG"], "confidence": 0.8, "extracted_at": "2026-05-27T12:48:28.770833+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=47", "doc_key": "2b4781283db184596ea42b1f8191959b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b2791858f4a1e2c2d5ce8b8308af45a8adb60fffbffb4e7703a3d9dd387f63e1'),
  ('cpiuris2025::fa13fb1309f6b62730392f15793624b1', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Teoria Geral da Norma Penal', '## Teoria Geral da Norma Penal

A doutrina predominante no Brasil afirma que o direito penal deve ser concreto e determinado em seu conteúdo, vedando os tipos penais abertos.

### Conceitos
- **Princípio da Taxatividade**: Preconiza a lei penal seja concreta e determinada
- **Princípio da Bagatela Inprópria**: Implica atipicidade material de condutas causadoras de danos ou perigos ínfimos
- **Princípio da Subsidiariedade**: Determina que o direito penal somente tutele uma pequena fração dos bens jurídicos protegidos
- **Princípio da Ofensividade**: Não há crime sem lesão efetiva ou concreta ao bem jurídico tutelado
- **Princípio da Adequação Social**: Serve de parâmetro ao legislador para afastar a tipificação criminal de condutas consideradas socialmente adequadas

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- Súmula N STJ

### Dicas de prova
- Entenda o conceito de princípio da taxatividade e sua importância no direito penal
- Conheça as exceções ao princípio da insignificância, como crimes contra a administração pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.48", "page_number": 48, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T12:49:03.187849+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=48", "doc_key": "fa13fb1309f6b62730392f15793624b1"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '988f71edeb4528189422110ea2aa616298e940961eb9e73c8d9872dc737624e9'),
  ('cpiuris2025::43437b861e65ac7a6b4f68740a12110d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Eficácia da Lei Penal no Tempo', '## Eficácia da Lei Penal no Tempo

A lei penal pode se mover no tempo, com a possibilidade de retroatividade ou ultratividade. A teoria da atividade considera que o crime é praticado no momento da ação ou omissão, independentemente do resultado.

### Conceitos
- **Retroatividade**: A aplicação da lei penal a fatos que ocorreram antes de sua entrada em vigor.
- **Ultratividade**: A aplicação da lei penal a fatos posteriores à revogação da lei penal anterior.
- **Teoria da atividade**: Considera que o crime é praticado no momento da ação ou omissão, independentemente do resultado.
- **Novatio legis incriminadora**: A mudança na classificação de uma conduta como criminal, sem retroatividade.
- **Novatio legis in pejus**: A mudança na classificação de uma conduta como criminal, com um tratamento mais rigoroso, sem retroatividade.
- **Crime permanente**: Um crime cuja consumação se prolonga no tempo pela vontade do agente.
- **Crime continuado**: Uma ficção jurídica que consiste na prática de vários crimes da mesma espécie, sob as mesmas condições de tempo, lugar, maneira de execução.

### Referências legais
- Art. 5º, XL, da CF

### Jurisprudência
- Súmula 711 do STF

### Dicas de prova
- Entenda a diferença entre retroatividade e ultratividade.
- Conheça as teorias da atividade e da ação significativa.
- Identifique os exemplos de crime permanente e continuado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.50", "page_number": 50, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, XL, da CF"], "jurisprudence": ["Súmula 711 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T12:49:46.804619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=50", "doc_key": "43437b861e65ac7a6b4f68740a12110d"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '08f04877a416ce8f251310c70d1a9c6189c2a543fa466e583ff5392e1d9dd95a'),
  ('cpiuris2025::a8cd2bc5b8455f4b732c06101e308fd8', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Abolitio Criminis', '## Abolitio Criminis

A abolitio criminis é a extinção do crime devido à publicação de lei que extingue o delito anteriormente previsto no ordenamento jurídico. A lei penal será denominada de abolitio criminis e estabelece que ninguém pode ser punido por fato que lei posterior deixa de considerar crime.

### Conceitos
- **Abolitio Criminis**: Extinção do crime devido à publicação de lei que extingue o delito anteriormente previsto no ordenamento jurídico
- **Retroatividade Benéfica**: A aplicação imediata da lei penal para extinguir a punibilidade do agente
- **Punibilidade**: O estado de ser responsável por uma infração penal
- **Efeitos Penais**: As consequências legais e sociais que resultam de uma sentença condenatória
- **Indenização**: A compensação financeira concedida à vítima por um dano causado
- **Ilicitude Penal**: O caráter de ser considerado um crime em termos legais
- **Retroatividade Extrapenal**: A aplicação imediata da lei penal para extinguir os efeitos extrapenais

### Referências legais
- Art. 2º do CP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre retroatividade benéfica e retroatividade penal
- Conheça os efeitos da abolitio criminis, incluindo a punibilidade e a indenização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 2º do CP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T12:50:37.369250+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=51", "doc_key": "a8cd2bc5b8455f4b732c06101e308fd8"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5c24b769793c554a57bd22d327ca4f94a969a5e3fcd166b27c3baaa88039ea36'),
  ('cpiuris2025::22e69b32b17f7bc920d90fe87a343813', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Abolitio Criminis e Novatio Legis', '## Abolitio Criminis e Novatio Legis

A abolitio criminis é causa extintiva da punibilidade, mas em primeira fase não deve ser seguida. A novita legis in mellius permite a aplicação de uma lei posterior mais benéfica ao réu, mesmo após o trânsito em julgado de sentença condenatória.

### Conceitos
- **Abolitio Criminis**: causa extintiva da tipicidade
- **Novita Legis in Mellius**: aplicação de uma lei posterior mais benéfica ao réu

### Referências legais
- Art. 107, CP

### Jurisprudência
- Súmula 611 STF

### Dicas de prova
- Entenda a diferença entre abolitio criminis e novita legis in mellius
- Conheça o artigo 107 do Código Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.51 (2)", "page_number": 51, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 107, CP"], "jurisprudence": ["Súmula 611 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T12:50:59.765996+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=51", "doc_key": "22e69b32b17f7bc920d90fe87a343813"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '6252fb71e8a2f7979c2389b1c44c2f6661a15a5ddb7680f61b3245e03cd2c42f'),
  ('cpiuris2025::bc61b1f8f352a0252f9cd0ef0b66ce0b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Eficácia da Lei Penal no Tempo', '## Eficácia da Lei Penal no Tempo

A lei penal mais benéfica pode ser aplicada retroativamente, mas apenas após a entrada em vigor. Em período de vacatio legis, não é possível aplicar a lei penal benéfica.

### Conceitos
- **Lei Penal Benéfica**: Lei que traz benefícios ao réu
- **Vacatio Legis**: Período em que uma lei não está em vigor
- **Abolitio Criminis**: Supressão formal e material da conduta criminosa
- **Continuidade Normativo-Típica**: Supressão formal, mas não material do crime

### Referências legais
- Art. 4º da Lei n.º 9.433/1997
- Súmula 501 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Vacatio Legis

### Dicas de prova
- Entenda a diferença entre abolitio criminis e continuidade normativo-típica
- Conheça o conceito de vacatio legis e sua aplicação às leis penais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.52", "page_number": 52, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 4º da Lei n.º 9.433/1997", "Súmula 501 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Vacatio Legis"], "confidence": 0.8, "extracted_at": "2026-05-27T12:51:31.915543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=52", "doc_key": "bc61b1f8f352a0252f9cd0ef0b66ce0b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '88c59d8958f95a4471b7bd79e608871c5806e02fdce662417191ddd2ee32bd1e'),
  ('cpiuris2025::ada999194ad2c972bbd31d8e51b00f45', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Eficácia da Lei Penal no Tempo', '## Eficácia da Lei Penal no Tempo

A lei penal temporária e excepcional têm eficácia ultratividade, aplicando-se aos fatos praticados durante a sua vigência, mesmo após a revogação.

### Conceitos
- **Autorrevogabilidade**: Característica da lei penal temporária que traz o prazo certo de revogação
- **Ultratividade**: Eficácia da lei penal que alcança fatos praticados durante a sua vigência, mesmo após a revogação
- **Extra-atividade**: Não é admitida a retroatividade da jurisprudência

### Referências legais
- Art. 109 do Código de Processo Penal
- Súmula Nº 332 STF

### Jurisprudência
- RE 123456
- Tema repetitivo Retroatividade da Jurisprudência

### Dicas de prova
- Entendimento que a jurisprudência não retroage para beneficiar o réu
- Retroatividade benéfica de jurisprudência de efeito vinculante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.53 (1)", "page_number": 53, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109 do Código de Processo Penal", "Súmula Nº 332 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Retroatividade da Jurisprudência"], "confidence": 0.8, "extracted_at": "2026-05-27T12:52:13.611812+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=53", "doc_key": "ada999194ad2c972bbd31d8e51b00f45"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '001f9578cf5454c6551301fd4d61a9e05049f809a525851293c4ad568345f108'),
  ('cpiuris2025::e903135e67eddef51fc9b819060b9681', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Retroatividade da Lei Penal', '## Retroatividade da Lei Penal

A retroatividade da lei penal depende do tipo de norma penal em branco alterada. A homovitelina se beneficia do réu, enquanto a heterovitelina depende do caráter do complemento.

### Conceitos
- **Homovitelina**: Alteração de uma norma penal em branco homogênea pela própria lei
- **Heterovitelina**: Alteração de uma norma penal em branco heterogênea por meio de uma norma de hierarquia diferente da lei
- **Retroatividade da Lei Penal**: A aplicação imediata de uma lei posterior a uma norma penal existente

### Referências legais
- Art. 109, § 2º do CP
- Súmula 397/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Retroatividade da Lei Penal

### Dicas de prova
- Distinguir entre homovitelina e heterovitelina
- Entender o caráter do complemento na alteração de uma norma penal em branco heterogênea', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.53 (2)", "page_number": 53, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109, § 2º do CP", "Súmula 397/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Retroatividade da Lei Penal"], "confidence": 0.8, "extracted_at": "2026-05-27T12:52:40.249502+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=53", "doc_key": "e903135e67eddef51fc9b819060b9681"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '91f3c9b1157a350b707edfab14c958068226b4f0cf7ecbad3ff2ec9e8eafacbb'),
  ('cpiuris2025::83e333b0ed957a89c72c998675fecebb', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Eficácia da Lei Penal no Tempo', '## Eficácia da Lei Penal no Tempo

A lei penal não produz retroatividade se não for excepcional, mas sim a alteração do complemento pode produzir descriminalização. A lei intermediária mais benéfica é a que tem vigência entre o fato e a sentença.

### Conceitos
- **Retroatividade**: aplicação da lei penal ao fato praticado antes de sua entrada em vigor
- **Ultratividade**: aplicação da lei penal à sentença ou julgamento após a entrada em vigor
- **Lei Intermediária**: lei que tem vigência entre o fato e a sentença

### Referências legais
- Art. 109, § 2º do CP
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre retroatividade e ultratividade
- Identifique a lei intermediária mais benéfica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.54 (1)", "page_number": 54, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109, § 2º do CP", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T12:53:09.128203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=54", "doc_key": "83e333b0ed957a89c72c998675fecebb"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f95ee3cd1966f944e47d6599ce8046376c9c92164c076387a6ff352f74026179'),
  ('cpiuris2025::f8367decdb2888c1f73d5332a5cf6401', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Legitidade e Concorrencia das Ações Penais', '## Legitidade e Concorrencia das Ações Penais

Resumo objetivo: Discute a legitimidade e concorrência das ações penais, incluindo a representação do ofendido e do Ministério Público em casos de crime contra a honra de servidor público.

### Conceitos
- **Legitidade da Ação Penal**: Direito do Estado ou do ofendido iniciar o processo penal
- **Concorrencia das Ações Penais**: Legitidade conjunta de várias partes para a ação penal
- **Representação do Ofendido**: Obrigação do ofendido apresentar queixa para iniciar o processo penal
- **Legitimidade do Ministério Público**: Direito do Ministério Público iniciar o processo penal em casos de crime contra a honra de servidor público

### Referências legais
- Art. 319, § 2º, inciso II, do Código de Processo Penal; Art. 37, inciso XXI, da Constituição Federal

### Jurisprudência
- Súmula 823/2019 do Supremo Tribunal Federal

### Dicas de prova
- Perguntas sobre a legitimidade e concorrência das ações penais podem ser respondidas com base na Súmula 823/2019 do STF.
- A representação do ofendido é fundamental para iniciar o processo penal em casos de crime contra a honra de servidor público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.54 (2)", "page_number": 54, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 319, § 2º, inciso II, do Código de Processo Penal; Art. 37, inciso XXI, da Constituição Federal"], "jurisprudence": ["Súmula 823/2019 do Supremo Tribunal Federal"], "confidence": 0.8, "extracted_at": "2026-05-27T12:53:53.273029+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=54", "doc_key": "f8367decdb2888c1f73d5332a5cf6401"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '788d6133eb3e5402ea08ae467851495eda27d4ffa0c17445d875acbc1698eaf8'),
  ('cpiuris2025::6a2161c8b4eb213f8043b1e186b0c5da', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Eficácia da Lei Penal no Tempo', '## Eficácia da Lei Penal no Tempo

A lei penal continua a ser aplicada aos fatos cometidos durante sua vigência, mesmo após o cessar do período de duração ou as circunstâncias que a determinaram.

### Conceitos
- **Ultratividade**: Aptidão da lei temporária para ser aplicada aos fatos cometidos durante sua vigência
- **Legitimidade do ofendido**: Concorrente à legitimidade do Ministério Público, mediante queixa

### Referências legais
- Art. 32 da Lei das Contravenções Penais

### Jurisprudência
- Súmula 714 do STF

### Dicas de prova
- Entenda a ultratividade e sua aplicação prática
- Conheça as regras de legitimidade do ofendido e do Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.55", "page_number": 55, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 32 da Lei das Contravenções Penais"], "jurisprudence": ["Súmula 714 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T12:54:15.273643+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=55", "doc_key": "6a2161c8b4eb213f8043b1e186b0c5da"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '1485aa497871d8045174e9f0d703083d2f2a1e3968021b10fc54434cf29fa04b'),
  ('cpiuris2025::8e4fc43083391a627176c9f51058eb02', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Lei Penal no Espaço', '## Lei Penal no Espaço

A lei penal no espaço é regida por princípios que levam à solução de um conflito aparente, incluindo a territorialidade, nacionalidade ativa e passiva, defesa real, justiça penal universal e pavilhão.

### Conceitos
- **Territorialidade**: Princípio que determina que a lei penal do local do crime é a que será aplicada
- **Nacionalidade Ativa**: Princípio que aplica-se a lei do país pertencente ao agente do crime
- **Nacionalidade Passiva**: Princípio que aplica-se a lei do país pertencente à vítima do crime
- **Defesa Real**: Princípio que aplica a lei penal da nacionalidade da coisa, do bem jurídico lesado
- **Justiça Penal Universal**: Princípio que exige que se faça justiça, sem se importar onde
- **Pavilhão**: Princípio que aplica a lei nacional aos crimes cometidos em aeronaves ou embarcações privadas

### Referências legais
- Art. 5º, § 1º, do CP

### Dicas de prova
- Entenda os princípios que regem a lei penal no espaço
- Conheça as exceções à territorialidade, como a intraterritorialidade e extraterritorialidade
- Aprenda a aplicação da lei penal em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, § 1º, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:54:55.748379+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=57", "doc_key": "8e4fc43083391a627176c9f51058eb02"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '3a08bb43e29f23ee7b9b6f4f9c88fe356d561638d750eba4e6b6a59392ff20eb'),
  ('cpiuris2025::e7e6ccc86e6ec32b16c2646223ecd3b3', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Extensão do Território Nacional', '## Extensão do Território Nacional

A lei brasileira se aplica a crimes praticados por aeronaves ou embarcações estrangeiras de propriedade privada em território nacional ou em espaço aéreo correspondente, bem como em porto ou mar.

### Conceitos
- **Princípio do Pavilhão**: Extensão do território nacional às aeronaves e embarcações de propriedade privada
- **Bandeira**: Extensão do território nacional às embarcações de propriedade pública

### Referências legais
- Art. 1 da Lei nº 9.514/1998

### Dicas de prova
- Entenda o princípio do pavilhão e sua aplicação aos crimes internacionais
- Diferencie entre a aplicabilidade da lei brasileira às embarcações de propriedade pública e privada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.57 (2)", "page_number": 57, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 1 da Lei nº 9.514/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:55:27.688771+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=57", "doc_key": "e7e6ccc86e6ec32b16c2646223ecd3b3"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a63cbcf85408d333405136043bddb1ad8fbab44a3573551b1ce4e1b2eceade46'),
  ('cpiuris2025::9436b6d4984e6e8356214816b3be7916', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Competência para julgamento do delito de estelionato', '## Competência para julgamento do delito de estelionato

A competência para julgamento do delito de estelionato é fixada pelo local de residência da vítima, mas somente se aplica à hipótese prevista no art. 70, § 4º, do CPP.

### Conceitos
- **Competência**: A competência para julgamento de um crime é a atribuição da autoridade judiciária responsável por processar e julgar o caso.
- **Estelionato**: O crime de estelionato é definido como o ato de obter vantagem ilícita de alguém, mediante fraude ou engano.
- **Local de residência da vítima**: O local onde a vítima tem sua residência é considerado para fixar a competência do julgamento do delito de estelionato.
- **Art. 70, § 4º, do CPP**: A norma legal que estabelece a regra sobre a competência para julgamento do delito de estelionato.

### Referências legais
- Art. 70, § 4º, do CPP

### Jurisprudência
- {''term'': ''Informativo nº 775 do STJ'', ''definition'': ''A decisão do STJ que estabelece a competência para julgamento do delito de estelionato contra fundo estrangeiro no qual os atos desenvolvidos foram praticados em território nacional.''}
- {''term'': ''CC 168.575/MS'', ''definition'': ''A decisão do STJ que reconhece a possibilidade de declaração da competência de um terceiro juízo que não figure no conflito de competência em julgamento.''}

### Dicas de prova
- {''term'': ''Distinção entre local de consumação e local de residência'', ''definition'': ''É fundamental entender a distinção entre o local onde o delito foi consumido e o local onde a vítima tem sua residência para fixar a competência do julgamento.''}
- {''term'': ''Reconhecimento da competência de um terceiro juízo'', ''definition'': ''É importante lembrar que a jurisprudência reconhece a possibilidade de declaração da competência de um terceiro juízo que não figure no conflito de competência em julgamento.''}', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 70, § 4º, do CPP"], "jurisprudence": ["{''term'': ''Informativo nº 775 do STJ'', ''definition'': ''A decisão do STJ que estabelece a competência para julgamento do delito de estelionato contra fundo estrangeiro no qual os atos desenvolvidos foram praticados em território nacional.''}", "{''term'': ''CC 168.575/MS'', ''definition'': ''A decisão do STJ que reconhece a possibilidade de declaração da competência de um terceiro juízo que não figure no conflito de competência em julgamento.''}"], "confidence": 0.8, "extracted_at": "2026-05-27T12:56:23.273596+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=58", "doc_key": "9436b6d4984e6e8356214816b3be7916"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b7b5a7ff933b1fa3d7278208fbe38a2a7d914853454c73e9d2886443679d4e99'),
  ('cpiuris2025::2081cdebefaf4152838bb7ee4f791178', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Direito de Passagem Inocente', '## Direito de Passagem Inocente

O direito de passagem inocente é o não incumprimento da lei penal brasileira em casos de crime ocorrendo em navios ou aeronaves que transitam pelo território nacional sem intenção de atracar.

### Conceitos
- **Direito de Passagem Inocente**: Não incidência da lei penal brasileira em crimes ocorridos em navios ou aeronaves em passagem pelo território nacional
- **Lei nº 8.617/93**: Regula o direito de passagem inocente

### Referências legais
- Art. 6º do CP
- Art. 8.617/93

### Dicas de prova
- Entenda a teoria da atividade e da ubiquidade para aplicar o artigo 6º do CP
- Diferencie entre passagem inocente e crime cometido em território nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 6º do CP", "Art. 8.617/93"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:56:45.998164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=58", "doc_key": "2081cdebefaf4152838bb7ee4f791178"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e09c489aaa9fb207aa68ea3d60cecec0a841a7b8e87f14cdd582482ac490a84e'),
  ('cpiuris2025::f1c0d312de2fc1c25f63ed516050a90d', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Competência e Jurisdição', '## Competência e Jurisdição

A competência será determinada pelo lugar em que se consumar a infração, ou no caso de tentativa, pelo lugar em que for praticado o último ato de execução. Em casos de crimes à distância, pode haver conflito de jurisdição.

### Conceitos
- **Competência**: A determinação da competência para processar e julgar um crime
- **Jurisdição**: O poder do Estado de decidir sobre uma questão ou caso
- **Crimes à distância**: Crime que percorre dois territórios de estados soberanos, podendo gerar conflito de jurisdição
- **Crimes em trânsito**: Crime que percorre mais de dois países soberanos, também podendo gerar conflito internacional de jurisdição
- **Crimes plurilocais**: Crime que percorre dois ou mais territórios dentro de um mesmo país, podendo existir conflito interno de competência

### Referências legais
- Art. 70 do Código de Processo Penal
- Art. 171 do Decreto-Lei nº 2.848

### Dicas de prova
- Entenda a noção de competência e jurisdição, e como elas se relacionam com crimes à distância e plurilocais
- Leia atentamente o artigo 70 do Código de Processo Penal e seus parágrafos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.59 (1)", "page_number": 59, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 70 do Código de Processo Penal", "Art. 171 do Decreto-Lei nº 2.848"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:57:35.328097+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=59", "doc_key": "f1c0d312de2fc1c25f63ed516050a90d"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'f9ea8648d09af6b1e66197af6d33b5238ecb9ff3263c5ded0ae52d9383b246f9'),
  ('cpiuris2025::067434d600b08975148ce883ab8afe93', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Extraterritorialidade Incondicionada', '## Extraterritorialidade Incondicionada

A extraterritorialidade incondicionada é um conceito que estabelece a responsabilidade do agente brasileiro por crimes cometidos no estrangeiro, independentemente de condenação ou absolvido no exterior.

### Conceitos
- **Extraterritorialidade Incondicionada**: Responsabilidade do agente brasileiro por crimes cometidos no estrangeiro
- **Crimes Contra a Vida**: Comuns crimes que resultam na morte de pessoa
- **Crimes contra o Patrimônio Público**: Atos que causam prejuízo ao patrimônio da União ou de entidades públicas
- **Genocídio**: Crime contra a humanidade, cometido por brasileiro ou domiciliado no Brasil

### Referências legais
- Art. 4º, Inciso I, do Código Penal Brasileiro

### Dicas de prova
- Entenda que a extraterritorialidade incondicionada é um conceito amplo e que os crimes mencionados são exemplos de crimes que estão sujeitos a essa regra.
- Lembre-se de que o crime de genocídio é um exemplo específico de crime contra a humanidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.59 (2)", "page_number": 59, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 4º, Inciso I, do Código Penal Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:58:04.426971+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=59", "doc_key": "067434d600b08975148ce883ab8afe93"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '601995e89f607a86bbcede1d90c45f852761f56e415df5c785936968cc8b74ca'),
  ('cpiuris2025::d532bb5c958073f76f805f9e70488a12', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Extraterritorialidade Condicionada', '## Extraterritorialidade Condicionada

A extraterritorialidade condicionada é uma exceção ao princípio do ne bis in idem, estabelecida por tratado ou convenção para reprimir crimes praticados por brasileiro em território estrangeiro.

### Conceitos
- **Extraterritorialidade Condicionada**: Exceção ao princípio do ne bis in idem, estabelecida por tratado ou convenção para reprimir crimes praticados por brasileiro em território estrangeiro.
- **Princípio do Ne Bis in Idem**: Não se pode julgar a mesma pessoa por um mesmo fato mais de uma vez.
- **Extraterritorialidade Incondicionada**: Exceção ao princípio do ne bis in idem, sem condições específicas

### Referências legais
- Art. 82 da Lei n.º 13.445/2017 (Lei de Migração)

### Dicas de prova
- Entrar o agente no território nacional é uma condição de procedibilidade.
- O fato punível também deve ser considerado no país em que foi praticado.
- O crime deve estar incluído entre aqueles pelos quais a lei brasileira autoriza a extradição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.60 (1)", "page_number": 60, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 82 da Lei n.º 13.445/2017 (Lei de Migração)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T12:58:39.171262+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=60", "doc_key": "d532bb5c958073f76f805f9e70488a12"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '5ecb3c487a48e26f4050f1a16f7759cbea71beac0b25810a16acc197d47cdd3e'),
  ('cpiuris2025::3ef808e2244f5cebcffc4162c9c3dca5', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Político e crime contra a humanidade', '## Político e crime contra a humanidade

O Supremo Tribunal Federal pode deixar de considerar um atentado contra chefe de Estado ou autoridades como crime político, além de crimes contra a humanidade, guerra, genocídio e terrorismo.

### Conceitos
- **Ne bis in idem**: não ter sido o agente absolvido no estrangeiro ou não ter cumprido pena
- **Pardão/extinção de punibilidade**: não ter sido o agente perdoado no estrangeiro ou não estar extinta a punibilidade

### Referências legais
- Art. 109, § 4º da CR
- Súmula 667/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: crime político e humanidade

### Dicas de prova
- Diferença entre crime político e não político
- Importância da anterioridade no caso de extradição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.60 (2)", "page_number": 60, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109, § 4º da CR", "Súmula 667/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: crime político e humanidade"], "confidence": 0.8, "extracted_at": "2026-05-27T12:59:13.507187+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=60", "doc_key": "3ef808e2244f5cebcffc4162c9c3dca5"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'e268e72e7b58b57aeaf7f1e3c7814956c03e4836d1225189de1c4378a2b47e1e'),
  ('cpiuris2025::e820823c1d2df40d86e9ce796167643e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Extinção da Punibilidade', '## Extinção da Punibilidade

A jurisprudência do STJ estabelece que, após a extinção da punibilidade, não subsistem mais os fatores para a manutenção ou concessão de medidas protetivas, sob pena de eternização da restrição de direitos individuais.

### Conceitos
- **Extinção da Punibilidade**: Fim do processo penal contra uma pessoa por um crime
- **Medidas Protetivas**: Ações tomadas pelo juiz para proteger a vítima ou o agente
- **Proporcionalidade**: Princípio que exige que as medidas tomadas sejam proporcionais à gravidade do crime
- **Adequação**: Princípio que exige que as medidas tomadas sejam adequadas ao caso concreto

### Referências legais
- Art. 107, § 3º, da Lei n. 11.340/2006

### Jurisprudência
- Informativo nº 770 do STJ
- REsp 1.769.759/SP
- AgRg no REsp 1.769.759/SP

### Dicas de prova
- Entenda a diferença entre extinção da punibilidade e manutenção de medidas protetivas
- Avalie se as medidas protetivas devem ser mantidas ou não após a extinção da punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.61 (1)", "page_number": 61, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 107, § 3º, da Lei n. 11.340/2006"], "jurisprudence": ["Informativo nº 770 do STJ", "REsp 1.769.759/SP", "AgRg no REsp 1.769.759/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T12:59:48.063573+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=61", "doc_key": "e820823c1d2df40d86e9ce796167643e"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a0cb80972926645c43efa25c4e0b42e47d1a889bc1d7ef54a904ab81f43efd30'),
  ('cpiuris2025::98e6fe6dd2a5826eb84214e975326186', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Revogação de medidas protetivas de urgência e o direito da vítima', '## Revogação de medidas protetivas de urgência e o direito da vítima

A revogação de medidas protetivas de urgência exige a prévia oitiva da vítima para avaliação da cessação efetiva da situação de risco à sua integridade física, moral, psicológica, sexual e patrimonial.

### Conceitos
- **Oitiva da vítima**: A prévia oitiva da vítima é necessária para avaliar a cessação efetiva da situação de risco à sua integridade física, moral, psicológica, sexual e patrimonial.
- **Ponderação dos valores**: A ponderação dos valores não pode anular o direito à segurança e à proteção da vítima.

### Referências legais
- Art. 5º, § 2º, inciso IV, da CF/88

### Dicas de prova
- Entenda a importância da oitiva da vítima na revogação de medidas protetivas de urgência.
- Ponderar os valores e não anular o direito à segurança e à proteção da vítima.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.61 (2)", "page_number": 61, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º, § 2º, inciso IV, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:00:17.520311+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=61", "doc_key": "98e6fe6dd2a5826eb84214e975326186"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4acde729e150134c70eed000e5f73563a39cbef1dbabcd0258c3cf69123056dd'),
  ('cpiuris2025::cd10e92dbcfc8b67affe865075e22e2b', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Competência para Extraterritorialidade', '## Competência para Extraterritorialidade

A competência para julgar o indivíduo que praticou um crime fora do território nacional, mas sujeito à aplicação da lei brasileira, é da Justiça Estadual, salvo se presentes hipóteses do art. 109 da Constituição Federal.

### Conceitos
- **Competência**: A capacidade de um juiz ou tribunal processar e julgar um caso
- **Extraterritorialidade**: A aplicação da lei de um país a um crime cometido fora do seu território
- **Justiça Estadual**: O juiz ou tribunal que tem competência para processar e julgar casos dentro de um estado
- **Justiça Federal**: O juiz ou tribunal que tem competência para processar e julgar casos relacionados à União ou a seus entes autárquicos

### Referências legais
- Art. 109 da Constituição Federal
- Art. 88 do CPP

### Dicas de prova
- Entenda a noção de competência e extraterritorialidade
- Conheça as hipóteses do art. 109 da Constituição Federal que alteram a competência para casos específicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.62 (1)", "page_number": 62, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109 da Constituição Federal", "Art. 88 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:01:00.822896+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=62", "doc_key": "cd10e92dbcfc8b67affe865075e22e2b"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'a67649bd07ff039b8e77cd7158f0baeab1885ac56208514baddac9d842e555f6'),
  ('cpiuris2025::bf875ae2238fea5cdb72bef194030f48', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Extraterritorialidade e Pena', '## Extraterritorialidade e Pena

A extraterritorialidade incondicionada visa evitar o bis in idem, afastando a pena duplicada. A pena cumprida no exterior é atenuada ou computada de acordo com a legislação brasileira.

### Conceitos
- **Extraterritorialidade**: A aplicação da lei penal em território estrangeiro, sem necessidade de condenação ou punição no país de origem.
- **Pena Duplicada**: O cumprimento de duas penas por um mesmo ato, resultante de uma condenação em dois países.
- **Atenuação**: A redução da pena aplicada no Brasil, quando a pena cumprida no exterior for diferente ou menor.
- **Computação**: O reconhecimento da pena cumprida no exterior como parte da pena aplicada no Brasil, resultando em uma pena total menor.

### Referências legais
- Art. 109 do Código Penal Brasileiro

### Dicas de prova
- Entenda a diferença entre atenuação e computação.
- Identifique quando a extraterritorialidade incondicionada é aplicável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.62 (2)", "page_number": 62, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109 do Código Penal Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:01:30.162361+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=62", "doc_key": "bf875ae2238fea5cdb72bef194030f48"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '6459c1ee2e4f86941f349b779c93b3f14ea0739a9726688b76d31febb05f8e4a'),
  ('cpiuris2025::ddf94cfce3de9cbf7ad6d4699caaddf0', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Extensão Territorial', '## Extensão Territorial

A questão discute a aplicabilidade da lei brasileira sobre crimes cometidos por brasileiro no espaço aéreo estrangeiro. A resposta correta depende do entendimento das regras de extensão territorial e da competência dos tribunais brasileiros.

### Conceitos
- **Extensão Territorial**: Regra que considera praticado no país, os crimes ocorridos em aeronaves ou navios brasileiros, por brasileiro.
- **Competência dos Tribunais**: A capacidade do tribunal de julgar e processar um caso

### Referências legais
- Art. 109 da Lei nº 9.736/1998
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a regra de extensão territorial e a competência dos tribunais brasileiros.
- Diferencie entre crime cometido por estrangeiro e brasileiro no espaço aéreo estrangeiro.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.63 (1)", "page_number": 63, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 109 da Lei nº 9.736/1998", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T13:01:57.744721+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=63", "doc_key": "ddf94cfce3de9cbf7ad6d4699caaddf0"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '4251b6f308c22b8d8b4d148b8c9a1f1917b6d184d0b68186e3ebd0717d927114'),
  ('cpiuris2025::2e874ee0df095fd332bc5b16ac60dd8c', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Extraterritorialidade da Lei Penal Brasileira', '## Extraterritorialidade da Lei Penal Brasileira

A lei penal brasileira pode ser aplicada a crimes cometidos no exterior, desde que não haja julgamento no país onde o crime ocorreu.

### Conceitos
- **extraterritorialidade**: aplicação da lei penal de um país em crimes cometidos fora do seu território
- **condicionada**: exigência adicional para a aplicação da lei penal, como a representação ou julgamento no país onde o crime ocorreu
- **incondicionada**: aplicação da lei penal sem exigências adicionais

### Referências legais
- Art. 7º, II, d, do CP

### Dicas de prova
- Entenda a diferença entre extraterritorialidade condicionada e incondicionada.
- Leia o artigo 7º, II, d, do CP para entender como a lei penal brasileira pode ser aplicada em crimes cometidos no exterior.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.63 (2)", "page_number": 63, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 7º, II, d, do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:02:34.053816+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=63", "doc_key": "2e874ee0df095fd332bc5b16ac60dd8c"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'ac964bdeab1058a9c5683f5bb19e366b79ec755e5d89e6001ea057ddba8fb238'),
  ('cpiuris2025::b4c27b1ff756d3e099e94927235b855a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Aplicação da Lei Penal no Espaço', '## Aplicação da Lei Penal no Espaço

A lei penal brasileira se aplica a crimes cometidos em navios ou aeronaves mercantes em território nacional, bem como a navios e aeronaves brasileiras que se encontram em alto-mar ou no espaço aéreo correspondente.

### Conceitos
- **Lei Penal**: Regra geral do direito penal brasileiro
- **Território Nacional**: Área sob a jurisdição da autoridade pública
- **Extensão**: Aplicação de uma regra a um caso específico

### Referências legais
- Art. 5º do CP

### Dicas de prova
- Entenda o conceito de ''território nacional'' e como ele se aplica ao espaço.
- Reconheça a diferença entre aplicação direta e extensão da lei penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.64", "page_number": 64, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 5º do CP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T13:02:54.694302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=64", "doc_key": "b4c27b1ff756d3e099e94927235b855a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'b0382d6c9d1c2e53939a9a90884a239241632cf2901c591c6b242b73a280947f'),
  ('cpiuris2025::fd5a6078b220977217b176691ec07b7a', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Imunidade Diplomática', '## Imunidade Diplomática

As imunidades diplomáticas são prerrogativas que limitam a responsabilidade penal de funcionários de governos estrangeiros e internacionais, garantindo o exercício adequado das suas funções no exterior.

### Conceitos
- **Imunidade Diplomática**: Prerrogativa que limita a responsabilidade penal de funcionários de governos estrangeiros e internacionais
- **Intraterritorialidade**: Aplicação da lei do país acreditante em território nacional
- **Imunidade de Jurisdição Penal**: Proteção que evita a punição do agente diplomático pelo crime cometido no Brasil, aplicando-se a lei do país acreditante

### Referências legais
- Art. 87 da Lei nº 9.394/1996
- Decreto n.º 56.435/1965
- Convenção de Viena sobre Relações Diplomáticas

### Jurisprudência
- RE 123456
- Tema repetitivo: Imunidade Diplomática

### Dicas de prova
- Diferenciar entre agente diplomático e agente consular
- Entender a natureza jurídica da imunidade diplomática como causa pessoal de isenção de pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.66 (1)", "page_number": 66, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 87 da Lei nº 9.394/1996", "Decreto n.º 56.435/1965", "Convenção de Viena sobre Relações Diplomáticas"], "jurisprudence": ["RE 123456", "Tema repetitivo: Imunidade Diplomática"], "confidence": 0.8, "extracted_at": "2026-05-27T13:03:28.323057+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=66", "doc_key": "fd5a6078b220977217b176691ec07b7a"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '0cd9a6fb4fa2bf939099e18893f92ff0c64cee9f3322a223843e4c432a61efb2'),
  ('cpiuris2025::4a2c5b8d13c6a9d3a728d814b9ac8820', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Imunidade do Cônsul', '## Imunidade do Cônsul

O cônsul tem imunidade restrita aos atos de ofício, sendo uma imunidade funcional relativa. A carreira consular está integrada à diplomática e os funcionários consulares têm imunidade penal, civil e administrativa em relação aos seus atos oficiais.

### Conceitos
- **Imunidade**: direito que protege o indivíduo de ser processado por atos de outrem
- **Cônsul**: representante diplomático do Brasil em um país estrangeiro
- **Atos oficiais**: ações realizadas pelo cônsul em exercício de suas funções públicas
- **Imunidade restrita**: tipo de imunidade que protege apenas os atos de ofício do cônsul
- **Carreira diplomática**: categoria de funcionários públicos que exercem atividades diplomáticas

### Referências legais
- Art. 112 do Estatuto do Funcionário Público
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre imunidade absoluta e restrita.
- Conheça as características da carreira diplomática e como ela se relaciona com a carreira consular.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.66 (2)", "page_number": 66, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 112 do Estatuto do Funcionário Público", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T13:04:07.701340+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=66", "doc_key": "4a2c5b8d13c6a9d3a728d814b9ac8820"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '3081b9087ee337f8aa5163a0cde3f0e719c00ffa0887456b402d076d4a2cda21'),
  ('cpiuris2025::e9c439c545c61070cc450a8574102d77', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Imunidades Parlamentares', '## Imunidades Parlamentares

As imunidades parlamentares são classificadas em absolutas e relativas, sendo as últimas divididas em formal ou processual. As imunidades absolutas protegem os parlamentares contra crimes relacionados ao exercício de suas funções, enquanto as imunidades relativas protegem contra crimes não relacionados.

### Conceitos
- **Imunidade Absoluta**: Protege o parlamentar contra crimes relacionados ao exercício de suas funções
- **Imunidade Relativa**: Protege o parlamentar contra crimes não relacionados ao exercício de suas funções
- **Forno por Prerrogativa de Função**: Foro exclusivo para julgamento de crimes praticados no exercício da função e em razão dela

### Referências legais
- Art. 53, caput, da CF
- Súmula N STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre imunidades absolutas e relativas
- Entender a noção de foro por prerrogativa de função
- Conhecer as limitações da imunidade parlamentar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.67 (1)", "page_number": 67, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 53, caput, da CF", "Súmula N STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T13:04:39.630890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=67", "doc_key": "e9c439c545c61070cc450a8574102d77"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', 'fa8686e7c8c75b60826cdab158f50a7d6ae28af89f1bd4a93808fcf9b86b15fa'),
  ('cpiuris2025::e584ad5c43dd994b84ec71153d07b029', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Imunidade Parlamentar', '## Imunidade Parlamentar

A imunidade parlamentar não abrange atos praticados em local distinto e não há nexo de causalidade com o desempenho das funções do mandato parlamentar.

### Conceitos
- **Imunidade Parlamentar**: Conceito jurídico que protege os atos de um parlamentar
- **Nexo de Causalidade**: Relação necessária entre o ato e a função do mandato parlamentar
- **Foro por Prerrogativa de Função**: Direito que concede privilégio de julgamento em determinados crimes

### Referências legais
- Art. 37, Caput, da CF/88; Art. 52, § 3º, da CF/88

### Jurisprudência
- RE 606451
- STF Plenário AP 937 QO/RJ

### Dicas de prova
- Distinção entre atos praticados em local distinto e nexo de causalidade
- Interpretação restritiva das normas constitucionais que estabelecem hipóteses de foro por prerrogativa de função', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.67 (2)", "page_number": 67, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 37, Caput, da CF/88; Art. 52, § 3º, da CF/88"], "jurisprudence": ["RE 606451", "STF Plenário AP 937 QO/RJ"], "confidence": 0.8, "extracted_at": "2026-05-27T13:05:05.252985+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=67", "doc_key": "e584ad5c43dd994b84ec71153d07b029"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '42eb6f114c87f078e547fe3d628e60737739ab38bb083fde93b9e2f1ec5d976f'),
  ('cpiuris2025::a47514e9de72b2b2c7a8a5053b0d2ecf', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Imunidade relativa à prisão', '## Imunidade relativa à prisão

A imunidade relativa à prisão protege os parlamentares contra coerções pelas suas atuações e opiniões, proibindo sua prisão salvo em flagrante de crime inafiançável.

### Conceitos
- **Imunidade**: direito que protege uma pessoa contra coerção por parte de outra
- **Incoercibilidade**: impossibilidade de ser coagido a fazer algo contra a vontade
- **Prisão cautelar**: medida provisória para garantir a ordem pública e segurança
- **Flagrante**: situação em que uma pessoa é capturada no ato de cometer um crime
- **Crime inafiançável**: crime que não pode ser compensado com fiança

### Referências legais
- Art. 2º, § 1º, da Lei n.º 12.850/2013

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre imunidade e incoercibilidade
- Conheça as exceções à imunidade relativa à prisão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf", "source_ref": "IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Direito Penal (Parte Geral)", "legal_refs": ["Art. 2º, § 1º, da Lei n.º 12.850/2013"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T13:05:48.337236+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Penal (Parte Geral) - Vol. 05 - 2025.pdf#page=68", "doc_key": "a47514e9de72b2b2c7a8a5053b0d2ecf"}'::jsonb, '{"materia": "Direito Penal (Parte Geral)"}'::jsonb, 'cp_iuris_2025', '27ec9269dc8216423dfb878c7dd59ce51af1d434d3b179e8ca523aa93014faf0'),
  ('cpiuris2025::ecf55b203382a97687b3cfa7ecd59e6e', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Prisão de Parlamentar Devedor de Alimentos', '## Prisão de Parlamentar Devedor de Alimentos

Discute-se a possibilidade de prisão de um parlamentar devedor de alimentos, com divergências entre as correntes jurídicas.

### Conceitos
- **Imunidade do Parlamentar**: Conceito jurídico que protege o parlamentar de atos de privação da liberdade
- **Prisão em Flagrante**: Mêscla entre prisão e julgamento, onde o preso é detido imediatamente após a comissão do crime
- **Forno Privilegiado**: Direito que concede ao juiz competência para julgar um caso, geralmente em casos de crimes políticos

### Referências legais
- Art. 37, Caput, da Constituição Federal
- Lei n.º 7.170/1973 (Lei de Segurança Nacional)

### Jurisprudência
- RE 123456
- Tema repetitivo: Imunidade do Parlamentar

### Dicas de prova
- Entenda a imunidade do parlamentar e suas limitações
- Diferencie entre prisão em flagrante e julgamento
