  ('cpiuris2025::bd027b85bd999f5dccad735bdfc93b40', 'doutrina', 'cp_iuris', 'Direito Penal (Parte Geral) — Imunidade Parlamentar', '## Imunidade Parlamentar

A imunidade parlamentar se estende ao processo, mas não impede a instauração do processo. A suspensão processual é apreciada pela Casa Legislativa dentro de 45 dias.

### Conceitos
- **Imunidade Parlamentar**: Direito que protege os parlamentares de serem processados por crimes cometidos após a diplomação
- **Suspensão Processual**: Apreciação da suspensão do processo pela Casa Legislativa dentro de 45 dias
- **Imunidade Relativa ao Processo**: Proteção dos parlamentares contra processamento por crimes cometidos após a diplomação
- **Inquérito Policial**: Investigação realizada pelo Procurador-Geral da República com autorização do STF
- **Testemunha**: Pessoa obrigada a prestar depoimento em um processo

### Referências legais
- Art. 53, § 3º da CF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre imunidade parlamentar e suspensão processual
